  provenanceService?: ProvenanceService;
}

export function createApp(dependencies: AppDependencies = {}) {
  const environment = dependencies.environment ?? loadEnvironment();
  const verifyAccessToken =
    dependencies.verifyAccessToken ?? createSupabaseTokenVerifier(environment);
  const synchronizeAccount = dependencies.synchronizeAccount ?? createAccountSynchronizer();
  const publicReadService = dependencies.publicReadService ?? createPublicReadService();
  const fixtureStatisticsService =
    dependencies.fixtureStatisticsService ?? createFixtureStatisticsService();
  const participantAggregatesService =
    dependencies.participantAggregatesService ?? createParticipantAggregatesService();
  const submissionService = dependencies.submissionService ?? createSubmissionService();
  const submitterAccessService =
    dependencies.submitterAccessService ?? createSubmitterAccessService();
  const accountDeletionService =
    dependencies.accountDeletionService ??
    (environment.SUPABASE_SECRET_KEY
      ? createAccountDeletionService(
          createSupabaseAdminUserDeleter({
            SUPABASE_URL: environment.SUPABASE_URL,
            SUPABASE_SECRET_KEY: environment.SUPABASE_SECRET_KEY,
          }),
        )
      : createUnavailableAccountDeletionService());
  const adminService =
    dependencies.adminService ??
    createAdminService(
      undefined,
      environment.SUPABASE_SECRET_KEY
        ? createSupabaseAdminUserEmailReader({
            SUPABASE_URL: environment.SUPABASE_URL,
            SUPABASE_SECRET_KEY: environment.SUPABASE_SECRET_KEY,
          })
        : undefined,
    );
  const weatherService = dependencies.weatherService ?? new WeatherService();
  const fixtureWeatherService =
    dependencies.fixtureWeatherService ?? createFixtureWeatherService(weatherService);
  const batchPayloadStorageService =
    dependencies.batchPayloadStorageService ??
    (environment.NODE_ENV === 'production'
      ? createAzureObjectStorageComposition(environment).batchPayloadStorageService
      : undefined);
  const batchService = dependencies.batchService ?? createBatchService(batchPayloadStorageService);
  const apiConsumerRepository =
    dependencies.apiConsumerRepository ?? createLazyApiConsumerRepository();
  const apiConsumerService =
    dependencies.apiConsumerService ?? createApiConsumerService(apiConsumerRepository);
  const datasetReleaseService = dependencies.datasetReleaseService ?? createDatasetReleaseService();
  const provenanceService =
    dependencies.provenanceService ?? createProvenanceService(fixtureStatisticsService);
  const allowedOrigins = environment.CORS_ORIGINS.split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);

  const app = express();

  if (batchPayloadStorageService) {
    app.locals.batchPayloadStorageService = batchPayloadStorageService;
  }

  app.disable('x-powered-by');
  app.use(helmet());
  app.use(
    cors({
      origin: allowedOrigins,
      credentials: true,
    }),
  );
  app.use(
    express.json({
      limit: '1mb',
      type: (request) => {
        if (request.url?.startsWith(`${API_BASE_PATH}/batches`)) {
          return false;
        }

        const contentType = request.headers['content-type'] ?? '';
        return /^application\/(?:[a-z0-9!#$&^_.+-]+\+)?json(?:;|$)/i.test(contentType);
      },
    }),
  );
  app.use(
    pinoHttp({
      autoLogging: process.env.NODE_ENV !== 'test',
      redact: ['req.headers.authorization', 'req.headers.x-api-key'],
    }),
  );

  app.use(API_BASE_PATH, (_request, response, next) => {
    response.setHeader('API-Version', CURRENT_API_VERSION);
    next();
  });

  app.use(`${API_BASE_PATH}/health`, healthRouter);
  app.use(`${API_BASE_PATH}/auth`, createAuthRouter(verifyAccessToken, synchronizeAccount));
  app.use(API_BASE_PATH, createFixtureStatisticsRouter(fixtureStatisticsService));
  app.use(API_BASE_PATH, createParticipantAggregatesRouter(participantAggregatesService));
  app.use(
    API_BASE_PATH,
    createSubmissionRouter(verifyAccessToken, synchronizeAccount, submissionService),
  );
  app.use(API_BASE_PATH, createBatchRouter(verifyAccessToken, synchronizeAccount, batchService));
  app.use(
    API_BASE_PATH,
    createProvenanceRouter(verifyAccessToken, synchronizeAccount, provenanceService),
  );
  app.use(
    API_BASE_PATH,
    createSubmitterAccessRouter(verifyAccessToken, synchronizeAccount, submitterAccessService),
  );
  app.use(
    API_BASE_PATH,
    createAccountDeletionRouter(verifyAccessToken, synchronizeAccount, accountDeletionService),
  );
  app.use(API_BASE_PATH, createAdminRouter(verifyAccessToken, synchronizeAccount, adminService));
  app.use(
    API_BASE_PATH,
    createApiConsumerRouter(verifyAccessToken, synchronizeAccount, apiConsumerService),
  );
  app.use(API_BASE_PATH, createConsumerRouter(publicReadService, apiConsumerRepository));
  app.use(
    API_BASE_PATH,
    createDatasetReleaseRouter(verifyAccessToken, synchronizeAccount, datasetReleaseService),
  );
  app.use(API_BASE_PATH, createPublicReadRouter(publicReadService, fixtureStatisticsService));
  app.use(API_BASE_PATH, createWeatherRouter(weatherService, fixtureWeatherService));

  app.use('/api', (request, response, next) => {
    const requestedVersion = request.path.split('/').filter(Boolean)[0];

    if (requestedVersion !== undefined && /^v\d+$/.test(requestedVersion)) {
      response.status(404).json({
        error: {
          code: 'UNSUPPORTED_API_VERSION',
          message: `API version ${requestedVersion} is not supported. Use ${API_BASE_PATH}.`,
        },
      });
      return;
    }

    next();
  });

  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
}
import { DefaultAzureCredential, type TokenCredential } from '@azure/identity';
import { BlobServiceClient, type ContainerClient } from '@azure/storage-blob';

import type { Environment } from '../../config/env';
import { AzureBlobObjectStore } from './azure-blob-object-store';
import { BatchPayloadStorageService } from './batch-payload-storage.service';
import type { ObjectStore } from './object-store';
import { createStoredObjectRepository } from './stored-object.repository';

type AzureStorageEnvironment = Pick<
  Environment,
  'AZURE_STORAGE_ACCOUNT_NAME' | 'AZURE_STORAGE_CONTAINER_NAME'
>;

export interface AzureObjectStorageComposition {
  blobEndpoint: string;
  containerName: string;
  objectStore: ObjectStore;
  batchPayloadStorageService: BatchPayloadStorageService;
}

export interface AzureObjectStorageCompositionFactories {
  createCredential(): TokenCredential;
  createBlobServiceClient(
    endpoint: string,
    credential: TokenCredential,
  ): {
    getContainerClient(containerName: string): ContainerClient;
  };
  createObjectStore(containerClient: ContainerClient): ObjectStore;
  createBatchPayloadStorageService(objectStore: ObjectStore): BatchPayloadStorageService;
}

export function createDefaultAzureCredential(): DefaultAzureCredential {
  return new DefaultAzureCredential();
}

const defaultFactories: AzureObjectStorageCompositionFactories = {
  createCredential: createDefaultAzureCredential,
  createBlobServiceClient: (endpoint, credential) => new BlobServiceClient(endpoint, credential),
  createObjectStore: (containerClient) => new AzureBlobObjectStore(containerClient),
  createBatchPayloadStorageService: (objectStore) =>
    new BatchPayloadStorageService(
      objectStore,
      createStoredObjectRepository(),
      async (requesterId, object) => requesterId === object.ownerId,
    ),
};

/** Production composition for private Azure Blob Storage; performs no Azure I/O at startup. */
export function createAzureObjectStorageComposition(
  environment: AzureStorageEnvironment,
  factories: AzureObjectStorageCompositionFactories = defaultFactories,
): AzureObjectStorageComposition {
  const accountName = environment.AZURE_STORAGE_ACCOUNT_NAME;
  const containerName = environment.AZURE_STORAGE_CONTAINER_NAME;

  if (!accountName) {
    throw new Error('Azure storage account name is required for production object storage.');
  }
  if (!containerName) {
    throw new Error('Azure storage container name is required for production object storage.');
  }

  const blobEndpoint = `https://${accountName}.blob.core.windows.net`;
  const credential = factories.createCredential();
  const blobServiceClient = factories.createBlobServiceClient(blobEndpoint, credential);
  const containerClient = blobServiceClient.getContainerClient(containerName);
  const objectStore = factories.createObjectStore(containerClient);
  const batchPayloadStorageService = factories.createBatchPayloadStorageService(objectStore);

  return {
    blobEndpoint,
    containerName,
    objectStore,
    batchPayloadStorageService,
  };
}

export * from './errors';
export * from './pool';
export * from './query';
export * from './transaction';

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

import { Pool, type PoolConfig } from 'pg';

import { DatabaseAccessError, translateDatabaseError } from './errors';

let applicationPool: Pool | undefined;

interface DatabasePoolOptions {
  connectionString: string;
  ssl?: PoolConfig['ssl'];
  max?: number;
}

function createDatabasePool(options: DatabasePoolOptions): Pool {
  const pool = new Pool({
    connectionString: options.connectionString,
    ssl: options.ssl,
    max: options.max ?? 10,
    min: 1,
    // A request that cannot obtain a connection must fail rather than wait
    // forever: an unbounded wait never rejects, so the interface never leaves
    // its loading state and the reader is given no error and no retry.
    // evidence/validation/issue-369-idle-backend-latency.md records this bound
    // as part of that fix; it was lost from the change that landed.
    connectionTimeoutMillis: 10_000,
    idleTimeoutMillis: 30_000,
  });

  pool.on('error', () => {
    // Do not expose the raw driver error because it may contain
    // database or connection details.
    console.error('Unexpected PostgreSQL pool error.');
  });

  return pool;
}

function loadApplicationDatabaseUrl(): string {
  const connectionString = process.env.DATABASE_URL;

  if (!connectionString?.trim()) {
    throw new DatabaseAccessError('DATABASE_UNAVAILABLE', 'DATABASE_URL is not configured.');
  }

  return connectionString;
}

function loadApplicationTlsConfiguration(connectionString: string): PoolConfig['ssl'] {
  const hostname = new URL(connectionString).hostname;
  if (hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '::1') {
    return undefined;
  }

  const certificatePath = resolve(__dirname, '../../certs/supabase-ca.crt');

  return {
    rejectUnauthorized: true,
    ca: readFileSync(certificatePath, 'utf8'),
  };
}

export function getDatabasePool(): Pool {
  if (!applicationPool) {
    const connectionString = loadApplicationDatabaseUrl();
    applicationPool = createDatabasePool({
      connectionString,
      ssl: loadApplicationTlsConfiguration(connectionString),
    });
  }

  return applicationPool;
}

export async function closeDatabasePool(): Promise<void> {
  if (!applicationPool) {
    return;
  }

  const pool = applicationPool;
  applicationPool = undefined;

  try {
    await pool.end();
  } catch (error) {
    throw translateDatabaseError(error);
  }
}

import request from 'supertest';
import { Pool } from 'pg';
import { afterAll, beforeAll, describe, expect, test } from 'vitest';

import { executeQuery } from '../../src/database';
import { createPublicEventRepository } from '../../src/modules/events/event.repository';
import { createDatasetReleaseRepository } from '../../src/modules/dataset-releases/dataset-release.repository';
import { createDatasetReleaseService } from '../../src/modules/dataset-releases/dataset-release.service';
import { createPublicReadService } from '../../src/modules/public-read/public-read.service';
import { assertSafeTestDatabase } from '../../scripts/test-database-safety';
import { createTestApp } from '../test-app';

interface TestRecords {
  competitionId: string;
  fixtureId: string;
  firstInningsId: string;
  secondInningsId: string;
  firstCompetitorId: string;
  secondCompetitorId: string;
  strikerId: string;
  nonStrikerId: string;
  bowlerId: string;
  orderedEventIds: string[];
  submissionIds: string[];
}

const sourcePrefix = `public-events-test-${process.pid}`;

describe.sequential('public events database API', () => {
  let pool: Pool | undefined;
  let records: TestRecords | undefined;

  function databasePool(): Pool {
    if (!pool) {
      throw new Error('Test database pool has not been initialised.');
    }

    return pool;
  }

  function testRecords(): TestRecords {
    if (!records) {
      throw new Error('Public event test records have not been initialised.');
    }

    return records;
  }

  async function insertSubmission(status: 'accepted' | 'pending' | 'rejected'): Promise<string> {
    const result = await executeQuery<{ submissionId: string }>(
      databasePool(),
      `
        INSERT INTO submission (status, rejection_detail)
        VALUES (
          $1::submission_status,
          CASE WHEN $1::text = 'rejected' THEN '{}'::jsonb ELSE NULL END
        )
        RETURNING submission_id::text AS "submissionId"
      `,
      [status],
    );

    return result.rows[0].submissionId;
  }

  async function insertDelivery(options: {
    inningsId: string;
    overNumber: number;
    positionInOver: number;
    sequenceNumber: number;
    submissionId: string;
    strikerId: string;
    nonStrikerId: string;
    bowlerId: string;
  }): Promise<string> {
    const result = await executeQuery<{ eventId: string }>(
      databasePool(),
      `
        INSERT INTO delivery (
          innings_id,
          over_number,
          position_in_over,
          innings_sequence,
          ball_number,
          striker_id,
          non_striker_id,
          bowler_id,
          runs_off_bat,
          runs_extras,
          runs_total,
          submission_id
        )
        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 1, 0, 1, $9)
        RETURNING delivery_id::text AS "eventId"
      `,
      [
        options.inningsId,
        options.overNumber,
        options.positionInOver,
        options.sequenceNumber,
        `${options.overNumber}.${options.sequenceNumber}`,
        options.strikerId,
        options.nonStrikerId,
        options.bowlerId,
        options.submissionId,
      ],
    );

    return result.rows[0].eventId;
  }

  beforeAll(async () => {
    const databaseUrl = assertSafeTestDatabase(
      process.env.DATABASE_URL_TEST,
      process.env.DATABASE_URL,
      process.env.NODE_ENV,
    );
    pool = new Pool({ connectionString: databaseUrl.toString() });

    const competition = await executeQuery<{ competitionId: string }>(
      pool,
      `
        INSERT INTO competition (name)
        VALUES ($1)
        RETURNING competition_id::text AS "competitionId"
      `,
      [`${sourcePrefix}-competition`],
    );
    const firstCompetitor = await executeQuery<{ competitorId: string }>(
      pool,
      `
        INSERT INTO team (name)
        VALUES ($1)
        RETURNING team_id::text AS "competitorId"
      `,
      [`${sourcePrefix}-first-team`],
    );
    const secondCompetitor = await executeQuery<{ competitorId: string }>(
      pool,
      `
        INSERT INTO team (name)
        VALUES ($1)
        RETURNING team_id::text AS "competitorId"
      `,
      [`${sourcePrefix}-second-team`],
    );

    async function insertPerson(role: string): Promise<string> {
      const result = await executeQuery<{ participantId: string }>(
        databasePool(),
        `
          INSERT INTO person (source_ref, display_name)
          VALUES ($1, $2)
          RETURNING person_id::text AS "participantId"
        `,
        [`${sourcePrefix}-${role}`, `${role} ${sourcePrefix}`],
      );

      return result.rows[0].participantId;
    }

    const strikerId = await insertPerson('striker');
    const nonStrikerId = await insertPerson('non-striker');
    const bowlerId = await insertPerson('bowler');
    const competitionId = competition.rows[0].competitionId;
    const firstCompetitorId = firstCompetitor.rows[0].competitorId;
    const secondCompetitorId = secondCompetitor.rows[0].competitorId;

    const fixture = await executeQuery<{ fixtureId: string }>(
      pool,
      `
        INSERT INTO fixture (
          source_ref,
          competition_id,
          season,
          match_type,
          team_type,
          gender,
          balls_per_over,
          start_date,
          end_date,
          outcome,
          source_version,
          source_revision
        )
        VALUES ($1, $2, '2026', 'T20', 'club', 'mixed', 6, CURRENT_DATE,
                CURRENT_DATE, 'tie', '1.0', 1)
        RETURNING fixture_id::text AS "fixtureId"
      `,
      [`${sourcePrefix}-fixture`, competitionId],
    );
    const fixtureId = fixture.rows[0].fixtureId;

    await executeQuery(
      pool,
      `
        INSERT INTO fixture_team (fixture_id, team_id, ordinal)
        VALUES ($1, $2, 1), ($1, $3, 2)
      `,
      [fixtureId, firstCompetitorId, secondCompetitorId],
    );
    await executeQuery(
      pool,
      `
        INSERT INTO fixture_squad (fixture_id, person_id, team_id)
        VALUES ($1, $2, $5), ($1, $3, $5), ($1, $4, $6)
      `,
      [fixtureId, strikerId, nonStrikerId, bowlerId, firstCompetitorId, secondCompetitorId],
    );

    const firstInnings = await executeQuery<{ inningsId: string }>(
      pool,
      `
        INSERT INTO innings (fixture_id, ordinal, batting_team_id)
        VALUES ($1, 0, $2)
        RETURNING innings_id::text AS "inningsId"
      `,
      [fixtureId, firstCompetitorId],
    );
    const secondInnings = await executeQuery<{ inningsId: string }>(
      pool,
      `
        INSERT INTO innings (fixture_id, ordinal, batting_team_id)
        VALUES ($1, 1, $2)
        RETURNING innings_id::text AS "inningsId"
      `,
      [fixtureId, secondCompetitorId],
    );
    const firstInningsId = firstInnings.rows[0].inningsId;
    const secondInningsId = secondInnings.rows[0].inningsId;
    const acceptedSubmissionId = await insertSubmission('accepted');
    const pendingSubmissionId = await insertSubmission('pending');
    const rejectedSubmissionId = await insertSubmission('rejected');
    const commonParticipants = {
      strikerId,
      nonStrikerId,
      bowlerId,
    };

    const thirdEventId = await insertDelivery({
      inningsId: secondInningsId,
      overNumber: 0,
      positionInOver: 0,
      sequenceNumber: 1,
      submissionId: acceptedSubmissionId,
      ...commonParticipants,
    });
    const secondEventId = await insertDelivery({
      inningsId: firstInningsId,
      overNumber: 0,
      positionInOver: 1,
      sequenceNumber: 2,
      submissionId: acceptedSubmissionId,
      ...commonParticipants,
    });
    const firstEventId = await insertDelivery({
      inningsId: firstInningsId,
      overNumber: 0,
      positionInOver: 0,
      sequenceNumber: 1,
      submissionId: acceptedSubmissionId,
      ...commonParticipants,
    });

    await insertDelivery({
      inningsId: firstInningsId,
      overNumber: 0,
      positionInOver: 2,
      sequenceNumber: 3,
      submissionId: pendingSubmissionId,
      ...commonParticipants,
    });
    await insertDelivery({
      inningsId: firstInningsId,
      overNumber: 0,
      positionInOver: 3,
      sequenceNumber: 4,
      submissionId: rejectedSubmissionId,
      ...commonParticipants,
    });

    const wicket = await executeQuery<{ wicketId: string }>(
      pool,
      `
        INSERT INTO delivery_wicket (delivery_id, ordinal, kind, source_kind, player_out_id)
        VALUES ($1, 0, 'caught', 'caught', $2)
        RETURNING wicket_id::text AS "wicketId"
      `,
      [secondEventId, strikerId],
    );
    await executeQuery(
      pool,
      `
        INSERT INTO delivery_wicket_fielder (wicket_id, ordinal, person_id)
        VALUES ($1, 0, $2)
      `,
      [wicket.rows[0].wicketId, bowlerId],
    );

    records = {
      competitionId,
      fixtureId,
      firstInningsId,
      secondInningsId,
      firstCompetitorId,
      secondCompetitorId,
      strikerId,
      nonStrikerId,
      bowlerId,
      orderedEventIds: [firstEventId, secondEventId, thirdEventId],
      submissionIds: [acceptedSubmissionId, pendingSubmissionId, rejectedSubmissionId],
    };
  });

  afterAll(async () => {
    if (!pool || !records) {
      return;
    }

    await executeQuery(pool, 'DELETE FROM delivery WHERE innings_id IN ($1, $2)', [
      records.firstInningsId,
      records.secondInningsId,
    ]);
    await executeQuery(pool, 'DELETE FROM submission WHERE submission_id = ANY($1::bigint[])', [
      records.submissionIds,
    ]);
    await executeQuery(pool, 'DELETE FROM fixture WHERE fixture_id = $1', [records.fixtureId]);
    await executeQuery(pool, 'DELETE FROM competition WHERE competition_id = $1', [
      records.competitionId,
    ]);
    await executeQuery(pool, 'DELETE FROM team WHERE team_id IN ($1, $2)', [
      records.firstCompetitorId,
      records.secondCompetitorId,
    ]);
    await executeQuery(pool, 'DELETE FROM person WHERE person_id IN ($1, $2, $3)', [
      records.strikerId,
      records.nonStrikerId,
      records.bowlerId,
    ]);
    await pool.end();
  });

  function app() {
    const repository = createPublicEventRepository(databasePool());
    return createTestApp(undefined, createPublicReadService(repository));
  }

  test('lists only accepted events anonymously in deterministic cursor order', async () => {
    const current = testRecords();
    const firstPage = await request(app())
      .get(`/api/v1/fixtures/${current.fixtureId}/events?limit=2`)
      .expect(200);

    expect(firstPage.body.data.map((event: { eventId: string }) => event.eventId)).toEqual(
      current.orderedEventIds.slice(0, 2),
    );
    expect(firstPage.body.pagination.nextCursor).toEqual(expect.any(String));

    const secondPage = await request(app())
      .get(`/api/v1/fixtures/${current.fixtureId}/events`)
      .query({
        limit: 2,
        cursor: firstPage.body.pagination.nextCursor,
      })
      .expect(200);

    expect(secondPage.body.data.map((event: { eventId: string }) => event.eventId)).toEqual(
      current.orderedEventIds.slice(2),
    );
    expect(secondPage.body.pagination.nextCursor).toBeNull();
  });

  test('filters accepted events and returns privacy-safe stable resources', async () => {
    const current = testRecords();
    const response = await request(app())
      .get(`/api/v1/fixtures/${current.fixtureId}/events`)
      .query({
        inningsId: current.firstInningsId,
        competitorId: current.firstCompetitorId,
        participantId: current.bowlerId,
        overNumber: 0,
        wicketKind: 'caught',
      })
      .expect(200);

    expect(response.body.data).toHaveLength(1);
    expect(response.body.data[0]).toMatchObject({
      eventId: current.orderedEventIds[1],
      fixtureId: current.fixtureId,
      competitionId: current.competitionId,
      competitionName: `${sourcePrefix}-competition`,
      inningsId: current.firstInningsId,
      battingCompetitorId: current.firstCompetitorId,
      battingCompetitorName: `${sourcePrefix}-first-team`,
      bowlingCompetitorId: current.secondCompetitorId,
      bowlingCompetitorName: `${sourcePrefix}-second-team`,
      strikerParticipantId: current.strikerId,
      strikerParticipantName: `striker ${sourcePrefix}`,
      nonStrikerParticipantId: current.nonStrikerId,
      nonStrikerParticipantName: `non-striker ${sourcePrefix}`,
      bowlerParticipantId: current.bowlerId,
      bowlerParticipantName: `bowler ${sourcePrefix}`,
      wickets: [
        {
          kind: 'caught',
          playerOutParticipantId: current.strikerId,
          playerOutParticipantName: `striker ${sourcePrefix}`,
          fielders: [
            {
              participantId: current.bowlerId,
              participantName: `bowler ${sourcePrefix}`,
              isSubstitute: false,
            },
          ],
        },
      ],
    });
    expect(response.body.data[0]).not.toHaveProperty('submissionId');
    expect(response.body.data[0]).not.toHaveProperty('submittedBy');
    expect(response.body.data[0]).not.toHaveProperty('revision');
    expect(response.body.data[0]).not.toHaveProperty('recordedAt');

    const detail = await request(app())
      .get(`/api/v1/fixtures/${current.fixtureId}/events/${current.orderedEventIds[1]}`)
      .expect(200);
    expect(detail.body.data.eventId).toBe(current.orderedEventIds[1]);
  });

  test('creates and retrieves an immutable checksum-backed published-data release', async () => {
    const client = await databasePool().connect();
    try {
      await client.query('BEGIN');
      const service = createDatasetReleaseService(createDatasetReleaseRepository(client));
      const version = `${sourcePrefix}-release`;

      const first = await service.createRelease({ version });
      const again = await service.createRelease({ version });
      const artifact = await service.getArtifact(version);

      const parsedArtifact = JSON.parse(artifact!);
      expect(first.eventCount).toBe(parsedArtifact.events.length);
      expect(first).toEqual(again);
      expect(artifact).toContain(`"eventId":"${testRecords().orderedEventIds[0]}"`);
      expect(await service.getRelease(version)).toEqual(first);
      expect(await service.listReleases()).toContainEqual(first);
      await expect(
        client.query('UPDATE dataset_release SET event_count = 0 WHERE version = $1', [version]),
      ).rejects.toThrow('Dataset releases are immutable');
    } finally {
      await client.query('ROLLBACK');
      client.release();
    }
  });
});

