import type { QueryResult, QueryResultRow } from 'pg';

import { translateDatabaseError } from './errors';

export interface QueryExecutor {
  query<Row extends QueryResultRow = QueryResultRow>(
    text: string,
    values?: unknown[],
  ): Promise<QueryResult<Row>>;
}

export async function executeQuery<Row extends QueryResultRow>(
  executor: QueryExecutor,
  text: string,
  values: unknown[] = [],
): Promise<QueryResult<Row>> {
  try {
    return await executor.query<Row>(text, values);
  } catch (error) {
    throw translateDatabaseError(error);
  }
}

import type { Pool, PoolClient } from 'pg';

import { DatabaseAccessError, translateDatabaseError } from './errors';
import { executeQuery } from './query';

export async function withTransaction<T>(
  pool: Pool,
  operation: (client: PoolClient) => Promise<T>,
): Promise<T> {
  let client: PoolClient;

  try {
    client = await pool.connect();
  } catch (error) {
    throw translateDatabaseError(error);
  }

  let transactionStarted = false;

  try {
    await executeQuery(client, 'BEGIN');
    transactionStarted = true;

    const result = await operation(client);

    await executeQuery(client, 'COMMIT');
    transactionStarted = false;

    return result;
  } catch (error) {
    if (transactionStarted) {
      try {
        await executeQuery(client, 'ROLLBACK');
      } catch (rollbackError) {
        throw new DatabaseAccessError(
          'DATABASE_TRANSACTION_FAILED',
          'The database transaction failed and rollback could not be confirmed.',
          {
            cause: new AggregateError([error, rollbackError]),
          },
        );
      }
    }

    throw error;
  } finally {
    client.release();
  }
}

import { createHash, randomUUID } from 'node:crypto';
import { basename } from 'node:path/posix';
import { Transform, type Readable, type TransformCallback } from 'node:stream';

import {
  ObjectSizeLimitError,
  ObjectStorageError,
  StoredObjectAccessDeniedError,
  StoredObjectUnavailableError,
  type ObjectStore,
} from './object-store';
import type { StoredObjectRecord, StoredObjectRepository } from './stored-object.repository';

export const MAX_BATCH_PAYLOAD_BYTES = 50 * 1024 * 1024;
const BATCH_PAYLOAD_RETENTION_DAYS = 90;
const BATCH_PAYLOAD_MEDIA_TYPES = ['application/json', 'text/csv', 'application/x-ndjson'] as const;

type BatchPayloadMediaType = (typeof BATCH_PAYLOAD_MEDIA_TYPES)[number];

export interface UploadBatchPayloadInput {
  ownerId: string;
  originalFilename: string;
  mediaType: BatchPayloadMediaType;
  source: Readable;
}

export type AuthorizeStoredObjectRead = (
  requesterId: string,
  object: StoredObjectRecord,
) => Promise<boolean>;

class MeasuringTransform extends Transform {
  private readonly hash = createHash('sha256');
  byteSize = 0;

  constructor(private readonly limitBytes: number) {
    super();
  }

  override _transform(
    chunk: Buffer | string,
    encoding: BufferEncoding,
    callback: TransformCallback,
  ): void {
    const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk, encoding);
    this.byteSize += bytes.length;
    if (this.byteSize > this.limitBytes) {
      callback(new ObjectSizeLimitError(this.limitBytes));
      return;
    }
    this.hash.update(bytes);
    callback(null, bytes);
  }

  checksum(): string {
    return this.hash.digest('hex');
  }
}

function safeFilename(submittedFilename: string): string {
  const filename = basename(submittedFilename.replaceAll('\\', '/')).trim();
  const hasControlCharacter = [...filename].some((character) => {
    const codePoint = character.codePointAt(0) ?? 0;
    return codePoint <= 31 || codePoint === 127;
  });
  if (!filename || filename.length > 255 || hasControlCharacter) {
    throw new ObjectStorageError('The original filename is invalid.');
  }
  return filename;
}

function storageKey(objectId: string, now: Date): string {
  const year = now.getUTCFullYear();
  const month = String(now.getUTCMonth() + 1).padStart(2, '0');
  const day = String(now.getUTCDate()).padStart(2, '0');
  return `incoming/batch-source/${year}/${month}/${day}/${objectId}`;
}

function limitedDownload(source: Readable, limitBytes: number): Readable {
  const limiter = new MeasuringTransform(limitBytes);
  source.once('error', () =>
    limiter.destroy(new ObjectStorageError('The object download failed.')),
  );
  return source.pipe(limiter);
}

export class BatchPayloadStorageService {
  constructor(
    private readonly objectStore: ObjectStore,
    private readonly repository: StoredObjectRepository,
    private readonly authorizeRead: AuthorizeStoredObjectRead,
    private readonly now: () => Date = () => new Date(),
  ) {}

  async upload(input: UploadBatchPayloadInput): Promise<StoredObjectRecord> {
    const objectId = randomUUID();
    const originalFilename = safeFilename(input.originalFilename);
    const createdAt = this.now();
    const key = storageKey(objectId, createdAt);
    const measuringStream = new MeasuringTransform(MAX_BATCH_PAYLOAD_BYTES);
    input.source.once('error', (error) => measuringStream.destroy(error));
    input.source.pipe(measuringStream);

    try {
      const storedVersion = await this.objectStore.write(key, measuringStream);
      if (measuringStream.byteSize === 0) {
        throw new ObjectStorageError('The uploaded object is empty.');
      }

      const retentionExpiresAt = new Date(createdAt);
      retentionExpiresAt.setUTCDate(retentionExpiresAt.getUTCDate() + BATCH_PAYLOAD_RETENTION_DAYS);

      return await this.repository.create({
        objectId,
        ownerId: input.ownerId,
        originalFilename,
        mediaType: input.mediaType,
        byteSize: measuringStream.byteSize,
        sha256: measuringStream.checksum(),
        storageKey: key,
        providerVersionId: storedVersion.versionId,
        retentionExpiresAt: retentionExpiresAt.toISOString(),
      });
    } catch (error) {
      input.source.destroy();
      measuringStream.destroy();
      try {
        await this.objectStore.delete(key);
      } catch {
        // The caller receives a safe failure. Reconciliation can retry an orphan cleanup.
      }

      if (error instanceof ObjectSizeLimitError || error instanceof ObjectStorageError) {
        throw error;
      }
      throw new ObjectStorageError('The object upload failed.');
    }
  }

  async download(
    requesterId: string,
    objectId: string,
    limitBytes = MAX_BATCH_PAYLOAD_BYTES,
  ): Promise<Readable> {
    const object = await this.repository.findById(objectId);
    if (!object || !(await this.authorizeRead(requesterId, object))) {
      throw new StoredObjectAccessDeniedError();
    }
    if (object.retentionState !== 'retained') {
      throw new StoredObjectUnavailableError();
    }
    if (object.byteSize > limitBytes) {
      throw new ObjectSizeLimitError(limitBytes);
    }

    try {
      return limitedDownload(await this.objectStore.read(object.storageKey), limitBytes);
    } catch {
      throw new ObjectStorageError('The object download failed.');
    }
  }

  async expire(objectId: string): Promise<StoredObjectRecord> {
    const object = await this.repository.findById(objectId);
    if (!object) {
      throw new StoredObjectUnavailableError();
    }
    if (object.retentionState === 'expired') {
      return object;
    }

    await this.repository.updateRetentionState(objectId, 'deletion_pending');
    try {
      await this.objectStore.delete(object.storageKey);
      return await this.repository.updateRetentionState(
        objectId,
        'expired',
        this.now().toISOString(),
      );
    } catch {
      await this.repository.updateRetentionState(objectId, 'deletion_failed');
      throw new ObjectStorageError('The retained object could not be expired.');
    }
  }
}

import { createHash, randomUUID } from 'node:crypto';
import { Readable } from 'node:stream';
import { describe, expect, test } from 'vitest';

import {
  BatchPayloadStorageService,
  MAX_BATCH_PAYLOAD_BYTES,
} from '../../src/modules/object-storage/batch-payload-storage.service';
import { FakeObjectStore } from '../../src/modules/object-storage/fake-object-store';
import {
  ObjectSizeLimitError,
  StoredObjectAccessDeniedError,
  StoredObjectUnavailableError,
} from '../../src/modules/object-storage/object-store';
import type {
  CreateStoredObjectInput,
  StoredObjectRecord,
  StoredObjectRepository,
  StoredObjectRetentionState,
} from '../../src/modules/object-storage/stored-object.repository';

class FakeStoredObjectRepository implements StoredObjectRepository {
  readonly records = new Map<string, StoredObjectRecord>();
  failCreate = false;

  async create(input: CreateStoredObjectInput): Promise<StoredObjectRecord> {
    if (this.failCreate) {
      throw new Error('Database unavailable');
    }
    const record: StoredObjectRecord = {
      ...input,
      retentionState: 'retained',
      createdAt: '2026-09-02T12:00:00.000Z',
      deletedAt: null,
    };
    this.records.set(record.objectId, record);
    return record;
  }

  async findById(objectId: string): Promise<StoredObjectRecord | null> {
    return this.records.get(objectId) ?? null;
  }

  async updateRetentionState(
    objectId: string,
    retentionState: StoredObjectRetentionState,
    deletedAt: string | null = null,
  ): Promise<StoredObjectRecord> {
    const current = this.records.get(objectId);
    if (!current) {
      throw new Error('Missing fake stored object');
    }
    const updated = { ...current, retentionState, deletedAt };
    this.records.set(objectId, updated);
    return updated;
  }
}

async function content(stream: Readable): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of stream) {
    chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  }
  return Buffer.concat(chunks);
}

function service(
  store = new FakeObjectStore(),
  repository = new FakeStoredObjectRepository(),
  authorize = async (requesterId: string, object: StoredObjectRecord) =>
    requesterId === object.ownerId,
) {
  return {
    store,
    repository,
    storage: new BatchPayloadStorageService(
      store,
      repository,
      authorize,
      () => new Date('2026-09-02T12:00:00.000Z'),
    ),
  };
}

describe('batch payload storage', () => {
  test('streams upload bytes, hashes them, and persists safe metadata', async () => {
    const current = service();
    const bytes = Buffer.from('{"contractVersion":"1.0"}');
    const object = await current.storage.upload({
      ownerId: '42',
      originalFilename: '../../season.json',
      mediaType: 'application/json',
      source: Readable.from([bytes.subarray(0, 5), bytes.subarray(5)]),
    });

    expect(object).toMatchObject({
      ownerId: '42',
      originalFilename: 'season.json',
      mediaType: 'application/json',
      byteSize: bytes.length,
      sha256: createHash('sha256').update(bytes).digest('hex'),
      retentionState: 'retained',
      retentionExpiresAt: '2026-12-01T12:00:00.000Z',
    });
    expect(object.storageKey).toMatch(/^incoming\/batch-source\/2026\/09\/02\/[0-9a-f-]{36}$/);
    expect(object.storageKey).not.toContain('season.json');
    await expect(content(await current.store.read(object.storageKey))).resolves.toEqual(bytes);
  });

  test('enforces the upload limit during streaming and cleans the incomplete key', async () => {
    const current = service();
    await expect(
      current.storage.upload({
        ownerId: '42',
        originalFilename: 'season.ndjson',
        mediaType: 'application/x-ndjson',
        source: Readable.from([Buffer.alloc(MAX_BATCH_PAYLOAD_BYTES), Buffer.from('x')]),
      }),
    ).rejects.toBeInstanceOf(ObjectSizeLimitError);

    expect(current.repository.records.size).toBe(0);
    expect(current.store.deletedKeys).toHaveLength(1);
    expect(current.store.has(current.store.deletedKeys[0] ?? '')).toBe(false);
  });

  test('cleans the stored bytes if metadata persistence fails', async () => {
    const current = service();
    current.repository.failCreate = true;

    await expect(
      current.storage.upload({
        ownerId: '42',
        originalFilename: 'season.csv',
        mediaType: 'text/csv',
        source: Readable.from('header\nvalue'),
      }),
    ).rejects.toThrow('The object upload failed.');

    expect(current.store.deletedKeys).toHaveLength(1);
    expect(current.repository.records.size).toBe(0);
  });

  test('cleans an interrupted streamed upload without exposing its contents', async () => {
    const current = service();
    let readCount = 0;
    const interrupted = new Readable({
      read() {
        readCount += 1;
        if (readCount === 1) {
          this.push('private partial payload');
          return;
        }
        this.destroy(new Error('connection reset after private partial payload'));
      },
    });

    await expect(
      current.storage.upload({
        ownerId: '42',
        originalFilename: 'season.json',
        mediaType: 'application/json',
        source: interrupted,
      }),
    ).rejects.toThrow('The object upload failed.');

    expect(current.store.deletedKeys).toHaveLength(1);
    expect(current.repository.records.size).toBe(0);
  });

  test('requires authorization before opening a private download', async () => {
    const current = service();
    const object = await current.storage.upload({
      ownerId: '42',
      originalFilename: 'season.csv',
      mediaType: 'text/csv',
      source: Readable.from('header\nvalue'),
    });

    await expect(current.storage.download('7', object.objectId)).rejects.toBeInstanceOf(
      StoredObjectAccessDeniedError,
    );
    await expect(content(await current.storage.download('42', object.objectId))).resolves.toEqual(
      Buffer.from('header\nvalue'),
    );
  });

  test('replaces provider download details with a credential-safe error', async () => {
    const current = service();
    const object = await current.storage.upload({
      ownerId: '42',
      originalFilename: 'season.csv',
      mediaType: 'text/csv',
      source: Readable.from('header\nvalue'),
    });
    current.store.failNextRead = true;

    await expect(current.storage.download('42', object.objectId)).rejects.toMatchObject({
      message: 'The object download failed.',
    });
  });

  test('enforces a download byte limit even when persisted size metadata is wrong', async () => {
    const current = service();
    const key = `incoming/batch-source/2026/09/02/${randomUUID()}`;
    await current.store.write(key, Readable.from('too many bytes'));
    const object = await current.repository.create({
      objectId: randomUUID(),
      ownerId: '42',
      originalFilename: 'season.csv',
      mediaType: 'text/csv',
      byteSize: 2,
      sha256: 'a'.repeat(64),
      storageKey: key,
      providerVersionId: null,
      retentionExpiresAt: '2026-12-01T12:00:00.000Z',
    });

    await expect(
      content(await current.storage.download('42', object.objectId, 4)),
    ).rejects.toBeInstanceOf(ObjectSizeLimitError);
  });

  test('expires bytes but retains provenance metadata', async () => {
    const current = service();
    const object = await current.storage.upload({
      ownerId: '42',
      originalFilename: 'season.json',
      mediaType: 'application/json',
      source: Readable.from('{}'),
    });

    const expired = await current.storage.expire(object.objectId);

    expect(expired).toMatchObject({
      objectId: object.objectId,
      sha256: object.sha256,
      storageKey: object.storageKey,
      retentionState: 'expired',
      deletedAt: '2026-09-02T12:00:00.000Z',
    });
    expect(current.store.has(object.storageKey)).toBe(false);
    await expect(current.storage.download('42', object.objectId)).rejects.toBeInstanceOf(
      StoredObjectUnavailableError,
    );
  });

  test('records a retryable deletion failure without losing provenance', async () => {
    const current = service();
    const object = await current.storage.upload({
      ownerId: '42',
      originalFilename: 'season.json',
      mediaType: 'application/json',
      source: Readable.from('{}'),
    });
    current.store.failNextDelete = true;

    await expect(current.storage.expire(object.objectId)).rejects.toThrow(
      'The retained object could not be expired.',
    );
    await expect(current.repository.findById(object.objectId)).resolves.toMatchObject({
      retentionState: 'deletion_failed',
      sha256: object.sha256,
    });
  });
});

