import { Readable } from 'node:stream';

import type { ContainerClient } from '@azure/storage-blob';
import { describe, expect, test, vi } from 'vitest';

import { AzureBlobObjectStore } from '../../src/modules/object-storage/azure-blob-object-store';

describe('Azure Blob object-store adapter', () => {
  test('streams to a non-overwriting private container client and returns the version', async () => {
    const getProperties = vi.fn().mockResolvedValue({});
    const uploadStream = vi.fn().mockResolvedValue({ versionId: 'version-2' });
    const getBlockBlobClient = vi.fn().mockReturnValue({ uploadStream });
    const adapter = new AzureBlobObjectStore({
      getProperties,
      getBlockBlobClient,
    } as unknown as ContainerClient);
    const source = Readable.from('payload');

    await expect(adapter.write('generated-key', source)).resolves.toEqual({
      versionId: 'version-2',
    });
    expect(getBlockBlobClient).toHaveBeenCalledWith('generated-key');
    expect(getProperties).toHaveBeenCalledOnce();
    expect(uploadStream).toHaveBeenCalledWith(source, 4 * 1024 * 1024, 4, {
      conditions: { ifNoneMatch: '*' },
    });
  });

  test('returns only a backend stream and performs idempotent snapshot-aware deletion', async () => {
    const getProperties = vi.fn().mockResolvedValue({});
    const body = Readable.from('private payload');
    const download = vi.fn().mockResolvedValue({ readableStreamBody: body });
    const deleteIfExists = vi.fn().mockResolvedValue({ succeeded: true });
    const getBlockBlobClient = vi.fn().mockReturnValue({ download, deleteIfExists });
    const adapter = new AzureBlobObjectStore({
      getProperties,
      getBlockBlobClient,
    } as unknown as ContainerClient);

    await expect(adapter.read('generated-key')).resolves.toBe(body);
    await expect(adapter.delete('generated-key')).resolves.toBeUndefined();
    expect(deleteIfExists).toHaveBeenCalledWith({ deleteSnapshots: 'include' });
    expect(getProperties).toHaveBeenCalledOnce();
  });

  test('refuses to use a container configured for public access', async () => {
    const getBlockBlobClient = vi.fn();
    const adapter = new AzureBlobObjectStore({
      getProperties: vi.fn().mockResolvedValue({ blobPublicAccess: 'container' }),
      getBlockBlobClient,
    } as unknown as ContainerClient);

    await expect(adapter.write('generated-key', Readable.from('payload'))).rejects.toThrow(
      'permits public access',
    );
    expect(getBlockBlobClient).not.toHaveBeenCalled();
  });
});

import { appendFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const DOC_ROOT_FILES = new Set([
  'README.md',
  'CONTRIBUTING.md',
  'SECURITY.md',
  'MIGRATION_GUIDE.md',
  'CLAUDE.md',
  'FILE_TREE.txt',
]);

const FULL_ROOT_FILES = new Set([
  'package.json',
  'package-lock.json',
  'tsconfig.base.json',
  '.eslintrc.cjs',
  '.prettierrc.json',
  '.prettierignore',
  '.dependency-cruiser.cjs',
  '.syncpackrc.json',
  'knip.json',
]);

const DOC_CONFIG_FILES = new Set([
  'mkdocs.yml',
  'requirements-docs.txt',
  'redocly.yaml',
  '.redocly.lint-ignore.yaml',
]);

const EVIDENCE_LIGHTWEIGHT_EXTENSIONS = new Set([
  '.csv',
  '.png',
  '.jpg',
  '.jpeg',
  '.webp',
  '.gif',
  '.pdf',
  '.docx',
  '.zip',
]);

function emptyPlan() {
  return {
    full: false,
    evidence: false,
    docs: false,
    frontend: false,
    backend: false,
    worker: false,
    contracts: false,
    database: false,
    e2e: false,
    e2eFull: false,
    intermediateIngestion: false,
    hygiene: false,
    deployment: false,
    openapi: false,
    coverage: false,
    deployFrontend: false,
    deployBackend: false,
    deployDocs: false,
    needsNpm: false,
  };
}

function markFull(plan) {
  plan.full = true;
  plan.docs = true;
  plan.frontend = true;
  plan.backend = true;
  plan.worker = true;
  plan.contracts = true;
  plan.database = true;
  plan.e2e = true;
  plan.e2eFull = true;
  plan.hygiene = true;
  plan.deployment = true;
  plan.openapi = true;
  plan.needsNpm = true;
}

function isDocumentationPath(file) {
  return (
    file.startsWith('docs/') ||
    DOC_ROOT_FILES.has(file) ||
    DOC_CONFIG_FILES.has(file) ||
    file.endsWith('/README.md') ||
    file.startsWith('.gitea/ISSUE_TEMPLATE/') ||
    file === '.gitea/PULL_REQUEST_TEMPLATE.md'
  );
}

function isEvidenceLightweight(file) {
  return file.startsWith('evidence/') && EVIDENCE_LIGHTWEIGHT_EXTENSIONS.has(path.extname(file));
}

function isIntermediateIngestionPath(file) {
  if (
    [
      'apps/backend/src/modules/batches/',
      'apps/backend/src/modules/object-storage/',
      'apps/backend/src/modules/provenance/',
      'apps/backend/src/modules/submissions/',
      'apps/worker/',
      'packages/batch-processing/',
      'apps/frontend/src/features/reviews/',
      'apps/frontend/src/features/submissions/',
    ].some((prefix) => file.startsWith(prefix))
  ) {
    return true;
  }

  if (
    new Set([
      'apps/backend/src/app.ts',
      'apps/backend/src/modules/statistics/recomputation-dependencies.ts',
      'packages/contracts/src/batches.ts',
      'packages/contracts/src/cricket-delivery-comparison.ts',
      'packages/contracts/src/cricket-validation.ts',
      'packages/contracts/src/provenance.ts',
      'packages/contracts/src/season-upload.ts',
      'packages/contracts/src/submissions.ts',
      'packages/contracts/src/tests/batches.test.ts',
      'packages/contracts/src/tests/provenance.test.ts',
      'packages/contracts/src/tests/season-upload.test.ts',
      'packages/contracts/src/tests/submissions.test.ts',
      'tests/e2e/batch-review-workspace.spec.ts',
      'tests/e2e/corrections.spec.ts',
      'tests/e2e/submissions.spec.ts',
    ]).has(file)
  ) {
    return true;
  }

  if (
    file.startsWith('apps/backend/tests/') &&
    /(?:^|\/)(?:batch|provenance|submission|stored-object)[^/]*\.(?:test|spec)\.ts$/.test(file)
  ) {
    return true;
  }

  return (
    file.startsWith('database/migrations/') &&
    /(?:batch|ingestion|submission|correction|provenance|publication|review|stored-object|reference-mapping|statistics-refresh|fixture-statistics-cache)/i.test(
      file,
    )
  );
}

function applyPath(plan, file) {
  if (!file) return;

  const intermediateIngestion = isIntermediateIngestionPath(file);
  if (intermediateIngestion) plan.intermediateIngestion = true;

  if (file.startsWith('evidence/')) {
    plan.evidence = true;
    if (!isEvidenceLightweight(file)) plan.needsNpm = true;
    return;
  }

  if (isDocumentationPath(file)) {
    plan.docs = true;
    plan.needsNpm = true;

    if (file.startsWith('docs/') || file === 'mkdocs.yml' || file === 'requirements-docs.txt') {
      plan.deployDocs = true;
    }

    if (
      file === 'redocly.yaml' ||
      file === '.redocly.lint-ignore.yaml' ||
      file === 'docs/api/openapi.yaml'
    ) {
      plan.openapi = true;
    }
    return;
  }

  if (FULL_ROOT_FILES.has(file)) {
    markFull(plan);
    if (file === 'package.json' || file === 'package-lock.json') {
      plan.deployFrontend = true;
      plan.deployBackend = true;
      plan.deployDocs = true;
    } else if (file === 'tsconfig.base.json') {
      plan.deployFrontend = true;
      plan.deployBackend = true;
    }
    return;
  }

  if (file === '.gitea/workflows/ci.yml') {
    markFull(plan);
    return;
  }

