    plan.backend = true;
    plan.worker = true;
    plan.database = true;
    plan.deployment = true;
    plan.deployBackend = true;
    plan.hygiene = true;
    plan.needsNpm = true;
    return;
  }

  if (file.startsWith('apps/frontend/')) {
    plan.frontend = true;
    plan.contracts = true;
    plan.hygiene = true;
    plan.needsNpm = true;

    const isFrontendTest = /(?:\.test\.[cm]?[jt]sx?|\/test\/)/.test(file);
    if (!isFrontendTest) {
      plan.e2e = true;
      if (!intermediateIngestion) plan.e2eFull = true;
      plan.deployFrontend = true;
    }
    return;
  }

