import { spawnSync } from 'node:child_process';

const workspaces = {
  frontend: '@sport-analytics/frontend',
  backend: '@sport-analytics/backend',
};

const argumentsToForward = process.argv.slice(2);
const requestedApp = argumentsToForward[0]?.startsWith('-')
  ? 'frontend'
  : (argumentsToForward.shift() ?? 'frontend');

if (!(requestedApp in workspaces)) {
  console.error(`Unknown development app "${requestedApp}". Use "frontend" or "backend".`);
  process.exitCode = 1;
} else {
  const npmCli = process.env.npm_execpath;

  if (!npmCli) {
    console.error('npm_execpath is unavailable. Start this command through npm.');
    process.exitCode = 1;
  } else {
    const result = spawnSync(
      process.execPath,
      [
        npmCli,
        'run',
        'dev',
        `--workspace=${workspaces[requestedApp]}`,
        '--',
        ...argumentsToForward,
      ],
      { stdio: 'inherit' },
    );

    if (result.error) {
      console.error(`Could not start the ${requestedApp} development app: ${result.error.message}`);
      process.exitCode = 1;
    } else {
      process.exitCode = result.status ?? 1;
    }
  }
}

import 'dotenv/config';

import { createApp } from './app';
import { loadEnvironment } from './config/env';
import { closeDatabasePool } from './database';

const environment = loadEnvironment();
const app = createApp({ environment });

const server = app.listen(environment.PORT, () => {
  console.log(`Sport Analytics API listening on port ${environment.PORT}`);
});

let shuttingDown = false;

function closeHttpServer(): Promise<void> {
  return new Promise((resolve, reject) => {
    server.close((error) => {
      if (error) {
        reject(error);
        return;
      }

      resolve();
    });
  });
}

async function shutdown(signal: string): Promise<void> {
  if (shuttingDown) {
    return;
  }

  shuttingDown = true;

  console.log(`${signal} received; shutting down`);

  try {
    await closeHttpServer();
  } catch {
    console.error('Failed to close HTTP server cleanly.');
    process.exitCode = 1;
  }

  try {
    await closeDatabasePool();
  } catch {
    console.error('Failed to close database pool cleanly.');
    process.exitCode = 1;
  }
}

process.on('SIGINT', () => {
  void shutdown('SIGINT');
});

process.on('SIGTERM', () => {
  void shutdown('SIGTERM');
});

import type { ContainerClient } from '@azure/storage-blob';
import { DefaultAzureCredential } from '@azure/identity';
import { describe, expect, test, vi } from 'vitest';

import { createApp } from '../../src/app';
import { AzureBlobObjectStore } from '../../src/modules/object-storage/azure-blob-object-store';
import {
  createAzureObjectStorageComposition,
  createDefaultAzureCredential,
  type AzureObjectStorageCompositionFactories,
} from '../../src/modules/object-storage/azure-object-storage.composition';
import { BatchPayloadStorageService } from '../../src/modules/object-storage/batch-payload-storage.service';

const productionStorageEnvironment = {
  AZURE_STORAGE_ACCOUNT_NAME: 'statsthegameblobdev',
  AZURE_STORAGE_CONTAINER_NAME: 'staged-ingestion',
};

describe('production Azure object-storage composition', () => {
  test('selects the configured HTTPS endpoint and container and injects the Azure adapter', () => {
    const credential = { getToken: vi.fn().mockResolvedValue(null) };
    const containerClient = {} as ContainerClient;
    const payloadStorageService = {} as BatchPayloadStorageService;
    const getContainerClient = vi.fn().mockReturnValue(containerClient);
    const createCredential = vi.fn().mockReturnValue(credential);
    const createBlobServiceClient = vi.fn().mockReturnValue({ getContainerClient });
    const createObjectStore = vi
      .fn()
      .mockImplementation((container) => new AzureBlobObjectStore(container));
    const createBatchPayloadStorageService = vi.fn().mockReturnValue(payloadStorageService);
    const factories: AzureObjectStorageCompositionFactories = {
      createCredential,
      createBlobServiceClient,
      createObjectStore,
      createBatchPayloadStorageService,
    };

    const composition = createAzureObjectStorageComposition(
      productionStorageEnvironment,
      factories,
    );

    expect(createCredential).toHaveBeenCalledOnce();
    expect(createBlobServiceClient).toHaveBeenCalledWith(
      'https://statsthegameblobdev.blob.core.windows.net',
      credential,
    );
    expect(getContainerClient).toHaveBeenCalledWith('staged-ingestion');
    expect(createObjectStore).toHaveBeenCalledWith(containerClient);
    expect(composition.objectStore).toBeInstanceOf(AzureBlobObjectStore);
    expect(createBatchPayloadStorageService).toHaveBeenCalledWith(composition.objectStore);
    expect(composition.batchPayloadStorageService).toBe(payloadStorageService);
  });

  test('uses DefaultAzureCredential for the production credential chain without contacting Azure', () => {
    expect(createDefaultAzureCredential()).toBeInstanceOf(DefaultAzureCredential);
  });

  test('installs the composed payload-storage service in the production application', () => {
    const app = createApp({
      environment: {
        NODE_ENV: 'production',
        PORT: 3000,
        CORS_ORIGINS: 'https://example.invalid',
        SUPABASE_URL: 'https://test-project.supabase.co',
        SUPABASE_PUBLISHABLE_KEY: 'test-publishable-key',
        ...productionStorageEnvironment,
      },
    });

    expect(app.locals.batchPayloadStorageService).toBeInstanceOf(BatchPayloadStorageService);
  });

  test('fails safely when the storage account is absent', () => {
    expect(() =>
      createAzureObjectStorageComposition({
        AZURE_STORAGE_CONTAINER_NAME: 'staged-ingestion',
      }),
    ).toThrow('Azure storage account name is required for production object storage.');
  });

  test('fails safely when the container is absent', () => {
    expect(() =>
      createAzureObjectStorageComposition({
        AZURE_STORAGE_ACCOUNT_NAME: 'statsthegameblobdev',
      }),
    ).toThrow('Azure storage container name is required for production object storage.');
  });
});

import { DefaultAzureCredential, type TokenCredential } from '@azure/identity';
import { BlobServiceClient, type ContainerClient } from '@azure/storage-blob';

import type { Environment } from '../../config/env';
import { AzureBlobObjectStore } from './azure-blob-object-store';
import { BatchPayloadStorageService } from './batch-payload-storage.service';
import type { ObjectStore } from './object-store';
import { createStoredObjectRepository } from './stored-object.repository';

type AzureStorageEnvironment = Pick<
  Environment,
  'AZURE_STORAGE_ACCOUNT_NAME' | 'AZURE_STORAGE_CONTAINER_NAME'
>;

export interface AzureObjectStorageComposition {
  blobEndpoint: string;
  containerName: string;
  objectStore: ObjectStore;
  batchPayloadStorageService: BatchPayloadStorageService;
}

export interface AzureObjectStorageCompositionFactories {
  createCredential(): TokenCredential;
  createBlobServiceClient(
    endpoint: string,
    credential: TokenCredential,
  ): {
    getContainerClient(containerName: string): ContainerClient;
  };
  createObjectStore(containerClient: ContainerClient): ObjectStore;
  createBatchPayloadStorageService(objectStore: ObjectStore): BatchPayloadStorageService;
}

export function createDefaultAzureCredential(): DefaultAzureCredential {
  return new DefaultAzureCredential();
}

const defaultFactories: AzureObjectStorageCompositionFactories = {
  createCredential: createDefaultAzureCredential,
  createBlobServiceClient: (endpoint, credential) => new BlobServiceClient(endpoint, credential),
  createObjectStore: (containerClient) => new AzureBlobObjectStore(containerClient),
  createBatchPayloadStorageService: (objectStore) =>
    new BatchPayloadStorageService(
      objectStore,
      createStoredObjectRepository(),
      async (requesterId, object) => requesterId === object.ownerId,
    ),
};

/** Production composition for private Azure Blob Storage; performs no Azure I/O at startup. */
export function createAzureObjectStorageComposition(
  environment: AzureStorageEnvironment,
  factories: AzureObjectStorageCompositionFactories = defaultFactories,
): AzureObjectStorageComposition {
  const accountName = environment.AZURE_STORAGE_ACCOUNT_NAME;
  const containerName = environment.AZURE_STORAGE_CONTAINER_NAME;

  if (!accountName) {
    throw new Error('Azure storage account name is required for production object storage.');
  }
  if (!containerName) {
    throw new Error('Azure storage container name is required for production object storage.');
  }

  const blobEndpoint = `https://${accountName}.blob.core.windows.net`;
  const credential = factories.createCredential();
  const blobServiceClient = factories.createBlobServiceClient(blobEndpoint, credential);
  const containerClient = blobServiceClient.getContainerClient(containerName);
  const objectStore = factories.createObjectStore(containerClient);
  const batchPayloadStorageService = factories.createBatchPayloadStorageService(objectStore);

  return {
    blobEndpoint,
    containerName,
    objectStore,
    batchPayloadStorageService,
  };
}

