export function createApp(dependencies: AppDependencies = {}) {
  const environment = dependencies.environment ?? loadEnvironment();
  const verifyAccessToken =
    dependencies.verifyAccessToken ?? createSupabaseTokenVerifier(environment);
  const synchronizeAccount = dependencies.synchronizeAccount ?? createAccountSynchronizer();
  const publicReadService = dependencies.publicReadService ?? createPublicReadService();
  const fixtureStatisticsService =
    dependencies.fixtureStatisticsService ?? createFixtureStatisticsService();
  const participantAggregatesService =
    dependencies.participantAggregatesService ?? createParticipantAggregatesService();
  const submissionService = dependencies.submissionService ?? createSubmissionService();
  const submitterAccessService =
    dependencies.submitterAccessService ?? createSubmitterAccessService();
  const accountDeletionService =
    dependencies.accountDeletionService ??
    (environment.SUPABASE_SECRET_KEY
      ? createAccountDeletionService(
          createSupabaseAdminUserDeleter({
            SUPABASE_URL: environment.SUPABASE_URL,
            SUPABASE_SECRET_KEY: environment.SUPABASE_SECRET_KEY,
          }),
        )
      : createUnavailableAccountDeletionService());
  const adminService =
    dependencies.adminService ??
    createAdminService(
      undefined,
      environment.SUPABASE_SECRET_KEY
        ? createSupabaseAdminUserEmailReader({
            SUPABASE_URL: environment.SUPABASE_URL,
            SUPABASE_SECRET_KEY: environment.SUPABASE_SECRET_KEY,
          })
        : undefined,
    );
  const weatherService = dependencies.weatherService ?? new WeatherService();
  const fixtureWeatherService =
    dependencies.fixtureWeatherService ?? createFixtureWeatherService(weatherService);
  const objectStorageComposition =
    environment.NODE_ENV === 'production'
      ? createAzureObjectStorageComposition(environment)
      : undefined;
  const objectStore = dependencies.objectStore ?? objectStorageComposition?.objectStore;
  const batchPayloadStorageService =
    dependencies.batchPayloadStorageService ?? objectStorageComposition?.batchPayloadStorageService;
  const batchService = dependencies.batchService ?? createBatchService(batchPayloadStorageService);
  const apiConsumerRepository =
    dependencies.apiConsumerRepository ?? createLazyApiConsumerRepository();
  const apiConsumerService =
    dependencies.apiConsumerService ?? createApiConsumerService(apiConsumerRepository);
  const datasetReleaseService =
    dependencies.datasetReleaseService ?? createDatasetReleaseService(undefined, objectStore);
  const provenanceService =
    dependencies.provenanceService ?? createProvenanceService(fixtureStatisticsService);
  const allowedOrigins = environment.CORS_ORIGINS.split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);

  const app = express();

  if (batchPayloadStorageService) {
    app.locals.batchPayloadStorageService = batchPayloadStorageService;
  }

  app.disable('x-powered-by');
  app.use(helmet());
  app.use(
    cors({
      origin: allowedOrigins,
      credentials: true,
    }),
  );
  app.use(
    express.json({
      limit: '1mb',
      type: (request) => {
        if (request.url?.startsWith(`${API_BASE_PATH}/batches`)) {
          return false;
        }

        const contentType = request.headers['content-type'] ?? '';
        return /^application\/(?:[a-z0-9!#$&^_.+-]+\+)?json(?:;|$)/i.test(contentType);
      },
    }),
  );
  app.use(
    pinoHttp({
      autoLogging: process.env.NODE_ENV !== 'test',
      redact: ['req.headers.authorization', 'req.headers.x-api-key'],
    }),
  );

  app.use(API_BASE_PATH, (_request, response, next) => {
    response.setHeader('API-Version', CURRENT_API_VERSION);
    next();
  });

  app.use(`${API_BASE_PATH}/health`, healthRouter);
  app.use(`${API_BASE_PATH}/auth`, createAuthRouter(verifyAccessToken, synchronizeAccount));
  app.use(API_BASE_PATH, createFixtureStatisticsRouter(fixtureStatisticsService));
  app.use(API_BASE_PATH, createParticipantAggregatesRouter(participantAggregatesService));
  app.use(
    API_BASE_PATH,
    createSubmissionRouter(verifyAccessToken, synchronizeAccount, submissionService),
  );
  app.use(API_BASE_PATH, createBatchRouter(verifyAccessToken, synchronizeAccount, batchService));
  app.use(
    API_BASE_PATH,
    createProvenanceRouter(verifyAccessToken, synchronizeAccount, provenanceService),
  );
  app.use(
    API_BASE_PATH,
    createSubmitterAccessRouter(verifyAccessToken, synchronizeAccount, submitterAccessService),
  );
  app.use(
    API_BASE_PATH,
    createAccountDeletionRouter(verifyAccessToken, synchronizeAccount, accountDeletionService),
  );
  app.use(API_BASE_PATH, createAdminRouter(verifyAccessToken, synchronizeAccount, adminService));
  app.use(
    API_BASE_PATH,
    createApiConsumerRouter(verifyAccessToken, synchronizeAccount, apiConsumerService),
  );
  app.use(API_BASE_PATH, createConsumerRouter(publicReadService, apiConsumerRepository));
  app.use(
    API_BASE_PATH,
    createDatasetReleaseRouter(verifyAccessToken, synchronizeAccount, datasetReleaseService),
  );
  app.use(API_BASE_PATH, createPublicReadRouter(publicReadService, fixtureStatisticsService));
  app.use(API_BASE_PATH, createWeatherRouter(weatherService, fixtureWeatherService));

  app.use('/api', (request, response, next) => {
    const requestedVersion = request.path.split('/').filter(Boolean)[0];

    if (requestedVersion !== undefined && /^v\d+$/.test(requestedVersion)) {
      response.status(404).json({
        error: {
          code: 'UNSUPPORTED_API_VERSION',
          message: `API version ${requestedVersion} is not supported. Use ${API_BASE_PATH}.`,
        },
      });
      return;
    }

    next();
  });

  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
}

import { spawn } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { smokeCheck } from './smoke-check-deployment.mjs';

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const artifactEntryPoint = path.join(
  repositoryRoot,
  '.deployment',
  'backend',
  'apps',
  'backend',
  'dist',
  'index.js',
);
const port = 3100;
let processOutput = '';

const backend = spawn(process.execPath, [artifactEntryPoint], {
  cwd: repositoryRoot,
  env: {
    ...process.env,
    AZURE_STORAGE_ACCOUNT_NAME: 'deploymentstorage',
    AZURE_STORAGE_CONTAINER_NAME: 'deployment-smoke-check',
    CORS_ORIGINS: `http://127.0.0.1:${port}`,
    NODE_ENV: 'production',
    PORT: String(port),
    SUPABASE_PUBLISHABLE_KEY: 'deployment-smoke-check-key',
    SUPABASE_URL: 'https://example.invalid',
  },
  stdio: ['ignore', 'pipe', 'pipe'],
});

for (const stream of [backend.stdout, backend.stderr]) {
  stream.setEncoding('utf8');
  stream.on('data', (chunk) => {
    processOutput += chunk;
  });
}

const backendExited = new Promise((_, reject) => {
  backend.once('error', (error) => reject(error));
  backend.once('exit', (code, signal) => {
    reject(
      new Error(
        `Backend artifact exited before the health check passed (code ${code ?? 'none'}, signal ${signal ?? 'none'}).`,
      ),
    );
  });
});

async function stopBackend() {
  if (backend.exitCode !== null) {
    return;
  }

  backend.kill('SIGTERM');
  await Promise.race([
    new Promise((resolve) => backend.once('exit', resolve)),
    new Promise((resolve) => setTimeout(resolve, 5_000)),
  ]);

  if (backend.exitCode === null) {
    backend.kill('SIGKILL');
  }
}

try {
  await Promise.race([
    smokeCheck({
      attempts: 20,
      delayMs: 1_000,
      expectedText: 'sport-analytics-api',
      label: 'backend deployment artifact',
      timeoutMs: 5_000,
      url: `http://127.0.0.1:${port}/api/v1/health`,
    }),
    backendExited,
  ]);
} catch (error) {
  const output = processOutput.trim();

  if (output) {
    console.error(`[smoke] Backend artifact process output:\n${output}`);
  }

  throw error;
} finally {
  await stopBackend();
}

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

const ciWorkflow = readFileSync('.gitea/workflows/ci.yml', 'utf8');
const manualBackendWorkflow = readFileSync('.gitea/workflows/deploy-backend.yml', 'utf8');
const backendDeployScript = readFileSync('scripts/deploy-backend-azure.py', 'utf8');
const backendArtifactSmokeCheck = readFileSync('scripts/smoke-check-backend-artifact.mjs', 'utf8');

function automaticBackendJob() {
  const marker = '\n  deploy_backend:';
  const start = ciWorkflow.indexOf(marker);
  assert.notEqual(start, -1, 'automatic backend deployment job must exist in CI');
  const end = ciWorkflow.indexOf('\n  deploy_docs:', start);
  return end === -1 ? ciWorkflow.slice(start) : ciWorkflow.slice(start, end);
}

test('automatic backend deployment waits for validated main quality and production-impact routing', () => {
  const job = automaticBackendJob();

  assert.match(job, /needs:\s*\n\s*- plan\s*\n\s*- quality/);
  assert.match(job, /github\.event_name == 'push'/);
  assert.match(job, /github\.ref == 'refs\/heads\/main'/);
  assert.match(job, /needs\.plan\.outputs\.deployBackend == 'true'/);
});

test('automatic backend deployment avoids duplicate authoritative test suites', () => {
  const job = automaticBackendJob();

  assert.doesNotMatch(job, /npm run test:unit/);
  assert.doesNotMatch(job, /npm run test:api/);
  assert.doesNotMatch(job, /npm run typecheck/);
  assert.doesNotMatch(job, /npm run lint/);
  assert.match(job, /npm run build --workspace=@sport-analytics\/backend/);
  assert.match(job, /npm run deploy:prepare:backend/);
  assert.match(job, /smoke-check-backend-artifact\.mjs/);
  assert.match(job, /python3 scripts\/deploy-backend-azure\.py/);
  assert.match(job, /api\/v1\/health/);
  assert.match(job, /api\/v1\/competitions\?limit=1/);
});

test('standalone backend deployment workflow is manual recovery only and shares deployment mechanics', () => {
  assert.match(manualBackendWorkflow, /workflow_dispatch:/);
  assert.doesNotMatch(manualBackendWorkflow, /\n\s*push:/);
  assert.doesNotMatch(manualBackendWorkflow, /npm run test:unit/);
  assert.doesNotMatch(manualBackendWorkflow, /npm run test:api/);
  assert.match(manualBackendWorkflow, /python3 scripts\/deploy-backend-azure\.py/);
});

test('shared Azure backend deploy script retains ZIP creation, credential redaction and Kudu status checks', () => {
  assert.match(backendDeployScript, /zipfile\.ZIP_DEFLATED/);
  assert.match(backendDeployScript, /AZURE_BACKEND_PUBLISH_PROFILE/);
  assert.match(backendDeployScript, /def redact\(value\):/);
  assert.match(backendDeployScript, /Azure accepted the ZIP\. Waiting for deployment/);
