import { randomUUID } from 'node:crypto';
import { createWriteStream } from 'node:fs';
import { link, mkdir, open, unlink } from 'node:fs/promises';
import path from 'node:path';
import type { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';

import { ObjectStorageError, type ObjectStore } from './object-store';

const STORAGE_KEY_SEGMENT = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

function isMissingFile(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    (error as NodeJS.ErrnoException).code === 'ENOENT'
  );
}

/** Development-only object storage that atomically publishes streamed files below one root. */
export class FilesystemObjectStore implements ObjectStore {
  private readonly root: string;

  constructor(root: string) {
    if (!root.trim()) {
      throw new ObjectStorageError('Filesystem object storage root is required.');
    }
    this.root = path.resolve(root);
  }

  async write(storageKey: string, source: Readable) {
    const target = this.resolveStorageKey(storageKey);
    const parent = path.dirname(target);
    const temporary = path.join(parent, `.${path.basename(target)}.${randomUUID()}.tmp`);
    let published = false;

    try {
      await mkdir(parent, { recursive: true });
      await pipeline(source, createWriteStream(temporary, { flags: 'wx' }));
      await link(temporary, target);
      published = true;
      await unlink(temporary);
      return { versionId: null };
    } catch (error) {
      source.destroy();
      await unlink(temporary).catch(() => undefined);
      if (published) {
        await unlink(target).catch(() => undefined);
      }
      if (error instanceof ObjectStorageError) {
        throw error;
      }
      throw new ObjectStorageError('The filesystem object write failed.');
    }
  }

  async read(storageKey: string) {
    const target = this.resolveStorageKey(storageKey);

    try {
      const file = await open(target, 'r');
      return file.createReadStream();
    } catch {
      throw new ObjectStorageError('The filesystem object is unavailable.');
    }
  }

  async delete(storageKey: string) {
    const target = this.resolveStorageKey(storageKey);

    try {
      await unlink(target);
    } catch (error) {
      if (isMissingFile(error)) {
        return;
      }
      throw new ObjectStorageError('The filesystem object could not be deleted.');
    }
  }

  private resolveStorageKey(storageKey: string): string {
    if (
      !storageKey ||
      storageKey.includes('\\') ||
      path.isAbsolute(storageKey) ||
      path.win32.isAbsolute(storageKey)
    ) {
      throw new ObjectStorageError('The object storage key is invalid.');
    }

    const segments = storageKey.split('/');
    if (
      segments.some(
        (segment) => segment === '.' || segment === '..' || !STORAGE_KEY_SEGMENT.test(segment),
      )
    ) {
      throw new ObjectStorageError('The object storage key is invalid.');
    }

    const target = path.resolve(this.root, ...segments);
    const relative = path.relative(this.root, target);
    if (!relative || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative)) {
      throw new ObjectStorageError('The object storage key is invalid.');
    }
    return target;
  }
}

import type { Environment } from '../../config/env';
import {
  createAzureObjectStorageComposition,
  type AzureObjectStorageComposition,
} from './azure-object-storage.composition';
import type { BatchPayloadStorageService } from './batch-payload-storage.service';
import { FilesystemObjectStore } from './filesystem-object-store';
import type { ObjectStore } from './object-store';

export interface ObjectStorageComposition {
  objectStore: ObjectStore;
  batchPayloadStorageService?: BatchPayloadStorageService;
}

export interface ObjectStorageCompositionFactories {
  createAzure(environment: Environment): AzureObjectStorageComposition;
  createFilesystem(root: string): ObjectStore;
}

const defaultFactories: ObjectStorageCompositionFactories = {
  createAzure: createAzureObjectStorageComposition,
  createFilesystem: (root) => new FilesystemObjectStore(root),
};

/** Selects an explicit provider without allowing production to fall back to local storage. */
export function createObjectStorageComposition(
  environment: Environment,
  factories: ObjectStorageCompositionFactories = defaultFactories,
): ObjectStorageComposition | undefined {
  if (!environment.OBJECT_STORAGE_PROVIDER) {
    if (environment.NODE_ENV === 'production') {
      throw new Error('Object storage provider is required in production.');
    }
    return undefined;
  }

  if (environment.OBJECT_STORAGE_PROVIDER === 'azure') {
    return factories.createAzure(environment);
  }

  if (environment.NODE_ENV === 'production') {
    throw new Error('Filesystem object storage is not permitted in production.');
  }
  if (!environment.OBJECT_STORAGE_FILESYSTEM_ROOT) {
    throw new Error('Filesystem object storage root is required for the filesystem provider.');
  }

  return {
    objectStore: factories.createFilesystem(environment.OBJECT_STORAGE_FILESYSTEM_ROOT),
  };
}

