  d.extra_noballs AS "noBalls",
  d.extra_byes AS byes,
  d.extra_legbyes AS "legByes",
  d.extra_penalty AS penalty,
  COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'kind', wicket.kind,
        'playerOutId', wicket.player_out_id::text,
        'fielders', COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
