            { name: 'OUTBOX_CLAIM_TTL_MS', value: '30000' }
            { name: 'OUTBOX_BATCH_SIZE', value: '20' }
            { name: 'BATCH_CHUNK_SIZE', value: '500' }
            { name: 'BATCH_LEASE_MS', value: '120000' }
            { name: 'DATABASE_URL', secretRef: 'database-url' }
