interface StoredReferenceCandidate {
  canonicalId: string;
  label: string;
  outOfScope?: boolean;
}

interface StoredReferenceOutcome {
  referencePath: string;
  entityType: BatchReferenceEntityType;
  state: 'resolved' | 'ambiguous' | 'unresolved' | 'invalid';
  submittedReference: unknown;
  candidates: StoredReferenceCandidate[];
  reason: string | null;
}

function candidateReference(
  batchReference: string,
  itemOrdinal: number,
  referencePath: string,
  canonicalId: string,
) {
  const bytes = createHash('sha256')
    .update(`${batchReference}\0${String(itemOrdinal)}\0${referencePath}\0${canonicalId}`)
    .digest()
    .subarray(0, 16);
  bytes[6] = (bytes[6]! & 0x0f) | 0x50;
  bytes[8] = (bytes[8]! & 0x3f) | 0x80;
  const value = bytes.toString('hex');
  return `${value.slice(0, 8)}-${value.slice(8, 12)}-${value.slice(12, 16)}-${value.slice(16, 20)}-${value.slice(20)}`;
}

function storedOutcomes(value: unknown): StoredReferenceOutcome[] {
  const results: StoredReferenceOutcome[] = [];
  function visit(candidate: unknown) {
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) return;
    const record = candidate as Record<string, unknown>;
    if (
      typeof record.referencePath === 'string' &&
      ['competition', 'team', 'fixture', 'innings', 'participant'].includes(
        String(record.entityType),
      ) &&
      ['resolved', 'ambiguous', 'unresolved', 'invalid'].includes(String(record.state)) &&
      Array.isArray(record.candidates)
    ) {
      const candidates = record.candidates.flatMap((entry): StoredReferenceCandidate[] => {
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return [];
        const item = entry as Record<string, unknown>;
        return typeof item.canonicalId === 'string' && typeof item.label === 'string'
          ? [
              {
                canonicalId: item.canonicalId,
                label: item.label,
                ...(item.outOfScope === true ? { outOfScope: true } : {}),
              },
            ]
          : [];
      });
      results.push({
        referencePath: record.referencePath,
        entityType: record.entityType as BatchReferenceEntityType,
        state: record.state as StoredReferenceOutcome['state'],
        submittedReference: record.submittedReference,
        candidates,
        reason: typeof record.reason === 'string' ? record.reason : null,
      });
      return;
    }
    for (const nested of Object.values(record)) visit(nested);
  }
  visit(value);
  return results;
}

function reportReferenceResolutions(
  record: BatchReportItemRecord,
  batchReference: string,
  competitionId: string,
) {
  const paths = new Set<string>();
  return storedOutcomes(record.resolvedReferences).flatMap((outcome) => {
    if (outcome.state === 'resolved' || paths.has(outcome.referencePath)) return [];
    paths.add(outcome.referencePath);
    const candidates = outcome.candidates
      .filter(
        (candidate) =>
          !candidate.outOfScope &&
          (outcome.entityType !== 'competition' || candidate.canonicalId === competitionId),
      )
      .map((candidate) => ({
        candidateReference: candidateReference(
          batchReference,
          record.ordinal,
          outcome.referencePath,
          candidate.canonicalId,
        ),
        label: candidate.label,
      }));
    return [
      {
        referencePath: outcome.referencePath,
        entityType: outcome.entityType,
        state: outcome.state,
        submittedReference: outcome.submittedReference,
        reason: outcome.reason,
        requiredAction:
          candidates.length > 0 ? ('select_candidate' as const) : ('contact_reviewer' as const),
        candidates,
      },
    ];
  });
}

function receipt(batch: {
  batchReference: string;
  state: 'received' | 'stored' | string;
  createdAt: string;
}): BatchReceiptResponse {
  return {
    data: {
      batchReference: batch.batchReference,
      status: batch.state === 'received' ? 'received' : 'stored',
      statusUrl: `${API_BASE_PATH}/batches/${batch.batchReference}`,
      receivedAt: batch.createdAt,
    },
  };
}

function sourceLocation(record: BatchReportItemRecord) {
  const value = record.sourceLocation;
  return value && !Array.isArray(value) && typeof value === 'object' ? value : {};
}

function reportContext(record: BatchReportItemRecord) {
  const event = record.sourceIdentity;
  const cricketPosition =
    record.overNumber === null || record.positionInOver === null
      ? `source item ${record.ordinal + 1}`
      : `over ${record.overNumber}, delivery ${record.positionInOver}`;
  return {
    eventReference: event,
    fixtureId: record.fixtureId ?? null,
    fixtureLabel: record.fixtureLabel ?? null,
    inningsId: record.inningsId,
    overNumber: record.overNumber,
    positionInOver: record.positionInOver,
    description:
      record.operation === 'correction' && record.correctsSourceIdentity
        ? `Correction event ${event ?? `source item ${record.ordinal + 1}`} targets ${record.correctsSourceIdentity} at ${cricketPosition}.`
        : event
          ? `Event ${event} at ${cricketPosition}.`
          : `Cricket event at ${cricketPosition}.`,
  };
}

function reportLocation(
  record: BatchReportItemRecord,
  error?: BatchReportItemRecord['errors'][number],
) {
  const source = sourceLocation(record);
  const rowNumber = error?.rowNumber ?? source.rowNumber;
  return {
    filePath: error?.filePath ?? (typeof source.filePath === 'string' ? source.filePath : null),
    sheetName: typeof source.sheetName === 'string' ? source.sheetName : null,
    rowNumber: typeof rowNumber === 'number' && rowNumber > 0 ? rowNumber : null,
    jsonPath: error?.fieldPath ?? (typeof source.jsonPath === 'string' ? source.jsonPath : null),
    ordinal: record.ordinal,
  };
}

function reportOutcome(record: BatchReportItemRecord): BatchReportItem['outcome'] {
  if (
    record.rejectionCode?.includes('CONFLICT') ||
    record.errors.some((e) => e.ruleCode.includes('CONFLICT'))
  ) {
    return 'conflicting';
  }
  if (
    record.state === 'duplicate_skipped' ||
    record.errors.some((e) => e.ruleCode === 'DUPLICATE_BATCH_ITEM')
  ) {
    return 'duplicate';
  }
  if (record.referenceResolutionState && record.referenceResolutionState !== 'resolved') {
    return 'unresolved';
  }
  if (record.state === 'pending') return 'pending';
  if (record.state === 'rejected' || record.errors.length > 0 || record.state === null) {
    return 'rejected';
  }
  return 'accepted';
}

function reportPublishedConflict(
  record: BatchReportItemRecord,
): BatchReportItem['publishedConflict'] {
  if (record.rejectionCode !== 'PUBLISHED_DELIVERY_CONFLICT') return null;
  const detail = record.rejectionDetail;
  if (!detail || Array.isArray(detail) || typeof detail !== 'object') return null;
  const existingDeliveryId = detail.existingDeliveryId;
  const differences = detail.differences;
  if (
    typeof existingDeliveryId !== 'string' ||
    !Array.isArray(differences) ||
    differences.length === 0
  ) {
    return null;
  }
  const safeDifferences = differences.flatMap((value) => {
    if (!value || Array.isArray(value) || typeof value !== 'object') return [];
    const fieldPath = value.fieldPath;
    if (typeof fieldPath !== 'string' || fieldPath.length === 0) return [];
    return [
      {
        fieldPath,
        submittedValue: value.submittedValue,
        publishedValue: value.publishedValue,
      },
    ];
  });
  if (safeDifferences.length === 0) return null;
  const existingSourceEventId = record.publishedConflictSourceEventId ?? null;
  return {
    existingDeliveryId,
    existingSourceEventId,
    // Legacy published deliveries can initialise immutable lineage lazily
    // when a reviewer explicitly approves a correction.
    correctionPermitted: true,
    differences: safeDifferences,
  };
}

function mapReportItem(
  record: BatchReportItemRecord,
  batchReference: string,
  competitionId: string,
): BatchReportItem {
  const context = reportContext(record);
  return {
    ordinal: record.ordinal,
    outcome: reportOutcome(record),
    location: reportLocation(record),
    context,
    stagedRecordId: record.batchItemId,
    acceptedRecordId: record.publishedEventId,
    operation: record.operation ?? 'upsert',
    correctionTarget:
      record.operation === 'correction' && record.correctsSourceIdentity
        ? {
            sourceEventId: record.correctsSourceIdentity,
            resolvedDeliveryId: record.correctionTargetDeliveryId,
          }
        : null,
    publishedConflict: reportPublishedConflict(record),
    referenceResolutions: reportReferenceResolutions(record, batchReference, competitionId),
    errors: record.errors.map((error) => ({
      ruleCode: error.ruleCode,
      message: error.message,
      location: reportLocation(record, error),
      context,
    })),
  };
}

function decodeCursor<T>(value: string | undefined, schema: z.ZodType<T>): T | undefined {
  try {
    return readCursor(value, schema);
  } catch (error) {
    if (error instanceof InvalidCursorError)
      throw new BatchInputError('The pagination cursor is invalid.');
    throw error;
  }
}

export function createBatchService(
  storage?: BatchPayloadStorageService,
  repository: BatchRepository = createBatchRepository(),
): BatchService {
  function canReviewBatch(account: ApplicationAccount): boolean {
    return account.role === 'admin';
  }

  async function findAuthorizedBatch(account: ApplicationAccount, reference: string) {
    const batch = await repository.findBatchByReference(reference);
    const canInspect =
      batch && (batch.submitterId === account.accountId || canReviewBatch(account));
    if (!batch || !canInspect) {
      throw new BatchForbiddenError();
    }
    return batch;
  }

  async function status(batch: BatchRecord): Promise<BatchStatus> {
    const [progress, counts, review] = await Promise.all([
      repository.getBatchProgress(batch.batchId),
      repository.getBatchCounts(batch.batchId),
      repository.getLatestReviewDecision(batch.batchId),
    ]);
    return {
      batchReference: batch.batchReference,
      competitionId: batch.competitionId,
      status: batch.state,
      statusUrl: `${API_BASE_PATH}/batches/${batch.batchReference}`,
      receivedAt: batch.createdAt,
      updatedAt: batch.updatedAt,
      source: {
        fileName: batch.sourceFileName,
        checksum: batch.source?.checksum.toLowerCase() ?? null,
        packageVersion: batch.packageVersion,
        submitter: {
          accountId: batch.submitterId,
          displayName: batch.submitterDisplayName,
        },
      },
      progress,
      counts,
      review: review
        ? {
            decision: review.decision,
            actor: {
              accountId: review.actorId,
              displayName: review.actorDisplayName,
            },
            decidedAt: review.decidedAt,
            reason: review.reason,
          }
        : null,
    };
  }

  async function listPage(
    query: BatchListQuery,
    scope: { submitterId?: string } = {},
  ): Promise<BatchListResponse> {
    const cursor = decodeCursor(query.cursor, batchListCursorSchema);
    const records = await repository.listBatches({
      ...scope,
      ...(query.status ? { status: query.status } : {}),
      ...(cursor ? { beforeCreatedAt: cursor.createdAt, beforeBatchId: cursor.batchId } : {}),
      limit: query.limit + 1,
    });
    const page = records.slice(0, query.limit);
    return {
      data: await Promise.all(page.map(status)),
      pagination: {
        nextCursor:
          records.length > query.limit && page.length > 0
            ? createCursor({
                createdAt: page.at(-1)!.createdAt,
                batchId: page.at(-1)!.batchId,
              })
            : null,
      },
    };
  }

  return {
    async receive(account, metadata, source) {
      if (!canSubmitToCompetition(account, metadata.competitionId)) {
        source.destroy();
        throw new BatchForbiddenError();
      }
      if (!storage) {
        source.destroy();
        throw new ObjectStorageError('Batch payload storage is not configured.');
      }

      let object;
      try {
        object = await storage.upload({
          ownerId: account.accountId,
          originalFilename: metadata.fileName,
          mediaType: metadata.mediaType,
          source,
        });
        const outcome = await repository.createOrFindBatchAndQueueValidation({
          batchReference: randomUUID(),
          submitterId: account.accountId,
          competitionId: metadata.competitionId,
          idempotencyKey: metadata.idempotencyKey,
          packageVersion: metadata.packageVersion,
          source: {
            checksum: object.sha256,
            uri: `stored-object:${object.objectId}`,
            sizeBytes: object.byteSize,
          },
          state: 'stored',
        });
        if (outcome.activeLimitReached) {
          throw new BatchConflictError('The submitter already has three active batches.');
        }
        if (!outcome.batch) throw new Error('Batch receipt returned no result.');
        if (!outcome.created && outcome.batch.source?.checksum !== object.sha256) {
          throw new BatchConflictError(
            'The Idempotency-Key is already associated with different batch content.',
          );
        }
        return receipt(outcome.batch);
      } catch (error) {
        // A storage record is retained for reconciliable provenance, but no batch row is created
        // unless its source was completely stored and recorded.
        if (error instanceof ObjectSizeLimitError || error instanceof ObjectStorageError) {
          throw error;
        }
        throw error;
      }
    },

    async getStatus(account, reference) {
      return { data: await status(await findAuthorizedBatch(account, reference)) };
    },

    async list(account, query) {
      return listPage(
        query,
        account.role === 'admin' && query.status === 'awaiting_review'
          ? {}
          : { submitterId: account.accountId },
      );
    },

    async listForAdmin(account, query) {
      if (!canReviewBatch(account)) throw new BatchForbiddenError();
      return listPage(query);
    },

    async getReport(account, reference, query) {
      const batch = await findAuthorizedBatch(account, reference);
      const cursor = decodeCursor(query.cursor, batchReportCursorSchema);
      if (cursor && cursor.batchReference !== reference) {
        throw new BatchInputError('The pagination cursor is invalid for this batch.');
      }
      const [records, acceptedRecords] = await Promise.all([
        repository.listBatchReportItems(batch.batchId, {
          ...(cursor ? { afterOrdinal: cursor.ordinal } : {}),
          limit: query.limit + 1,
        }),
        repository.listBatchReportItems(batch.batchId, { acceptedOnly: true, limit: 15 }),
      ]);
      const page = records.slice(0, query.limit);
      const [batchStatus, errorGroups, blockingValidationErrors, resolution, fixtureSummaries] =
        await Promise.all([
          status(batch),
          repository.listBatchRuleGroups(batch.batchId),
          repository.countBlockingValidationErrors(batch.batchId),
          repository.getBatchResolutionCounts(batch.batchId),
          repository.listBatchFixtureSummaries(batch.batchId),
        ]);
      const blockingReasons: string[] = [];
      if (blockingValidationErrors > 0) blockingReasons.push('Blocking validation errors remain.');
      if (batchStatus.counts.conflicting > 0) blockingReasons.push('Conflicting records remain.');
      if (resolution.ambiguous > 0) blockingReasons.push('Ambiguous references remain.');
      if (resolution.unresolved > 0) blockingReasons.push('Unresolved references remain.');
      if (resolution.invalid > 0) blockingReasons.push('Invalid references remain.');
      return {
        data: {
          batch: batchStatus,
          errorGroups,
          reviewSummary: {
            validation: {
              accepted: batchStatus.counts.accepted,
              rejected: batchStatus.counts.rejected,
              blockingErrors: blockingValidationErrors,
              duplicate: batchStatus.counts.duplicate,
              conflicting: batchStatus.counts.conflicting,
            },
            resolution,
            approvalBlocked: blockingReasons.length > 0,
            blockingReasons,
          },
          fixtureSummaries,
          acceptedSamples: acceptedRecords
            .filter((record) => reportOutcome(record) === 'accepted')
            .slice(0, 15)
            .map((record) => mapReportItem(record, reference, batch.competitionId)),
          items: page.map((record) => mapReportItem(record, reference, batch.competitionId)),
          pagination: {
            nextCursor:
              records.length > query.limit && page.length > 0
                ? createCursor({ batchReference: reference, ordinal: page.at(-1)!.ordinal })
                : null,
          },
          downloadUrl: `${API_BASE_PATH}/batches/${reference}/report/download`,
        },
      };
    },

    async downloadReport(account, reference) {
      const batch = await findAuthorizedBatch(account, reference);
      const items: BatchReportItem[] = [];
      let afterOrdinal: number | undefined;
      for (;;) {
        const page = await repository.listBatchReportItems(batch.batchId, {
          ...(afterOrdinal === undefined ? {} : { afterOrdinal }),
          limit: 1000,
        });
        items.push(...page.map((record) => mapReportItem(record, reference, batch.competitionId)));
        if (page.length < 1000) break;
        afterOrdinal = page.at(-1)!.ordinal;
      }
      const [batchStatus, errorGroups, blockingValidationErrors, resolution, fixtureSummaries] =
        await Promise.all([
          status(batch),
          repository.listBatchRuleGroups(batch.batchId),
          repository.countBlockingValidationErrors(batch.batchId),
          repository.getBatchResolutionCounts(batch.batchId),
          repository.listBatchFixtureSummaries(batch.batchId),
        ]);
      const blockingReasons = [
        ...(blockingValidationErrors > 0 ? ['Blocking validation errors remain.'] : []),
        ...(batchStatus.counts.conflicting > 0 ? ['Conflicting records remain.'] : []),
        ...(resolution.ambiguous > 0 ? ['Ambiguous references remain.'] : []),
        ...(resolution.unresolved > 0 ? ['Unresolved references remain.'] : []),
        ...(resolution.invalid > 0 ? ['Invalid references remain.'] : []),
      ];
      return {
        data: {
          batch: batchStatus,
          errorGroups,
          reviewSummary: {
            validation: {
              accepted: batchStatus.counts.accepted,
              rejected: batchStatus.counts.rejected,
              blockingErrors: blockingValidationErrors,
              duplicate: batchStatus.counts.duplicate,
              conflicting: batchStatus.counts.conflicting,
            },
            resolution,
            approvalBlocked: blockingReasons.length > 0,
            blockingReasons,
          },
          fixtureSummaries,
          acceptedSamples: items.filter((item) => item.outcome === 'accepted').slice(0, 15),
          items,
        },
      };
    },

    async review(account, reference, request) {
      const batch = await repository.findBatchByReference(reference);
      if (!batch || !canReviewBatch(account)) {
        throw new BatchForbiddenError();
      }
      try {
        const decision = await repository.applyReviewDecision({
          batchId: batch.batchId,
          actorId: account.accountId,
          decision: request.decision,
          reason: request.reason,
        });
        if (decision.resumePublication) {
          await repository.publishAcceptedItems(batch.batchId, `reviewer:${account.accountId}`);
        }
      } catch (error) {
        if (
          error instanceof BatchReviewConflictError ||
          error instanceof BatchReviewResolutionError ||
          error instanceof BatchLeaseBusyError
        ) {
          throw new BatchConflictError(error.message);
        }
        throw error;
      }
      const current = await repository.findBatchById(batch.batchId);
      if (!current) throw new Error('Reviewed batch could not be reloaded.');
      return { data: await status(current) };
    },

    async resolvePublishedConflict(account, reference, request) {
      if (!canReviewBatch(account)) throw new BatchForbiddenError();
      const batch = await repository.findBatchByReference(reference);
      if (!batch) throw new BatchForbiddenError();
      try {
        await repository.resolvePublishedConflict({
          batchId: batch.batchId,
          actorId: account.accountId,
          itemOrdinal: request.itemOrdinal,
          existingDeliveryId: request.existingDeliveryId,
          decision: request.decision,
          reason: request.reason,
        });
      } catch (error) {
        if (error instanceof BatchPublishedConflictResolutionError) {
          throw new BatchConflictError(error.message);
        }
        throw error;
      }
      const current = await repository.findBatchById(batch.batchId);
      if (!current) throw new Error('Resolved batch could not be reloaded.');
      return { data: await status(current) };
    },

    async mapReference(account, reference, request) {
      const batch = await findAuthorizedBatch(account, reference);
      let afterOrdinal: number | undefined;
      let selection:
        { entityType: BatchReferenceEntityType; canonicalId: string; label: string } | undefined;

      for (;;) {
        const items = await repository.listBatchItems(batch.batchId, {
          ...(afterOrdinal === undefined ? {} : { afterOrdinal }),
          limit: 1000,
        });
        for (const item of items) {
          if (item.ordinal !== request.itemOrdinal) continue;
          for (const outcome of storedOutcomes(item.resolvedReferences)) {
            if (outcome.referencePath !== request.referencePath) {
              continue;
            }
            const candidate = outcome.candidates.find(
              (value) =>
                !value.outOfScope &&
                (outcome.entityType !== 'competition' ||
                  value.canonicalId === batch.competitionId) &&
                candidateReference(
                  reference,
                  item.ordinal,
                  outcome.referencePath,
                  value.canonicalId,
                ) === request.candidateReference,
            );
            if (candidate) {
              selection = {
                entityType: outcome.entityType,
                canonicalId: candidate.canonicalId,
                label: candidate.label,
              };
              break;
            }
          }
          if (selection) break;
        }
        if (selection || items.length < 1000) break;
        afterOrdinal = items.at(-1)!.ordinal;
      }

      if (!selection) {
        throw new BatchConflictError(
          'The selected candidate is stale or is not available for this reference.',
        );
      }

      try {
        const decision = await repository.queueReferenceMapping({
          decisionReference: randomUUID(),
          batchId: batch.batchId,
          actorId: account.accountId,
          itemOrdinal: request.itemOrdinal,
          referencePath: request.referencePath,
          entityType: selection.entityType,
          candidateId: selection.canonicalId,
          candidateLabel: selection.label,
          decisionKey: request.decisionKey,
        });
        return {
          data: {
            batchReference: reference,
            decisionReference: decision.decisionReference,
            status: decision.state === 'applied' ? 'applied' : 'queued',
            statusUrl: `${API_BASE_PATH}/batches/${reference}`,
            submittedAt: decision.decidedAt,
          },
        };
      } catch (error) {
        if (error instanceof BatchReferenceMappingConflictError) {
          throw new BatchConflictError(error.message);
        }
        throw error;
      }
    },

    async createCanonicalFixture(account, reference, request) {
      if (!canReviewBatch(account)) throw new BatchForbiddenError();
      const batch = await repository.findBatchByReference(reference);
      if (!batch) throw new BatchForbiddenError();
      const items = await repository.listBatchItems(batch.batchId, { limit: 1000 });
      const item = items.find((value) => value.ordinal === request.itemOrdinal);
      const evidence =
        item &&
        storedOutcomes(item.resolvedReferences).find(
          (value) =>
            value.referencePath === request.referencePath && value.entityType === 'fixture',
        );
      const submitted = evidence?.submittedReference as
        | {
            sourceId?: string;
            context?: { date?: string; teams?: { context?: { name?: string } }[] };
            proposal?: Record<string, unknown>;
            season?: { context?: { name?: string } };
          }
        | undefined;
      const proposal = fixtureProposalSchema.safeParse(submitted?.proposal);
      const teams = submitted?.context?.teams?.map((team) => team.context?.name).filter(Boolean);
      if (
        !item ||
        batch.packageVersion !== FIXTURE_PROPOSAL_CONTRACT_VERSION ||
        !submitted?.sourceId ||
        !submitted.context?.date ||
        !submitted.season?.context?.name ||
        !proposal.success ||
        teams?.length !== 2
      ) {
        throw new BatchConflictError('A complete version 1.1 fixture proposal is required.');
      }
      try {
        const decision = await repository.createCanonicalFixtureAndQueueMapping({
          batchId: batch.batchId,
          batchReference: reference,
          competitionId: batch.competitionId,
          actorId: account.accountId,
          itemOrdinal: item.ordinal,
          referencePath: request.referencePath,
          decisionKey: request.decisionKey,
          sourceRef: submitted.sourceId.split(':', 3)[2]!,
          season: submitted.season.context.name,
          startDate: submitted.context.date,
          teamNames: teams as string[],
          proposal: proposal.data,
        });
        return {
          data: {
            batchReference: reference,
            decisionReference: decision.decisionReference,
            status: decision.state === 'applied' ? 'applied' : 'queued',
            statusUrl: `${API_BASE_PATH}/batches/${reference}`,
            submittedAt: decision.decidedAt,
          },
        };
      } catch (error) {
        if (error instanceof BatchReferenceMappingConflictError)
          throw new BatchConflictError(error.message);
        throw error;
      }
    },
  };
}

import { z } from 'zod';

import {
  apiDateTimeSchema,
  apiIdentifierSchema,
  createCollectionResponseSchema,
  createResourceResponseSchema,
  paginationQuerySchema,
} from './api';
import { sourceIdentifierSchema } from './season-upload';

export const BATCH_PACKAGE_VERSION = '1.0' as const;
export const BATCH_PACKAGE_VERSIONS = ['1.0', '1.1'] as const;
export const BATCH_MEDIA_TYPES = ['application/json', 'text/csv', 'application/x-ndjson'] as const;
export const BATCH_STATES = [
  'received',
  'stored',
  'validating',
  'rejected',
  'awaiting_review',
  'correction_requested',
  'publishing',
  'published',
  'partially_published',
  'failed',
  'superseded',
] as const;

export const batchReferenceSchema = z.string().uuid();
export const batchMetadataSchema = z
  .object({
    competitionId: apiIdentifierSchema.regex(/^[1-9]\d*$/, 'Expected a positive competition ID.'),
    idempotencyKey: z.string().trim().min(1).max(255),
    packageVersion: z.enum(BATCH_PACKAGE_VERSIONS),
    fileName: z.string().trim().min(1).max(255),
    mediaType: z.enum(BATCH_MEDIA_TYPES),
  })
  .strict();

export const batchReceiptSchema = z
  .object({
    batchReference: batchReferenceSchema,
    status: z.enum(['stored', 'received']),
    statusUrl: z.string().startsWith('/api/v1/batches/'),
    receivedAt: apiDateTimeSchema,
  })
  .strict();

export const batchReceiptResponseSchema = createResourceResponseSchema(batchReceiptSchema);

export const BATCH_REVIEW_DECISIONS = ['approved', 'rejected', 'returned_for_correction'] as const;

export const batchReviewDecisionSchema = z
  .object({
    decision: z.enum(BATCH_REVIEW_DECISIONS),
    actor: z
      .object({
        accountId: apiIdentifierSchema,
        displayName: z.string().nullable(),
      })
      .strict(),
    decidedAt: apiDateTimeSchema,
    reason: z.string().min(1),
  })
  .strict();

export const batchReviewRequestSchema = z
  .object({
    decision: z.enum(BATCH_REVIEW_DECISIONS),
    reason: z.string().trim().min(1).max(2000),
  })
  .strict()
  .superRefine((value, context) => {
    if (value.decision !== 'approved' && value.reason.length < 10) {
      context.addIssue({
        code: z.ZodIssueCode.too_small,
        minimum: 10,
        type: 'string',
        inclusive: true,
        path: ['reason'],
        message: 'Explain the rejection or correction in at least 10 characters.',
      });
    }
  });

export const batchStatusSchema = z
  .object({
    batchReference: batchReferenceSchema,
    competitionId: apiIdentifierSchema,
    status: z.enum(BATCH_STATES),
    statusUrl: z.string().startsWith('/api/v1/batches/'),
    receivedAt: apiDateTimeSchema,
    updatedAt: apiDateTimeSchema,
    source: z
      .object({
        fileName: z.string().min(1).nullable(),
        checksum: z
          .string()
          .regex(/^[0-9a-f]{64}$/)
          .nullable(),
        packageVersion: z.string().min(1),
        submitter: z
          .object({ accountId: apiIdentifierSchema, displayName: z.string().nullable() })
          .strict(),
      })
      .strict(),
    progress: z
      .object({
        total: z.number().int().nonnegative(),
        processed: z.number().int().nonnegative(),
        accepted: z.number().int().nonnegative(),
        rejected: z.number().int().nonnegative(),
      })
      .strict(),
    counts: z
      .object({
        accepted: z.number().int().nonnegative(),
        rejected: z.number().int().nonnegative(),
        unresolved: z.number().int().nonnegative(),
        duplicate: z.number().int().nonnegative(),
        conflicting: z.number().int().nonnegative(),
      })
      .strict(),
    review: batchReviewDecisionSchema.nullable(),
  })
  .strict();

export const batchStatusResponseSchema = createResourceResponseSchema(batchStatusSchema);
export const batchReviewResponseSchema = createResourceResponseSchema(batchStatusSchema);

export const batchListQuerySchema = paginationQuerySchema.extend({
  status: z.enum(BATCH_STATES).optional(),
});
export const batchListResponseSchema = createCollectionResponseSchema(batchStatusSchema);

export const batchReportQuerySchema = paginationQuerySchema;

export const batchReportLocationSchema = z
  .object({
    filePath: z.string().nullable(),
    sheetName: z.string().nullable(),
    rowNumber: z.number().int().positive().nullable(),
    jsonPath: z.string().nullable(),
    ordinal: z.number().int().nonnegative(),
  })
  .strict();

export const batchReportContextSchema = z
  .object({
    eventReference: z.string().nullable(),
    fixtureId: apiIdentifierSchema.nullable(),
    fixtureLabel: z.string().min(1).nullable(),
    inningsId: apiIdentifierSchema.nullable(),
    overNumber: z.number().int().nonnegative().nullable(),
    positionInOver: z.number().int().nonnegative().nullable(),
    description: z.string().min(1),
  })
  .strict();

export const batchReferenceEntityTypeSchema = z.enum([
  'competition',
  'team',
  'fixture',
  'innings',
  'participant',
]);

export const batchReferenceResolutionSchema = z
  .object({
    referencePath: z.string().min(1),
    entityType: batchReferenceEntityTypeSchema,
    state: z.enum(['ambiguous', 'unresolved', 'invalid']),
    submittedReference: z.unknown(),
    reason: z.string().min(1).nullable(),
    requiredAction: z.enum(['select_candidate', 'contact_reviewer']),
    candidates: z.array(
      z
        .object({
          candidateReference: z.string().uuid(),
          label: z.string().min(1),
        })
        .strict(),
    ),
  })
  .strict();

export const batchReportErrorSchema = z
  .object({
    ruleCode: z.string().regex(/^[A-Z][A-Z0-9_]*$/),
    message: z.string().min(1),
    location: batchReportLocationSchema,
    context: batchReportContextSchema,
  })
  .strict();

export const batchPublishedConflictDifferenceSchema = z
  .object({
    fieldPath: z.string().min(1),
    submittedValue: z.unknown(),
    publishedValue: z.unknown(),
  })
  .strict();

export const batchPublishedConflictSchema = z
  .object({
    existingDeliveryId: apiIdentifierSchema,
    existingSourceEventId: z.string().uuid().nullable(),
    correctionPermitted: z.boolean(),
    differences: z.array(batchPublishedConflictDifferenceSchema).min(1),
  })
  .strict();

export const batchConflictResolutionRequestSchema = z
  .object({
    itemOrdinal: z.number().int().nonnegative(),
    existingDeliveryId: apiIdentifierSchema,
    decision: z.enum(['use_existing', 'replace_published']),
    reason: z.string().trim().min(10).max(2000),
  })
  .strict();

export const batchReportItemSchema = z
  .object({
    ordinal: z.number().int().nonnegative(),
    outcome: z.enum(['pending', 'accepted', 'rejected', 'unresolved', 'duplicate', 'conflicting']),
    location: batchReportLocationSchema,
    context: batchReportContextSchema,
    stagedRecordId: apiIdentifierSchema.nullable(),
    acceptedRecordId: apiIdentifierSchema.nullable(),
    operation: z.enum(['upsert', 'correction']).default('upsert'),
    correctionTarget: z
      .object({
        sourceEventId: sourceIdentifierSchema,
        resolvedDeliveryId: apiIdentifierSchema.nullable(),
      })
      .strict()
      .nullable()
      .default(null),
    publishedConflict: batchPublishedConflictSchema.nullable().optional(),
    referenceResolutions: z.array(batchReferenceResolutionSchema),
    errors: z.array(batchReportErrorSchema),
  })
  .strict();

export const batchReportRuleGroupSchema = z
  .object({
    ruleCode: z.string().regex(/^[A-Z][A-Z0-9_]*$/),
    count: z.number().int().positive(),
  })
  .strict();

export const batchFixtureSummarySchema = z
  .object({
    fixtureId: apiIdentifierSchema.nullable(),
    label: z.string().min(1),
    total: z.number().int().nonnegative(),
    accepted: z.number().int().nonnegative(),
    rejected: z.number().int().nonnegative(),
    unresolved: z.number().int().nonnegative(),
  })
  .strict();

export const batchReviewSummarySchema = z
  .object({
    validation: z
      .object({
        accepted: z.number().int().nonnegative(),
        rejected: z.number().int().nonnegative(),
        blockingErrors: z.number().int().nonnegative(),
        duplicate: z.number().int().nonnegative(),
        conflicting: z.number().int().nonnegative(),
      })
      .strict(),
    resolution: z
      .object({
        resolved: z.number().int().nonnegative(),
        ambiguous: z.number().int().nonnegative(),
        unresolved: z.number().int().nonnegative(),
        invalid: z.number().int().nonnegative(),
        proposed: z.number().int().nonnegative(),
      })
      .strict(),
    approvalBlocked: z.boolean(),
    blockingReasons: z.array(z.string().min(1)),
  })
  .strict();

export const batchReportSchema = z
  .object({
    batch: batchStatusSchema,
    errorGroups: z.array(batchReportRuleGroupSchema),
    reviewSummary: batchReviewSummarySchema,
    fixtureSummaries: z.array(batchFixtureSummarySchema),
    acceptedSamples: z.array(batchReportItemSchema).max(15),
    items: z.array(batchReportItemSchema),
    pagination: z.object({ nextCursor: z.string().min(1).nullable() }).strict(),
