eSchema,\\n  })\\n  .strict();\\n\\nexport type ApplicationRole = z.infer<typeof applicationRoleSchema>;\\nexport type SubmitterApprovalState = z.infer<typeof submitterApprovalStateSchema>;\\nexport type CurrentUserProfile = z.infer<typeof currentUserProfileSchema>;\\nexport type CurrentUserProfileResponse = z.infer<typeof currentUserProfileResponseSchema>;\\n\\r\\n###FILE:packages/contracts/src/tests/auth.test.ts\\r\\nimport { describe, expect, test } from 'vitest';\\n\\nimport { currentUserProfileResponseSchema, submitterApprovalStateSchema } from '../auth';\\n\\ndescribe('submitter approval state contract', () => {\\n  test.each(['not_requested', 'pending', 'approved', 'rejected'] as const)(\\n    'accepts the %s state',\\n    (approvalState) => {\\n      expect(submitterApprovalStateSchema.parse(approvalState)).toBe(approvalState);\\n    },\\n  );\\n\\n  test('rejects an unsupported approval state', () => {\\n    expect(submitterApprovalStateSchema.safeParse('revoked').success).toBe(false);\\n  });\\n});\\n\\ndescribe('current user profile response contract', () => {\\n  test.each(['not_requested', 'pending', 'approved', 'rejected'] as const)(\\n    'accepts a current-user response with %s submitter access',\\n    (approvalState) => {\\n      const result = currentUserProfileResponseSchema.safeParse({\\n        user: {\\n          id: '42',\\n          subject: 'supabase-user-123',\\n          displayName: 'Example User',\\n          role: 'viewer',\\n          approvalState,\\n          competitionIds: [],\\n        },\\n      });\\n\\n      expect(result.success).toBe(true);\\n    },\\n  );\\n\\n  test('accepts an approved submitter with competition scope', () => {\\n    const result = currentUserProfileResponseSchema.safeParse({\\n      user: {\\n        id: '42',\\n        subject: 'supabase-user-123',\\n        displayName: 'Example User',\\n        role: 'viewer',\\n        approvalState: 'approved',\\n        competitionIds: ['7', '12'],\\n      },\\n    });\\n\\n    expect(result.success).toBe(true);\\n  });\\n\\n  test('accepts a null display name', () => {\\n    const result = currentUserProfileResponseSchema.safeParse({\\n      user: {\\n        id: '42',\\n        subject: 'supabase-user-123',\\n        displayName: null,\\n        role: 'viewer',\\n        approvalState: 'not_requested',\\n        competitionIds: [],\\n      },\\n    });\\n\\n    expect(result.success).toBe(true);\\n  });\\n\\n  test('rejects a response without the approval state', () => {\\n    const result = currentUserProfileResponseSchema.safeParse({\\n      user: {\\n        id: '42',\\n        subject: 'supabase-user-123',\\n        displayName: 'Example User',\\n        role: 'viewer',\\n        competitionIds: [],\\n      },\\n    });\\n\\n    expect(result.success).toBe(false);\\n  });\\n\\n  test('rejects duplicate competition scope identifiers', () => {\\n    const result = currentUserProfileResponseSchema.safeParse({\\n      user: {\\n        id: '42',\\n        subject: 'supabase-user-123',\\n        displayName: 'Example User',\\n        role: 'viewer',\\n        approvalState: 'approved',\\n        competitionIds: ['7', '7'],\\n      },\\n    });\\n\\n    expect(result.success).toBe(false);\\n  });\\n});\\n\\r\\n###FILE:apps/backend/src/routes/auth.routes.ts\\r\\nimport { currentUserProfileResponseSchema } from '@sport-analytics/contracts';\\nimport { Router } from 'express';\\nimport type { VerifyAccessToken } from '../auth/supabase-auth';\\nimport { requireAuthentication } from '../middleware/require-authentication';\\nimport type { ApplicationAccount } from '../modules/accounts/account';\\nimport type { SynchronizeAccount } from '../modules/accounts/account.service';\\n\\nexport function createAuthRouter(\\n  verifyAccessToken: VerifyAccessToken,\\n  synchronizeAccount: SynchronizeAccount,\\n): Router {\\n  const authRouter = Router();\\n\\n  authRouter.get(\\n    '/me',\\n    requireAuthentication(verifyAccessToken, synchronizeAccount),\\n    (_request, response, next) => {\\n      const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;\\n\\n      if (!account) {\\n        next(new Error('Authenticated account was not attached to the response'));\\n        return;\\n      }\\n\\n      const responseBody = currentUserProfileResponseSchema.parse({\\n        user: {\\n          id: account.accountId,\\n          subject: account.subject,\\n          displayName: account.displayName,\\n          role: account.role,\\n          approvalState: account.approvalState,\\n          competitionIds: account.competitionIds,\\n        },\\n      });\\n\\n      response.status(200).json(responseBody);\\n    },\\n  );\\n\\n  return authRouter;\\n}\\n\\r\\n###FILE:apps/backend/src/modules/accounts/account.ts\\r\\nimport {\\n  applicationRoleSchema,\\n  submitterApprovalStateSchema,\\n  type ApplicationRole,\\n  type SubmitterApprovalState,\\n} from '@sport-analytics/contracts';\\n\\nexport type { ApplicationRole, SubmitterApprovalState } from '@sport-analytics/contracts';\\n\\nexport interface ApplicationAccount {\\n  accountId: string;\\n  subject: string;\\n  displayName: string | null;\\n  role: ApplicationRole;\\n  approvalState: SubmitterApprovalState;\\n  competitionIds: string[];\\n  disabled: boolean;\\n}\\n\\nexport function isApplicationRole(value: string): value is ApplicationRole {\\n  return applicationRoleSchema.safeParse(value).success;\\n}\\n\\nexport function isSubmitterApprovalState(value: string): value is SubmitterApprovalState {\\n  return submitterApprovalStateSchema.safeParse(value).success;\\n}\\n\\r\\n###FILE:apps/backend/src/modules/submitter-access/submitter-access.controller.ts\\r\\nimport type { RequestHandler, Response } from 'express';\\n\\nimport type { ApplicationAccount } from '../accounts/account';\\nimport { SubmitterAccessConflictError } from './submitter-access.errors';\\nimport type { SubmitterAccessService } from './submitter-access.service';\\n\\nfunction getAuthenticatedAccount(response: Response): ApplicationAccount {\\n  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;\\n\\n  if (!account) {\\n    throw new Error('Submitter access controller requires an authenticated application account');\\n  }\\n\\n  return account;\\n}\\n\\nexport function createSubmitterAccessController(service: SubmitterAccessService): RequestHandler {\\n  return (_request, response, next) => {\\n    let account: ApplicationAccount;\\n\\n    try {\\n      account = getAuthenticatedAccount(response);\\n    } catch (error) {\\n      next(error);\\n      return;\\n    }\\n\\n    void service\\n      .requestAccess(account)\\n      .then((result) => {\\n        response.status(201).json(result);\\n      })\\n      .catch((error: unknown) => {\\n        if (error instanceof SubmitterAccessConflictError) {\\n          response.status(409).json({\\n            error: {\\n              code: error.code,\\n              message: error.message,\\n            },\\n          });\\n          return;\\n        }\\n\\n        next(error);\\n      });\\n  };\\n}\\n\\r\\n###FILE:apps/backend/src/modules/submitter-access/submitter-access.service.ts\\r\\nimport type { ApplicationAccount } from '../accounts/account';\\nimport {\\n  createSubmitterAccessRepository,\\n  type SubmitterAccessRepository,\\n} from './submitter-access.repository';\\n\\nexport interface SubmitterAccessResponse {\\n  data: {\\n    accountId: string;\\n    approvalState: 'pending';\\n  };\\n}\\n\\nexport interface SubmitterAccessService {\\n  requestAccess(account: ApplicationAccount): Promise<SubmitterAccessResponse>;\\n}\\n\\nexport function createSubmitterAccessService(\\n  repository: SubmitterAccessRepository = createSubmitterAccessRepository(),\\n): SubmitterAccessService {\\n  return {\\n    async requestAccess(account) {\\n      const request = await repository.requestAccess(account.accountId);\\n\\n      return {\\n        data: request,\\n      };\\n    },\\n  };\\n}\\n\\r\\n###FILE:apps/backend/src/modules/submitter-access/submitter-access.repository.ts\\r\\nimport { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';\\nimport { isSubmitterApprovalState } from '../accounts/account';\\nimport { SubmitterAccessConflictError } from './submitter-access.errors';\\n\\nexport interface SubmitterAccessRequestRecord {\\n  accountId: string;\\n  approvalState: 'pending';\\n}\\n\\nexport interface SubmitterAccessRepository {\\n  requestAccess(accountId: string): Promise<SubmitterAccessRequestRecord>;\\n}\\n\\ninterface SubmitterAccessRow {\\n  accountId: string;\\n  approvalState: string;\\n  disabledAt: Date | null;\\n}\\n\\nexport function createSubmitterAccessRepository(\\n  executor: QueryExecutor = getDatabasePool(),\\n): SubmitterAccessRepository {\\n  return {\\n    async requestAccess(accountId) {\\n      const updated = await executeQuery<SubmitterAccessRow>(\\n        executor,\\n        `\\n          UPDATE app_user\\n          SET submitter_approval_state = 'pending'\\n          WHERE app_user_id = $1\\n            AND submitter_approval_state IN ('not_requested', 'rejected')\\n            AND disabled_at IS NULL\\n          RETURNING\\n            app_user_id::text AS \\\"accountId\\\",\\n            submitter_approval_state AS \\\"approvalState\\\",\\n            disabled_at AS \\\"disabledAt\\\"\\n        `,\\n        [accountId],\\n      );\\n\\n      const created = updated.rows[0];\\n\\n      if (created) {\\n        return {\\n          accountId: created.accountId,\\n          approvalState: 'pending',\\n        };\\n      }\\n\\n      const current = await executeQuery<SubmitterAccessRow>(\\n        executor,\\n        `\\n          SELECT\\n            app_user_id::text AS \\\"accountId\\\",\\n            submitter_approval_state AS \\\"approvalState\\\",\\n            disabled_at AS \\\"disabledAt\\\"\\n          FROM app_user\\n          WHERE app_user_id = $1\\n        `,\\n        [accountId],\\n      );\\n\\n      const account = current.rows[0];\\n\\n      if (!account) {\\n        throw new Error('Authenticated application account no longer exists');\\n      }\\n\\n      if (account.disabledAt) {\\n        throw new Error('Authenticated application account became disabled');\\n      }\\n\\n      if (!isSubmitterApprovalState(account.approvalState)) {\\n        throw new Error('Application account has an unsupported approval state');\\n      }\\n\\n      if (account.approvalState === 'pending') {\\n        throw new SubmitterAccessConflictError(\\n          'REQUEST_ALREADY_PENDING',\\n          'A submitter access request is already pending.',\\n        );\\n      }\\n\\n      if (account.approvalState === 'approved') {\\n        throw new SubmitterAccessConflictError(\\n          'SUBMITTER_ALREADY_APPROVED',\\n          'The authenticated account is already an approved submitter.',\\n        );\\n      }\\n\\n      throw new Error('Submitter access request state changed unexpectedly');\\n    },\\n  };\\n}\\n\\r\\n###FILE:apps/frontend/src/App.tsx\\r\\nimport { Route, Routes } from 'react-router-dom';\\nimport { PublicShell } from './components/PublicShell';\\nimport {\\n  CompetitionDetailPage,\\n  CompetitionsPage,\\n  CompetitorDetailPage,\\n  CompetitorsPage,\\n  FixtureDetailPage,\\n  FixturesPage,\\n  NotFoundPage,\\n  ParticipantDetailPage,\\n  ParticipantsPage,\\n  SeasonDetailPage,\\n  SeasonsPage,\\n} from './pages/PublicBrowsePages';\\nimport { useEffect } from 'react';\\nimport {\\n  AccountPage,\\n  AuthenticationCallbackPage,\\n  AuthenticationPage,\\n} from './features/auth/AuthPages';\\nimport { SubmissionPage } from './features/submissions/SubmissionPage';\\nimport {\\n  FixtureStatisticDetailPage,\\n  FixtureStatisticsPage,\\n} from './features/statistics/StatisticsPages';\\n\\nfunction HeroLogo() {\\n  return (\\n    <div className=\\\"hero__brand-art\\\" aria-hidden=\\\"true\\\">\\n      <img\\n        className=\\\"hero__logo brand-asset--day\\\"\\n        src=\\\"/brand/statsthegame-mark-light.svg\\\"\\n        alt=\\\"\\\"\\n      />\\n      <img\\n        className=\\\"hero__logo brand-asset--night\\\"\\n        src=\\\"/brand/statsthegame-mark-dark.svg\\\"\\n        alt=\\\"\\\"\\n      />\\n    </div>\\n  );\\n}\\n\\nfunction LandingPage() {\\n  useEffect(() => {\\n    document.title = \\\"Stat'sTheGame\\\";\\n  }, []);\\n\\n  return (\\n    <>\\n      <section className=\\\"hero\\\" aria-labelledby=\\\"page-title\\\">\\n        <HeroLogo />\\n        <div className=\\\"hero__content\\\">\\n          <p className=\\\"eyebrow\\\">Public T20 cricket record</p>\\n          <h1 id=\\\"page-title\\\">Stat&rsquo;sTheGame</h1>\\n          <p className=\\\"hero__tagline\\\">The game, measured ball by ball.</p>\\n          <p className=\\\"hero__summary\\\">\\n            An event-driven home for published cricket records, designed to keep every result\\n            connected to the deliveries behind it.\\n          </p>\\n        </div>\\n      </section>\\n\\n      <section className=\\\"principles\\\" aria-labelledby=\\\"principles-title\\\">\\n        <div className=\\\"content-boundary\\\">\\n          <div className=\\\"section-heading\\\">\\n            <p className=\\\"eyebrow\\\">Our standard</p>\\n            <h2 id=\\\"principles-title\\\">Explosive. Exact. Traceable.</h2>\\n          </div>\\n\\n          <div className=\\\"principles__grid\\\">\\n            <article>\\n              <p className=\\\"principle-number\\\" aria-hidden=\\\"true\\\">\\n                01\\n              </p>\\n              <h3>Event-led</h3>\\n              <p>Published figures begin with accepted, event-level cricket data.</p>\\n            </article>\\n            <article>\\n              <p className=\\\"principle-number\\\" aria-hidden=\\\"true\\\">\\n                02\\n              </p>\\n              <h3>Public by design</h3>\\n      