ns/new\\\" element={<SubmissionPage />} />\\n\\n        <Route path=\\\"*\\\" element={<NotFoundPage />} />\\n      </Routes>\\n    </PublicShell>\\n  );\\n}\\n\\nfunction App() {\\n  return <PublicApp />;\\n}\\n\\nexport default App;\\n\\r\\n###FILE:apps/frontend/src/App.test.tsx\\r\\nimport type { AuthChangeEvent, Session, User } from '@supabase/supabase-js';\\nimport { act, fireEvent, render, screen, within } from '@testing-library/react';\\nimport type { ComponentProps } from 'react';\\nimport { MemoryRouter } from 'react-router-dom';\\nimport { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';\\nimport App from './App';\\nimport { AuthProvider } from './features/auth/AuthProvider';\\nimport { THEME_STORAGE_KEY } from './theme';\\n\\ntype AuthClient = ComponentProps<typeof AuthProvider>['client'];\\ntype AuthStateListener = (event: AuthChangeEvent, session: Session | null) => void;\\n\\nfunction createSession(): Session {\\n  const user = {\\n    id: 'user-123',\\n    aud: 'authenticated',\\n    role: 'authenticated',\\n    email: 'person@example.com',\\n    app_metadata: {},\\n    user_metadata: {},\\n    identities: [],\\n    created_at: '2026-08-09T00:00:00.000Z',\\n  } satisfies User;\\n\\n  return {\\n    access_token: 'current-access-token',\\n    refresh_token: 'managed-by-supabase',\\n    expires_in: 3600,\\n    token_type: 'bearer',\\n    user,\\n  };\\n}\\n\\nfunction createAuthClient(session: Session | null) {\\n  let listener: AuthStateListener | undefined;\\n  const client = {\\n    getSession: vi.fn().mockResolvedValue({ data: { session } }),\\n    onAuthStateChange: vi.fn((nextListener: AuthStateListener) => {\\n      listener = nextListener;\\n      return {\\n        data: {\\n          subscription: {\\n            id: 'app-test-subscription',\\n            callback: nextListener,\\n            unsubscribe: vi.fn(),\\n          },\\n        },\\n      };\\n    }),\\n    signInWithOAuth: vi\\n      .fn()\\n      .mockResolvedValue