import type { Readable } from 'node:stream';

import { closeDatabasePool } from '../src/database';
import {
  createDatasetReleaseRepository,
  type DatasetReleaseRepository,
} from '../src/modules/dataset-releases/dataset-release.repository';
import { createDatasetReleaseService } from '../src/modules/dataset-releases/dataset-release.service';
import type { ObjectStore } from '../src/modules/object-storage/object-store';

class DiagnosticComplete extends Error {}

async function main(): Promise<void> {
  const startedAt = Date.now();
  const repository = createDatasetReleaseRepository();
  let pageNumber = 0;
  let eventCount = 0;
  let byteCount = 0;
  let result:
    | { eventCount: number; checksum: string; artifactStorageKey: string }
    | undefined;

  const diagnosticRepository: DatasetReleaseRepository = {
    ...repository,
    async findByVersion() {
      return null;
    },
    async loadPublishedEventPage(cursor, limit) {
      const pageStartedAt = Date.now();
      const page = await repository.loadPublishedEventPage(cursor, limit);
      pageNumber += 1;
      eventCount += page.events.length;
      console.log(
        JSON.stringify({
          phase: 'database-page-complete',
          pageNumber,
          pageEvents: page.events.length,
          cumulativeEvents: eventCount,
          elapsedMs: Date.now() - startedAt,
          pageElapsedMs: Date.now() - pageStartedAt,
          lastKeysetPosition: page.nextCursor,
        }),
      );
      return page;
    },
    async createOrFind(input) {
      result = {
        eventCount: input.eventCount,
        checksum: input.checksum,
        artifactStorageKey: input.artifactStorageKey,
      };
      throw new DiagnosticComplete();
    },
  };
  const sink: ObjectStore = {
    async write(_storageKey: string, source: Readable) {
      for await (const chunk of source) {
        byteCount += Buffer.isBuffer(chunk) ? chunk.length : Buffer.byteLength(chunk);
      }
      return { versionId: null };
    },
    async read() {
      throw new Error('The diagnostic sink does not retain bytes.');
    },
    async delete() {},
  };

  try {
    await createDatasetReleaseService(diagnosticRepository, sink).createRelease({
      version: `diagnostic-${Date.now()}`,
    });
  } catch (error) {
    if (!(error instanceof DiagnosticComplete)) throw error;
  }

  console.log(
    JSON.stringify({
      phase: 'generation-complete',
      pages: pageNumber,
      bytesWritten: byteCount,
      elapsedMs: Date.now() - startedAt,
      result,
    }),
  );
}

void main()
  .catch((error: unknown) => {
    console.error(error instanceof Error ? `${error.name}: ${error.message}` : 'Unknown error');
    process.exitCode = 1;
  })
  .finally(() => closeDatabasePool());

