import type { RequestHandler, Response } from 'express';
import type { VerifyAccessToken } from '../auth/supabase-auth';
import type { ApplicationAccount } from '../modules/accounts/account';
import type { SynchronizeAccount } from '../modules/accounts/account.service';
import { rejectAuthorization } from './authorization-response';

interface AuthenticationOptions {
  allowDisabledAccount?: (account: ApplicationAccount) => boolean;
}

function rejectAuthentication(response: Response): void {
  response.setHeader('WWW-Authenticate', 'Bearer');
  response.status(401).json({
    error: {
      code: 'UNAUTHORIZED',
      message: 'A valid authentication token is required.',
    },
  });
}

export function requireAuthentication(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  options: AuthenticationOptions = {},
): RequestHandler {
  return async (request, response, next) => {
    const authorization = request.get('authorization');
    const parts = authorization?.trim().split(/\s+/);
    const scheme = parts?.[0];
    const token = parts?.[1];

    if (parts?.length !== 2 || scheme?.toLowerCase() !== 'bearer' || !token) {
      rejectAuthentication(response);
      return;
    }

    let identity;

    try {
      identity = await verifyAccessToken(token);
    } catch {
      // Do not reveal token-validation details or log the submitted token.
      rejectAuthentication(response);
      return;
    }

    try {
      const account = await synchronizeAccount(identity);

      if (account.disabled && !options.allowDisabledAccount?.(account)) {
        rejectAuthorization(response);
        return;
      }

      response.locals.authenticatedIdentity = identity;
      response.locals.authenticatedAccount = account;
      next();
    } catch (error) {
      next(error);
    }
  };
}

import type { Request, RequestHandler, Response } from 'express';
import type { ApplicationAccount } from '../modules/accounts/account';
import { rejectAuthorization } from './authorization-response';

type CompetitionIdResolver = (request: Request) => string | undefined | Promise<string | undefined>;

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Authorization middleware requires an authenticated application account');
  }

  return account;
}

export function requireAdministrator(): RequestHandler {
  return (_request, response, next) => {
    let account: ApplicationAccount;

    try {
      account = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    if (account.role !== 'admin') {
      rejectAuthorization(response);
      return;
    }

    next();
