import { executeQuery, getDatabasePool, type QueryExecutor } from '../../database';

export interface DatasetReleaseSnapshot {
  releaseId: string;
  version: string;
  createdAt: string;
  eventCount: number;
  checksum: string;
}

export interface DatasetReleaseEventCursor {
  fixtureId: string;
  inningsOrdinal: number;
  sequenceNumber: number;
  eventId: string;
}

interface DatasetReleaseEventPage {
  events: unknown[];
  nextCursor: DatasetReleaseEventCursor | null;
}

export interface DatasetReleaseArtifactReference {
  storageKey: string | null;
  legacyArtifactText: string | null;
}

interface DatasetReleaseRow extends DatasetReleaseSnapshot {
  artifactStorageKey?: string | null;
  artifactText?: string | null;
}

interface DatasetReleaseEventRow extends DatasetReleaseEventCursor {
  event: unknown;
}

export interface DatasetReleaseRepository {
  loadPublishedEventPage(
    cursor: DatasetReleaseEventCursor | null,
    limit: number,
  ): Promise<DatasetReleaseEventPage>;
  createOrFind(input: {
    version: string;
    formatVersion: string;
    scope: string;
    eventCount: number;
    fields: readonly { name: string; description: string }[];
    artifactStorageKey: string;
    artifactProviderVersionId: string | null;
    checksum: string;
  }): Promise<{ snapshot: DatasetReleaseSnapshot; created: boolean }>;
  list(): Promise<DatasetReleaseSnapshot[]>;
  findByVersion(version: string): Promise<DatasetReleaseSnapshot | null>;
  findArtifactReferenceByVersion(version: string): Promise<DatasetReleaseArtifactReference | null>;
}

const snapshotColumns = `
  release_id::text AS "releaseId", version,
  created_at::text AS "createdAt", event_count AS "eventCount",
  checksum_sha256 AS checksum
`;

export function createDatasetReleaseRepository(executor?: QueryExecutor): DatasetReleaseRepository {
  const database = () => executor ?? getDatabasePool();

  async function findByVersion(version: string): Promise<DatasetReleaseSnapshot | null> {
    const result = await executeQuery<DatasetReleaseRow>(
      database(),
      `SELECT ${snapshotColumns} FROM dataset_release WHERE version = $1`,
      [version],
    );
    return result.rows[0] ?? null;
  }

  return {
    async loadPublishedEventPage(cursor, limit) {
      const result = await executeQuery<DatasetReleaseEventRow>(
        database(),
        `
          SELECT json_build_object(
            'eventId', d.delivery_id::text, 'fixtureId', i.fixture_id::text,
            'inningsId', i.innings_id::text, 'inningsOrdinal', i.ordinal,
            'sequenceNumber', d.innings_sequence, 'overNumber', d.over_number,
            'positionInOver', d.position_in_over, 'ballNumber', d.ball_number,
            'strikerParticipantId', d.striker_id::text, 'nonStrikerParticipantId', d.non_striker_id::text,
            'bowlerParticipantId', d.bowler_id::text, 'runsOffBat', d.runs_off_bat,
            'runsExtras', d.runs_extras, 'runsTotal', d.runs_total
          ) AS event,
          i.fixture_id::text AS "fixtureId", i.ordinal AS "inningsOrdinal",
          d.innings_sequence AS "sequenceNumber", d.delivery_id::text AS "eventId"
          FROM delivery_current d
          INNER JOIN innings i ON i.innings_id = d.innings_id
          INNER JOIN submission s ON s.submission_id = d.submission_id AND s.status = 'accepted'
          WHERE $1::bigint IS NULL
             OR (i.fixture_id, i.ordinal, d.innings_sequence, d.delivery_id)
                > ($1::bigint, $2::integer, $3::integer, $4::bigint)
          ORDER BY i.fixture_id ASC, i.ordinal ASC, d.innings_sequence ASC, d.delivery_id ASC
          LIMIT $5
        `,
        [
          cursor?.fixtureId ?? null,
          cursor?.inningsOrdinal ?? null,
          cursor?.sequenceNumber ?? null,
          cursor?.eventId ?? null,
          limit,
        ],
      );
      const last = result.rows.at(-1);
      return {
        events: result.rows.map((row) => row.event),
        nextCursor: last
          ? {
              fixtureId: last.fixtureId,
              inningsOrdinal: last.inningsOrdinal,
              sequenceNumber: last.sequenceNumber,
              eventId: last.eventId,
            }
          : null,
      };
    },

    async createOrFind(input) {
      const result = await executeQuery<DatasetReleaseRow>(
        database(),
        `
          INSERT INTO dataset_release
            (version, format_version, scope, event_count, fields, artifact_storage_key,
             artifact_provider_version_id, checksum_sha256)
          VALUES ($1, $2, $3, $4, $5::jsonb, $6, $7, $8)
          ON CONFLICT (version) DO NOTHING
          RETURNING ${snapshotColumns}
        `,
        [
          input.version,
          input.formatVersion,
          input.scope,
          input.eventCount,
          JSON.stringify(input.fields),
          input.artifactStorageKey,
          input.artifactProviderVersionId,
          input.checksum,
        ],
      );
      if (result.rows[0]) {
        return { snapshot: result.rows[0], created: true };
      }

      const existing = await findByVersion(input.version);
      if (!existing) {
        throw new Error('Dataset release was not created or found.');
      }
      return { snapshot: existing, created: false };
    },

    async list() {
      const result = await executeQuery<DatasetReleaseRow>(
        database(),
        `SELECT ${snapshotColumns} FROM dataset_release ORDER BY created_at DESC, version DESC`,
      );
      return result.rows;
    },

    findByVersion,

    async findArtifactReferenceByVersion(version) {
      const result = await executeQuery<DatasetReleaseRow>(
        database(),
        `
          SELECT artifact_storage_key AS "artifactStorageKey", artifact_text AS "artifactText"
          FROM dataset_release
          WHERE version = $1
        `,
        [version],
      );
      const row = result.rows[0];
      return row
        ? {
            storageKey: row.artifactStorageKey ?? null,
            legacyArtifactText: row.artifactText ?? null,
          }
        : null;
    },
  };
}

import { createHash, randomUUID } from 'node:crypto';
import { Readable } from 'node:stream';

import {
  DATASET_RELEASE_FORMAT_VERSION,
  type CreateDatasetRelease,
  type DatasetRelease,
} from '@sport-analytics/contracts';

import { ObjectStorageError, type ObjectStore } from '../object-storage/object-store';
import {
  createDatasetReleaseRepository,
  type DatasetReleaseEventCursor,
  type DatasetReleaseRepository,
  type DatasetReleaseSnapshot,
} from './dataset-release.repository';

const DATASET_RELEASE_EVENT_PAGE_SIZE = 10_000;
const DATASET_RELEASE_SCOPE = 'published-accepted-deliveries';

const fields = [
  { name: 'eventId', description: 'Stable identifier of the accepted delivery revision.' },
  { name: 'fixtureId', description: 'Fixture containing the delivery.' },
  { name: 'inningsId', description: 'Innings containing the delivery.' },
  { name: 'inningsOrdinal', description: 'Zero-based source innings order.' },
  { name: 'sequenceNumber', description: 'Stable delivery order within the innings.' },
  { name: 'overNumber', description: 'Zero-based cricket over number.' },
  { name: 'positionInOver', description: 'Zero-based source position within the over.' },
  { name: 'ballNumber', description: 'Display ball label; not an identity field.' },
  { name: 'strikerParticipantId', description: 'Stable striker participant identifier.' },
  { name: 'nonStrikerParticipantId', description: 'Stable non-striker participant identifier.' },
  { name: 'bowlerParticipantId', description: 'Stable bowler participant identifier.' },
  { name: 'runsOffBat', description: 'Runs credited to the striker.' },
  { name: 'runsExtras', description: 'Extra runs on the delivery.' },
  { name: 'runsTotal', description: 'Total runs on the delivery.' },
] as const;

export interface DatasetReleaseService {
  createRelease(input: CreateDatasetRelease): Promise<DatasetRelease>;
  listReleases(): Promise<DatasetRelease[]>;
  getRelease(version: string): Promise<DatasetRelease | null>;
  getArtifact(version: string): Promise<Readable | null>;
}

interface ArtifactGenerationState {
  eventCount: number;
}

function mapSnapshot(snapshot: DatasetReleaseSnapshot): DatasetRelease {
  return {
    releaseId: snapshot.releaseId,
    version: snapshot.version,
    createdAt: snapshot.createdAt,
    formatVersion: DATASET_RELEASE_FORMAT_VERSION,
    scope: DATASET_RELEASE_SCOPE,
    eventCount: snapshot.eventCount,
    checksum: snapshot.checksum,
    fields: [...fields],
  };
}

function artifactHeader(): Buffer {
  return Buffer.from(
    `{"formatVersion":${JSON.stringify(DATASET_RELEASE_FORMAT_VERSION)},` +
      `"scope":${JSON.stringify(DATASET_RELEASE_SCOPE)},` +
      `"fields":${JSON.stringify(fields)},"events":[`,
  );
}

async function* generateArtifact(
  repository: DatasetReleaseRepository,
  pageSize: number,
  hash: ReturnType<typeof createHash>,
  state: ArtifactGenerationState,
): AsyncGenerator<Buffer> {
  const emit = (bytes: Buffer) => {
    hash.update(bytes);
    return bytes;
  };

  yield emit(artifactHeader());
  let cursor: DatasetReleaseEventCursor | null = null;
  let firstEvent = true;

  while (true) {
    const page = await repository.loadPublishedEventPage(cursor, pageSize);
    for (const event of page.events) {
      const serialized = JSON.stringify(event);
      if (serialized === undefined) {
        throw new Error('A published dataset event could not be serialized.');
      }
      yield emit(Buffer.from(`${firstEvent ? '' : ','}${serialized}`));
      firstEvent = false;
      state.eventCount += 1;
    }

    if (page.events.length < pageSize || !page.nextCursor) {
      break;
    }
    cursor = page.nextCursor;
  }

  yield emit(Buffer.from(']}'));
}

function artifactStorageKey(): string {
  return `dataset-releases/${randomUUID()}.json`;
}

export function createDatasetReleaseService(
  repository: DatasetReleaseRepository = createDatasetReleaseRepository(),
  objectStore?: ObjectStore,
  pageSize = DATASET_RELEASE_EVENT_PAGE_SIZE,
): DatasetReleaseService {
  return {
    async createRelease(input) {
      const existing = await repository.findByVersion(input.version);
      if (existing) {
        return mapSnapshot(existing);
      }
      if (!objectStore) {
        throw new ObjectStorageError('Dataset release object storage is not configured.');
      }

      const key = artifactStorageKey();
      const hash = createHash('sha256');
      const state: ArtifactGenerationState = { eventCount: 0 };
      const source = Readable.from(generateArtifact(repository, pageSize, hash, state));

      try {
        const stored = await objectStore.write(key, source);
        const result = await repository.createOrFind({
          version: input.version,
          formatVersion: DATASET_RELEASE_FORMAT_VERSION,
          scope: DATASET_RELEASE_SCOPE,
          eventCount: state.eventCount,
          fields,
          artifactStorageKey: key,
          artifactProviderVersionId: stored.versionId,
          checksum: hash.digest('hex'),
        });

        if (!result.created) {
          try {
            await objectStore.delete(key);
          } catch {
            // Reconciliation can retry deletion of an unreferenced race-losing object.
          }
        }

        return mapSnapshot(result.snapshot);
      } catch (error) {
        source.destroy();
        try {
          await objectStore.delete(key);
        } catch {
          // Reconciliation can retry deletion if object storage is temporarily unavailable.
        }
        throw error;
      }
    },

    async listReleases() {
      const releases = await repository.list();
      return releases.map(mapSnapshot);
    },

    async getRelease(version) {
      const release = await repository.findByVersion(version);
      return release ? mapSnapshot(release) : null;
    },

    async getArtifact(version) {
      const reference = await repository.findArtifactReferenceByVersion(version);
      if (!reference) {
        return null;
      }
      if (reference.storageKey) {
        if (!objectStore) {
          throw new ObjectStorageError('Dataset release object storage is not configured.');
        }
        return objectStore.read(reference.storageKey);
      }
      return reference.legacyArtifactText === null
        ? null
        : Readable.from(Buffer.from(reference.legacyArtifactText));
    },
  };
}

import {
  createDatasetReleaseSchema,
  datasetReleaseVersionSchema,
} from '@sport-analytics/contracts';
import { Router } from 'express';
import { pipeline } from 'node:stream';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireAdministrator } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import type { DatasetReleaseService } from './dataset-release.service';

export function createDatasetReleaseRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: DatasetReleaseService,
): Router {
  const router = Router();
  const authenticate = requireAuthentication(verifyAccessToken, synchronizeAccount);

  router.post(
    '/admin/dataset-releases',
    authenticate,
    requireAdministrator(),
    (request, response, next) => {
      const parsed = createDatasetReleaseSchema.safeParse(request.body);
      if (!parsed.success) {
        response
          .status(400)
          .json({ error: { code: 'VALIDATION_FAILED', message: 'The request is invalid.' } });
        return;
      }
      void service
        .createRelease(parsed.data)
        .then((release) => response.status(201).json({ data: release }))
        .catch(next);
    },
  );

  router.get('/dataset-releases', (_request, response, next) => {
    void service
      .listReleases()
      .then((releases) => response.status(200).json({ data: releases }))
      .catch(next);
  });

  router.get('/dataset-releases/:version', (request, response, next) => {
    const version = datasetReleaseVersionSchema.safeParse(request.params.version);
    if (!version.success) {
      response
        .status(404)
        .json({ error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } });
      return;
    }
    void service
      .getRelease(version.data)
      .then((release) => {
        if (!release) {
          response
            .status(404)
            .json({ error: { code: 'NOT_FOUND', message: 'Dataset release not found.' } });
          return;
        }
        response.status(200).json({ data: release });
      })
      .catch(next);
  });

  router.get('/dataset-releases/:version/artifact.json', (request, response, next) => {
    const version = datasetReleaseVersionSchema.safeParse(request.params.version);
    if (!version.success) {
      response
        .status(404)
        .json({ error: { code: 'NOT_FOUND', message: 'Dataset release artifact not found.' } });
      return;
    }
    void service
      .getArtifact(version.data)
      .then((artifact) => {
        if (!artifact) {
          response
            .status(404)
            .json({ error: { code: 'NOT_FOUND', message: 'Dataset release artifact not found.' } });
          return;
        }
        response.type('application/json').attachment(`dataset-release-${version.data}.json`);
        pipeline(artifact, response, (error) => {
          if (error) {
            next(error);
          }
        });
      })
      .catch(next);
  });

  return router;
}

