import type { Logger } from './logger';

export interface ReceivedJob {
  body: unknown;
  deliveryCount: number;
  messageId: string;
}

export interface DeliverySubscription {
  close(): Promise<void>;
}

export interface DeliveryReceiver {
  subscribe(handlers: {
    processError(error: Error): Promise<void>;
    processMessage(message: ReceivedJob): Promise<void>;
  }): DeliverySubscription;
  complete(message: ReceivedJob): Promise<void>;
  abandon(message: ReceivedJob): Promise<void>;
  deadLetter(message: ReceivedJob, reason: string, description: string): Promise<void>;
  close(): Promise<void>;
}

export interface DeliveryMetrics {
  active: number;
  abandoned: number;
  completed: number;
  deadLettered: number;
  deliveryErrors: number;
  received: number;
}

export class PermanentJobError extends Error {
  constructor(
    readonly reason: string,
    message: string,
  ) {
    super(message);
    this.name = 'PermanentJobError';
  }
}

type JobHandler = (message: ReceivedJob, signal: AbortSignal) => Promise<void>;

export class DeliveryPump {
  private readonly controller = new AbortController();
  private readonly activeTasks = new Set<Promise<void>>();
  private subscription: DeliverySubscription | undefined;
  private stopping = false;
  readonly metrics: DeliveryMetrics = {
    active: 0,
    abandoned: 0,
    completed: 0,
    deadLettered: 0,
    deliveryErrors: 0,
    received: 0,
  };

  constructor(
    private readonly receiver: DeliveryReceiver,
    private readonly handler: JobHandler,
    private readonly logger: Logger,
  ) {}

  start(): void {
    if (this.subscription) throw new Error('Delivery pump has already started.');
    this.subscription = this.receiver.subscribe({
      processMessage: async (message) => this.track(message),
      processError: async (error) => {
        this.metrics.deliveryErrors += 1;
        this.logger.error('Service Bus delivery error.', { errorName: error.name });
      },
    });
    this.logger.info('Service Bus delivery pump started.');
  }

  private track(message: ReceivedJob): Promise<void> {
    const task = this.process(message);
    this.activeTasks.add(task);
    this.metrics.active = this.activeTasks.size;
    const removeTask = () => {
      this.activeTasks.delete(task);
      this.metrics.active = this.activeTasks.size;
    };
    // Use both handlers so the cleanup promise cannot become an unhandled rejection.
    void task.then(removeTask, removeTask);
    return task;
  }

  private async process(message: ReceivedJob): Promise<void> {
    this.metrics.received += 1;
    this.logger.info('Job delivery received.', {
      messageId: message.messageId,
      deliveryCount: message.deliveryCount,
    });

    if (this.stopping) {
      await this.receiver.abandon(message);
      this.metrics.abandoned += 1;
      return;
    }

    try {
      await this.handler(message, this.controller.signal);
      await this.receiver.complete(message);
      this.metrics.completed += 1;
      this.logger.info('Job delivery completed.', { messageId: message.messageId });
    } catch (error) {
      if (error instanceof PermanentJobError) {
        await this.receiver.deadLetter(message, error.reason, error.message);
        this.metrics.deadLettered += 1;
        this.logger.warn('Job delivery dead-lettered.', {
          messageId: message.messageId,
          reason: error.reason,
        });
        return;
      }

      await this.receiver.abandon(message);
      this.metrics.abandoned += 1;
      this.logger.warn('Job delivery abandoned for retry.', {
        messageId: message.messageId,
        errorName: error instanceof Error ? error.name : 'UnknownError',
      });
    }
  }

  async stop(timeoutMs: number): Promise<boolean> {
    if (this.stopping) return this.activeTasks.size === 0;
    this.stopping = true;
    this.logger.info('Stopping Service Bus delivery pump.', { active: this.activeTasks.size });
    // Begin stopping deliveries immediately. Some SDK implementations wait for active
    // handlers in close(), so do not let that consume the worker's whole drain budget.
    const subscriptionClosed = this.subscription?.close() ?? Promise.resolve();

    let timeout: NodeJS.Timeout | undefined;
    const drained = await Promise.race([
      Promise.allSettled([...this.activeTasks]).then(() => true),
      new Promise<false>((resolve) => {
        timeout = setTimeout(() => resolve(false), timeoutMs);
      }),
    ]);
    if (timeout) clearTimeout(timeout);
    if (!drained) {
      this.controller.abort();
      this.logger.warn(
        'Worker drain deadline expired; active locks will recover by abandon or expiry.',
        {
          active: this.activeTasks.size,
        },
      );
      await Promise.race([
        Promise.allSettled([...this.activeTasks]),
        new Promise<void>((resolve) => setTimeout(resolve, 1_000)),
      ]);
    }
    await Promise.race([
      subscriptionClosed,
      new Promise<void>((resolve) => setTimeout(resolve, 1_000)),
    ]);
    await this.receiver.close();
    return drained;
  }
}

import type { Environment } from '../../config/env';
import {
  createAzureObjectStorageComposition,
  type AzureObjectStorageComposition,
} from './azure-object-storage.composition';
import type { BatchPayloadStorageService } from './batch-payload-storage.service';
import { FilesystemObjectStore } from './filesystem-object-store';
import type { ObjectStore } from './object-store';

export interface ObjectStorageComposition {
  objectStore: ObjectStore;
  batchPayloadStorageService?: BatchPayloadStorageService;
}

export interface ObjectStorageCompositionFactories {
  createAzure(environment: Environment): AzureObjectStorageComposition;
  createFilesystem(root: string): ObjectStore;
}

const defaultFactories: ObjectStorageCompositionFactories = {
  createAzure: createAzureObjectStorageComposition,
  createFilesystem: (root) => new FilesystemObjectStore(root),
};

/** Selects an explicit provider without allowing production to fall back to local storage. */
export function createObjectStorageComposition(
  environment: Environment,
  factories: ObjectStorageCompositionFactories = defaultFactories,
): ObjectStorageComposition | undefined {
  if (!environment.OBJECT_STORAGE_PROVIDER) {
    if (environment.NODE_ENV === 'production') {
      throw new Error('Object storage provider is required in production.');
    }
    return undefined;
  }

  if (environment.OBJECT_STORAGE_PROVIDER === 'azure') {
    return factories.createAzure(environment);
  }

  if (environment.NODE_ENV === 'production') {
    throw new Error('Filesystem object storage is not permitted in production.');
  }
  if (!environment.OBJECT_STORAGE_FILESYSTEM_ROOT) {
    throw new Error('Filesystem object storage root is required for the filesystem provider.');
  }

  return {
    objectStore: factories.createFilesystem(environment.OBJECT_STORAGE_FILESYSTEM_ROOT),
  };
}

import { z } from 'zod';

const optionalNonEmptyString = z.preprocess(
  (value) => (typeof value === 'string' && value.trim() === '' ? undefined : value),
  z.string().trim().min(1).optional(),
);

const environmentSchema = z
  .object({
    NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
    PORT: z.coerce.number().int().positive().max(65_535).default(3000),
    CORS_ORIGINS: z.string().default('http://localhost:5173'),
    SUPABASE_URL: z.string().trim().url('Supabase URL must be a valid URL'),
    SUPABASE_PUBLISHABLE_KEY: z.string().trim().min(1, 'Supabase publishable key is required'),
    SUPABASE_SECRET_KEY: optionalNonEmptyString,
    OBJECT_STORAGE_PROVIDER: z.enum(['azure', 'filesystem']).optional(),
    OBJECT_STORAGE_FILESYSTEM_ROOT: optionalNonEmptyString,
    AZURE_STORAGE_ACCOUNT_NAME: optionalNonEmptyString.pipe(
      z
        .string()
        .regex(
          /^[a-z0-9]{3,24}$/,
          'Azure storage account name must be 3-24 lowercase letters or numbers',
        )
        .optional(),
    ),
    AZURE_STORAGE_CONTAINER_NAME: optionalNonEmptyString.pipe(
      z
        .string()
        .regex(
          /^(?!.*--)[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])$/,
          'Azure storage container name must be 3-63 lowercase letters, numbers or single hyphens',
        )
        .optional(),
    ),
  })
  .superRefine((environment, context) => {
    if (environment.NODE_ENV === 'production') {
      if (!environment.OBJECT_STORAGE_PROVIDER) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['OBJECT_STORAGE_PROVIDER'],
          message: 'Object storage provider is required in production',
        });
      } else if (environment.OBJECT_STORAGE_PROVIDER !== 'azure') {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['OBJECT_STORAGE_PROVIDER'],
          message: 'Production object storage provider must be azure',
        });
      }
    }

    if (
      environment.OBJECT_STORAGE_PROVIDER === 'filesystem' &&
      !environment.OBJECT_STORAGE_FILESYSTEM_ROOT
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['OBJECT_STORAGE_FILESYSTEM_ROOT'],
        message: 'Filesystem object storage root is required for the filesystem provider',
      });
    }

    if (environment.OBJECT_STORAGE_PROVIDER === 'azure') {
      if (!environment.AZURE_STORAGE_ACCOUNT_NAME) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['AZURE_STORAGE_ACCOUNT_NAME'],
          message: 'Azure storage account name is required for the Azure provider',
        });
      }

      if (!environment.AZURE_STORAGE_CONTAINER_NAME) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['AZURE_STORAGE_CONTAINER_NAME'],
          message: 'Azure storage container name is required for the Azure provider',
        });
      }
    }
  });

export type Environment = z.infer<typeof environmentSchema>;

export function loadEnvironment(source: NodeJS.ProcessEnv = process.env): Environment {
  const result = environmentSchema.safeParse(source);

  if (!result.success) {
    const details = result.error.issues
      .map((issue) => `${issue.path.join('.') || 'environment'}: ${issue.message}`)
      .join('; ');

    throw new Error(`Invalid environment configuration: ${details}`);
  }

  return result.data;
}

