        i.fixture_id::text AS "fixtureId", i.ordinal AS "inningsOrdinal",
        d.innings_sequence AS "sequenceNumber", d.delivery_id::text AS "eventId"
        FROM delivery_current d
        INNER JOIN innings i ON i.innings_id=d.innings_id
        INNER JOIN submission s ON s.submission_id=d.submission_id AND s.status='accepted'
        ${cursorPredicate}
        ORDER BY i.fixture_id, i.ordinal, d.innings_sequence, d.delivery_id
        LIMIT ${limitParameter}`, parameters);
      const last = result.rows.at(-1);
      return { events: result.rows.map((row) => row.event), nextCursor: last ? { fixtureId: last.fixtureId, inningsOrdinal: last.inningsOrdinal, sequenceNumber: last.sequenceNumber, eventId: last.eventId } : null };
    },

    async requestGeneration(input) {
      if (executor) throw new Error('Dataset release generation requests require a transactional database pool.');
      return withTransaction(getDatabasePool(), async (client) => {
        await executeQuery(client, `SELECT pg_advisory_xact_lock(hashtext($1))`, [`dataset-release:${input.deploymentEnvironment}:${input.version}`]);
        const existingRelease = await executeQuery<DatasetReleaseRow>(client, `SELECT ${snapshotColumns} FROM dataset_release WHERE deployment_environment=$1 AND version=$2`, [input.deploymentEnvironment, input.version]);
        if (existingRelease.rows[0]) return { release: existingRelease.rows[0], job: null };

        const existingJob = await executeQuery<{ jobId: string; state: DatasetReleaseJobRecord['state'] }>(client, `SELECT j.job_id::text AS "jobId", j.state FROM dataset_release_job drj INNER JOIN background_job j ON j.job_id=drj.job_id WHERE drj.deployment_environment=$1 AND drj.requested_version=$2 FOR UPDATE OF j, drj`, [input.deploymentEnvironment, input.version]);
        let jobId = existingJob.rows[0]?.jobId;
        if (!jobId) {
          jobId = randomUUID();
          await executeQuery(client, `INSERT INTO background_job (job_id,job_type,contract_version,idempotency_key,owner_id) VALUES ($1::uuid,'dataset-release.generate',1,$2,$3::bigint)`, [jobId, `dataset-release.generate:${input.deploymentEnvironment}:${input.version}`, input.requesterId]);
          await executeQuery(client, `INSERT INTO dataset_release_job (job_id,requested_version,deployment_environment,storage_provider) VALUES ($1::uuid,$2,$3,$4)`, [jobId, input.version, input.deploymentEnvironment, input.storageProvider]);
        } else if (['failed', 'dead_lettered'].includes(existingJob.rows[0]!.state)) {
          await executeQuery(client, `UPDATE background_job SET state='queued',progress_current=0,progress_total=NULL,attempt_count=0,started_at=NULL,completed_at=NULL,last_error_code=NULL,last_error_message=NULL WHERE job_id=$1::uuid`, [jobId]);
          await executeQuery(client, `UPDATE dataset_release_job SET events_processed=0,bytes_written=0,page_number=0,last_fixture_id=NULL,last_innings_ordinal=NULL,last_sequence_number=NULL,last_event_id=NULL,lease_owner=NULL,lease_expires_at=NULL,attempt_storage_key=NULL,storage_provider=$2 WHERE job_id=$1::uuid`, [jobId, input.storageProvider]);
        }

        if (!existingJob.rows[0] || ['failed', 'dead_lettered'].includes(existingJob.rows[0].state)) {
          const messageId = randomUUID();
          await executeQuery(client, `INSERT INTO outbox_message (outbox_message_id,job_id,message_type,contract_version,body) VALUES ($1::uuid,$2::uuid,'dataset-release.generate',1,jsonb_build_object('type','dataset-release.generate','version',1,'commandId',$1::text,'jobId',$2::text,'releaseVersion',$3,'deploymentEnvironment',$4))`, [messageId, jobId, input.version, input.deploymentEnvironment]);
        }
        return { release: null, job: await findJobOn(client, jobId, input.deploymentEnvironment) };
      });
    },

    findJob(jobId, deploymentEnvironment) { return findJobOn(database(), jobId, deploymentEnvironment); },
    async list(deploymentEnvironment) {
      const result = await executeQuery<DatasetReleaseRow>(database(), `SELECT ${snapshotColumns} FROM dataset_release WHERE deployment_environment=$1 ORDER BY created_at DESC,version DESC`, [deploymentEnvironment]);
      return result.rows;
    },
    findByVersion,
    async findArtifactReferenceByVersion(version, deploymentEnvironment) {
      const result = await executeQuery<DatasetReleaseRow>(database(), `SELECT artifact_storage_key AS "artifactStorageKey",artifact_text AS "artifactText",artifact_storage_location AS "artifactStorageLocation" FROM dataset_release WHERE deployment_environment=$1 AND version=$2`, [deploymentEnvironment, version]);
      const row = result.rows[0];
      return row ? { storageKey: row.artifactStorageKey ?? null, legacyArtifactText: row.artifactText ?? null, storageLocation: row.artifactStorageLocation ?? null } : null;
    },
  };
}

