  { name: 'nonStrikerParticipantId', description: 'Stable non-striker participant identifier.' },
  { name: 'bowlerParticipantId', description: 'Stable bowler participant identifier.' },
  { name: 'runsOffBat', description: 'Runs credited to the striker.' },
  { name: 'runsExtras', description: 'Extra runs on the delivery.' },
  { name: 'runsTotal', description: 'Total runs on the delivery.' },
] as const;

export interface DatasetReleaseRequestResult {
  release: DatasetRelease | null;
  job: DatasetReleaseJob | null;
}

export interface DatasetReleaseService {
  requestRelease(input: CreateDatasetRelease, requesterId: string): Promise<DatasetReleaseRequestResult>;
  getJob(jobId: string): Promise<DatasetReleaseJob | null>;
  listReleases(): Promise<DatasetRelease[]>;
  getRelease(version: string): Promise<DatasetRelease | null>;
  getArtifact(version: string): Promise<Readable | null>;
}

export interface DatasetReleaseServiceOptions {
  deploymentEnvironment: string;
  storageProvider?: 'azure' | 'filesystem';
  releaseObjectStore?: ObjectStore;
  legacyObjectStore?: ObjectStore;
}

function mapSnapshot(snapshot: DatasetReleaseSnapshot): DatasetRelease {
  return { releaseId: snapshot.releaseId, version: snapshot.version, createdAt: snapshot.createdAt,
    formatVersion: DATASET_RELEASE_FORMAT_VERSION, scope: DATASET_RELEASE_SCOPE,
    eventCount: snapshot.eventCount, checksum: snapshot.checksum, fields: [...DATASET_RELEASE_FIELDS] };
}

function mapJob(job: DatasetReleaseJobRecord): DatasetReleaseJob {
  const status = job.state === 'queued' ? 'pending' : job.state === 'running' ? 'generating' : job.state === 'succeeded' ? 'completed' : 'failed';
  return { jobId: job.jobId, version: job.version, status, eventsProcessed: job.eventsProcessed,
