+        if (row) await handlers.processMessage({ ...row, messageId: row.outboxMessageId });
+      } catch (error) {
+        await handlers.processError(error instanceof Error ? error : new Error('Database delivery failed.'));
+      }
+    };
+    this.timer = setInterval(() => void poll(), this.pollMs);
+    void poll();
+    return { close: async () => { if (this.timer) clearInterval(this.timer); } };
+  }
+
+  async complete(message: ReceivedJob): Promise<void> {
+    const item = requireDatabaseMessage(message);
+    await this.database.query(`UPDATE outbox_message SET published_at=now(),claim_owner=NULL,claim_expires_at=NULL WHERE outbox_message_id=$1::uuid AND claim_owner=$2`, [item.outboxMessageId, this.workerId]);
+  }
+
+  async abandon(message: ReceivedJob): Promise<void> {
+    const item = requireDatabaseMessage(message);
+    await this.database.query(`UPDATE outbox_message SET claim_owner=NULL,claim_expires_at=NULL WHERE outbox_message_id=$1::uuid AND claim_owner=$2`, [item.outboxMessageId, this.workerId]);
+  }
