+  if (environment.OBJECT_STORAGE_PROVIDER === 'azure') {
+    const account = environment.AZURE_STORAGE_ACCOUNT_NAME!;
+    const ingestionName = environment.AZURE_STORAGE_INGESTION_CONTAINER_NAME ?? environment.AZURE_STORAGE_CONTAINER_NAME!;
