import { createHash, randomUUID } from 'node:crypto';
import { Readable } from 'node:stream';

import { DATASET_RELEASE_FIELDS, DATASET_RELEASE_FORMAT_VERSION, DATASET_RELEASE_SCOPE } from '@sport-analytics/contracts';
import type { ObjectStore } from '@sport-analytics/object-storage';
import type { Pool, PoolClient } from 'pg';

import { PermanentJobError, type ReceivedJob } from './delivery-pump';
import type { Logger } from './logger';

const PAGE_SIZE = 10_000;

interface Cursor { fixtureId: string; inningsOrdinal: number; sequenceNumber: number; eventId: string }
interface EventRow extends Cursor { event: unknown }
interface Claim { terminal: boolean; attemptCount: number; maxAttempts: number; previousKey: string | null }
interface Command { type: 'dataset-release.generate'; version: 1; jobId: string; releaseVersion: string; deploymentEnvironment: string }

class LeaseBusyError extends Error {}

async function transaction<T>(database: Pool, operation: (client: PoolClient) => Promise<T>): Promise<T> {
  const client = await database.connect();
  try {
    await client.query('BEGIN');
    const result = await operation(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK').catch(() => undefined);
    throw error;
  } finally { client.release(); }
}

function parseCommand(message: ReceivedJob): Command {
  const body = message.body as Partial<Command> | null;
  if (!body || body.type !== 'dataset-release.generate' || body.version !== 1 ||
      typeof body.jobId !== 'string' || typeof body.releaseVersion !== 'string' || typeof body.deploymentEnvironment !== 'string') {
    throw new PermanentJobError('UnsupportedJobContract', 'Dataset release command is invalid.');
  }
  return body as Command;
}

export function createDatasetReleaseJobHandler(
  database: Pool,
  objectStore: ObjectStore,
  logger: Logger,
  options: { workerId: string; leaseMs: number; deploymentEnvironment: string; storageProvider: 'azure' | 'filesystem'; pageSize?: number },
) {
  const pageSize = options.pageSize ?? PAGE_SIZE;

  async function claim(command: Command): Promise<Claim> {
    if (command.deploymentEnvironment !== options.deploymentEnvironment) {
      throw new PermanentJobError('DeploymentEnvironmentMismatch', 'Dataset release command belongs to another deployment environment.');
    }
    return transaction(database, async (client) => {
      const result = await client.query<{ state: string; attemptCount: number; maxAttempts: number; leaseOwner: string | null; leaseExpiresAt: Date | null; storageProvider: string; attemptStorageKey: string | null }>(`
        SELECT j.state::text,j.attempt_count AS "attemptCount",j.max_attempts AS "maxAttempts",
          drj.lease_owner AS "leaseOwner",drj.lease_expires_at AS "leaseExpiresAt",
          drj.storage_provider AS "storageProvider",drj.attempt_storage_key AS "attemptStorageKey"
        FROM background_job j INNER JOIN dataset_release_job drj ON drj.job_id=j.job_id
        WHERE j.job_id=$1::uuid AND j.job_type='dataset-release.generate' AND j.contract_version=1
          AND drj.requested_version=$2 AND drj.deployment_environment=$3
        FOR UPDATE OF j,drj`, [command.jobId, command.releaseVersion, command.deploymentEnvironment]);
      const row = result.rows[0];
      if (!row) throw new PermanentJobError('JobNotFound', 'Dataset release job does not exist.');
      if (row.storageProvider !== options.storageProvider) throw new PermanentJobError('StorageProviderMismatch', 'Dataset release job storage provider does not match this worker.');
      if (row.state === 'succeeded') return { terminal: true, attemptCount: row.attemptCount, maxAttempts: row.maxAttempts, previousKey: null };
      if (!['queued', 'running', 'failed'].includes(row.state)) throw new PermanentJobError('JobNotRunnable', 'Dataset release job is not runnable.');
      if (row.leaseOwner && row.leaseOwner !== options.workerId && row.leaseExpiresAt && row.leaseExpiresAt.getTime() > Date.now()) throw new LeaseBusyError();
      if (row.attemptCount >= row.maxAttempts) throw new PermanentJobError('AttemptBudgetExhausted', 'Dataset release retry budget is exhausted.');
      const attemptCount = row.attemptCount + 1;
      await client.query(`UPDATE background_job SET state='running',attempt_count=$2,started_at=COALESCE(started_at,now()),completed_at=NULL,last_error_code=NULL,last_error_message=NULL WHERE job_id=$1::uuid`, [command.jobId, attemptCount]);
      await client.query(`UPDATE dataset_release_job SET events_processed=0,bytes_written=0,page_number=0,last_fixture_id=NULL,last_innings_ordinal=NULL,last_sequence_number=NULL,last_event_id=NULL,lease_owner=$2,lease_expires_at=now()+($3::integer*interval '1 millisecond'),attempt_storage_key=NULL WHERE job_id=$1::uuid`, [command.jobId, options.workerId, options.leaseMs]);
      return { terminal: false, attemptCount, maxAttempts: row.maxAttempts, previousKey: row.attemptStorageKey };
    });
  }

  async function loadPage(cursor: Cursor | null): Promise<{ events: unknown[]; next: Cursor | null }> {
    const predicate = cursor ? `WHERE (i.fixture_id,i.ordinal)>=($1::bigint,$2::integer) AND (i.fixture_id,i.ordinal,d.innings_sequence,d.delivery_id)>($1::bigint,$2::integer,$3::integer,$4::bigint)` : '';
    const params = cursor ? [cursor.fixtureId,cursor.inningsOrdinal,cursor.sequenceNumber,cursor.eventId,pageSize] : [pageSize];
    const limit = cursor ? '$5' : '$1';
    const result = await database.query<EventRow>(`SELECT json_build_object(
      'eventId',d.delivery_id::text,'fixtureId',i.fixture_id::text,'inningsId',i.innings_id::text,
      'inningsOrdinal',i.ordinal,'sequenceNumber',d.innings_sequence,'overNumber',d.over_number,
      'positionInOver',d.position_in_over,'ballNumber',d.ball_number,'strikerParticipantId',d.striker_id::text,
      'nonStrikerParticipantId',d.non_striker_id::text,'bowlerParticipantId',d.bowler_id::text,
      'runsOffBat',d.runs_off_bat,'runsExtras',d.runs_extras,'runsTotal',d.runs_total) AS event,
      i.fixture_id::text AS "fixtureId",i.ordinal AS "inningsOrdinal",d.innings_sequence AS "sequenceNumber",d.delivery_id::text AS "eventId"
      FROM delivery_current d INNER JOIN innings i ON i.innings_id=d.innings_id
      INNER JOIN submission s ON s.submission_id=d.submission_id AND s.status='accepted'
      ${predicate} ORDER BY i.fixture_id,i.ordinal,d.innings_sequence,d.delivery_id LIMIT ${limit}`, params);
    const last = result.rows.at(-1);
    return { events: result.rows.map((row) => row.event), next: last ? { fixtureId:last.fixtureId,inningsOrdinal:last.inningsOrdinal,sequenceNumber:last.sequenceNumber,eventId:last.eventId } : null };
  }

  async function updateProgress(jobId: string, cursor: Cursor | null, events: number, bytes: number, page: number) {
    const result = await database.query(`UPDATE dataset_release_job SET events_processed=$3,bytes_written=$4,page_number=$5,last_fixture_id=$6::bigint,last_innings_ordinal=$7,last_sequence_number=$8,last_event_id=$9::bigint,lease_expires_at=now()+($10::integer*interval '1 millisecond') WHERE job_id=$1::uuid AND lease_owner=$2`, [jobId,options.workerId,events,bytes,page,cursor?.fixtureId ?? null,cursor?.inningsOrdinal ?? null,cursor?.sequenceNumber ?? null,cursor?.eventId ?? null,options.leaseMs]);
    if (result.rowCount !== 1) throw new LeaseBusyError();
    await database.query(`UPDATE background_job SET progress_current=$2 WHERE job_id=$1::uuid`, [jobId, events]);
  }

  async function markFailed(jobId: string, attemptCount: number, maxAttempts: number, error: unknown) {
    const permanent = attemptCount >= maxAttempts;
    const code = error instanceof LeaseBusyError ? 'LeaseBusy' : error instanceof Error ? error.name : 'GenerationFailed';
    const message = error instanceof LeaseBusyError ? 'Another worker owns the active generation lease.' : 'Dataset release generation failed; see safe worker progress logs.';
    await database.query(`UPDATE background_job SET state=$2::background_job_state,completed_at=CASE WHEN $2='dead_lettered' THEN now() ELSE NULL END,last_error_code=$3,last_error_message=$4 WHERE job_id=$1::uuid AND state<>'succeeded'`, [jobId, permanent ? 'dead_lettered' : 'failed', code, message]);
    await database.query(`UPDATE dataset_release_job SET lease_owner=NULL,lease_expires_at=NULL,attempt_storage_key=NULL WHERE job_id=$1::uuid AND lease_owner=$2`, [jobId, options.workerId]);
    if (permanent) throw new PermanentJobError('AttemptBudgetExhausted', message);
  }

  async function handler(message: ReceivedJob, signal: AbortSignal): Promise<void> {
    const command = parseCommand(message);
    const started = Date.now();
    const claimed = await claim(command);
    if (claimed.terminal) return;
    if (claimed.previousKey) await objectStore.delete(claimed.previousKey).catch(() => undefined);
    const storageKey = `${randomUUID()}.json`;
    await database.query(`UPDATE dataset_release_job SET attempt_storage_key=$2 WHERE job_id=$1::uuid AND lease_owner=$3`, [command.jobId, storageKey, options.workerId]);
    let events = 0, bytes = 0, page = 0;
    const hash = createHash('sha256');
    const emit = (value: string) => { const chunk=Buffer.from(value); hash.update(chunk); bytes += chunk.length; return chunk; };
    async function* artifact() {
      yield emit(`{"formatVersion":${JSON.stringify(DATASET_RELEASE_FORMAT_VERSION)},"scope":${JSON.stringify(DATASET_RELEASE_SCOPE)},"fields":${JSON.stringify(DATASET_RELEASE_FIELDS)},"events":[`);
