        if (signal.aborted) throw new Error('Dataset release generation was interrupted.');
        page += 1;
        logger.info('Dataset release database page read started.', { jobId: command.jobId, releaseVersion: command.releaseVersion, pageNumber: page, eventsProcessed: events, bytesWritten: bytes });
        const loaded = await loadPage(cursor);
        for (const event of loaded.events) {
          const serialized = JSON.stringify(event);
          if (serialized === undefined) throw new Error('A published dataset event could not be serialized.');
          yield emit(`${first ? '' : ','}${serialized}`); first=false; events += 1;
        }
        cursor = loaded.next;
        await updateProgress(command.jobId,cursor,events,bytes,page);
        logger.info('Dataset release database page read completed.', { jobId: command.jobId, releaseVersion: command.releaseVersion, pageNumber: page, eventsProcessed: events, bytesWritten: bytes, lastFixtureId: cursor?.fixtureId, lastInningsOrdinal: cursor?.inningsOrdinal, lastSequenceNumber: cursor?.sequenceNumber, lastEventId: cursor?.eventId, elapsedMs: Date.now()-started });
