      const stored = await objectStore.write(storageKey, source);
      const checksum = hash.digest('hex');
      logger.info('Dataset release artifact write completed.', { jobId: command.jobId, releaseVersion: command.releaseVersion, eventsProcessed: events, bytesWritten: bytes, elapsedMs: Date.now()-started });
      const created = await transaction(database, async (client) => {
        await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [`dataset-release:${command.deploymentEnvironment}:${command.releaseVersion}`]);
        const inserted = await client.query<{ releaseId: string }>(`INSERT INTO dataset_release (version,deployment_environment,format_version,scope,event_count,fields,artifact_storage_key,artifact_provider_version_id,artifact_storage_provider,artifact_storage_location,checksum_sha256) VALUES ($1,$2,$3,$4,$5,$6::jsonb,$7,$8,$9,'release',$10) ON CONFLICT (deployment_environment,version) DO NOTHING RETURNING release_id::text AS "releaseId"`, [command.releaseVersion,command.deploymentEnvironment,DATASET_RELEASE_FORMAT_VERSION,DATASET_RELEASE_SCOPE,events,JSON.stringify(DATASET_RELEASE_FIELDS),storageKey,stored.versionId,options.storageProvider,checksum]);
        let releaseId=inserted.rows[0]?.releaseId;
        if (!releaseId) releaseId=(await client.query<{ releaseId:string }>(`SELECT release_id::text AS "releaseId" FROM dataset_release WHERE deployment_environment=$1 AND version=$2`,[command.deploymentEnvironment,command.releaseVersion])).rows[0]!.releaseId;
