import { createHash } from 'node:crypto';
import { mkdtemp, readFile, readdir, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

import request from 'supertest';
import { afterEach, describe, expect, test } from 'vitest';

import type { Environment } from '../../src/config/env';
import type {
  DatasetReleaseArtifactReference,
  DatasetReleaseRepository,
  DatasetReleaseSnapshot,
} from '../../src/modules/dataset-releases/dataset-release.repository';
import { createDatasetReleaseService } from '../../src/modules/dataset-releases/dataset-release.service';
import { createObjectStorageComposition } from '../../src/modules/object-storage/object-storage.composition';
import { createTestAccount, createTestApp } from '../test-app';

const temporaryRoots: string[] = [];

class LocalReleaseRepository implements DatasetReleaseRepository {
  private snapshot: DatasetReleaseSnapshot | null = null;
  private artifact: DatasetReleaseArtifactReference | null = null;

  async loadPublishedEventPage() {
    return {
      events: [
        { eventId: '1', runsTotal: 4 },
        { eventId: '2', runsTotal: 1 },
      ],
      nextCursor: null,
    };
  }

  async createOrFind(input: {
    version: string;
    eventCount: number;
    checksum: string;
    artifactStorageKey: string;
  }) {
    this.snapshot = {
      releaseId: '01234567-89ab-cdef-0123-456789abcdef',
      version: input.version,
      createdAt: '2026-09-14T12:00:00.000Z',
      eventCount: input.eventCount,
      checksum: input.checksum,
    };
    this.artifact = { storageKey: input.artifactStorageKey, legacyArtifactText: null };
    return { snapshot: this.snapshot, created: true };
  }

  async list() {
    return this.snapshot ? [this.snapshot] : [];
  }

  async findByVersion(version: string) {
    return this.snapshot?.version === version ? this.snapshot : null;
  }

  async findArtifactReferenceByVersion(version: string) {
    return this.snapshot?.version === version ? this.artifact : null;
  }
}

afterEach(async () => {
  await Promise.all(
    temporaryRoots.splice(0).map((root) => rm(root, { recursive: true, force: true })),
  );
});

describe('dataset release API with local filesystem object storage', () => {
  test('publishes and publicly streams the exact stored artifact', async () => {
    const root = await mkdtemp(path.join(tmpdir(), 'sport-release-api-'));
    temporaryRoots.push(root);
    const environment: Environment = {
      NODE_ENV: 'development',
      PORT: 3000,
      CORS_ORIGINS: 'http://localhost:5173',
      SUPABASE_URL: 'https://test-project.supabase.co',
      SUPABASE_PUBLISHABLE_KEY: 'test-publishable-key',
      OBJECT_STORAGE_PROVIDER: 'filesystem',
      OBJECT_STORAGE_FILESYSTEM_ROOT: root,
    };
    const composition = createObjectStorageComposition(environment);
    expect(composition).toBeDefined();
    const service = createDatasetReleaseService(
      new LocalReleaseRepository(),
      composition!.objectStore,
    );
    const app = createTestApp(
      undefined,
      undefined,
      async () => createTestAccount({ role: 'admin' }),
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
      service,
    );

    const publication = await request(app)
      .post('/api/v1/admin/dataset-releases')
      .set('Authorization', 'Bearer test')
      .send({ version: 'local-filesystem' })
      .expect(201);
    const storedFiles = await readdir(path.join(root, 'dataset-releases'));
    expect(storedFiles).toHaveLength(1);
    const storedBytes = await readFile(path.join(root, 'dataset-releases', storedFiles[0]!));
    expect(publication.body.data.eventCount).toBe(2);
    expect(publication.body.data.checksum).toBe(
      createHash('sha256').update(storedBytes).digest('hex'),
    );

    const retrieval = await request(app)
      .get('/api/v1/dataset-releases/local-filesystem/artifact.json')
      .expect(200);
    expect(Buffer.from(retrieval.text)).toEqual(storedBytes);
    expect(retrieval.headers['content-length']).toBeUndefined();
  });
});

import type { ContainerClient } from '@azure/storage-blob';
import { DefaultAzureCredential } from '@azure/identity';
import { describe, expect, test, vi } from 'vitest';

import { createApp } from '../../src/app';
import { AzureBlobObjectStore } from '../../src/modules/object-storage/azure-blob-object-store';
import {
  createAzureObjectStorageComposition,
  createDefaultAzureCredential,
  type AzureObjectStorageCompositionFactories,
} from '../../src/modules/object-storage/azure-object-storage.composition';
import { BatchPayloadStorageService } from '../../src/modules/object-storage/batch-payload-storage.service';

const productionStorageEnvironment = {
  AZURE_STORAGE_ACCOUNT_NAME: 'statsthegameblobdev',
  AZURE_STORAGE_CONTAINER_NAME: 'staged-ingestion',
};

describe('production Azure object-storage composition', () => {
  test('selects the configured HTTPS endpoint and container and injects the Azure adapter', () => {
    const credential = { getToken: vi.fn().mockResolvedValue(null) };
    const containerClient = {} as ContainerClient;
    const payloadStorageService = {} as BatchPayloadStorageService;
    const getContainerClient = vi.fn().mockReturnValue(containerClient);
    const createCredential = vi.fn().mockReturnValue(credential);
    const createBlobServiceClient = vi.fn().mockReturnValue({ getContainerClient });
    const createObjectStore = vi
      .fn()
      .mockImplementation((container) => new AzureBlobObjectStore(container));
    const createBatchPayloadStorageService = vi.fn().mockReturnValue(payloadStorageService);
    const factories: AzureObjectStorageCompositionFactories = {
      createCredential,
      createBlobServiceClient,
      createObjectStore,
      createBatchPayloadStorageService,
    };

    const composition = createAzureObjectStorageComposition(
      productionStorageEnvironment,
      factories,
    );

    expect(createCredential).toHaveBeenCalledOnce();
    expect(createBlobServiceClient).toHaveBeenCalledWith(
      'https://statsthegameblobdev.blob.core.windows.net',
      credential,
    );
    expect(getContainerClient).toHaveBeenCalledWith('staged-ingestion');
    expect(createObjectStore).toHaveBeenCalledWith(containerClient);
    expect(composition.objectStore).toBeInstanceOf(AzureBlobObjectStore);
    expect(createBatchPayloadStorageService).toHaveBeenCalledWith(composition.objectStore);
    expect(composition.batchPayloadStorageService).toBe(payloadStorageService);
  });

  test('uses DefaultAzureCredential for the production credential chain without contacting Azure', () => {
    expect(createDefaultAzureCredential()).toBeInstanceOf(DefaultAzureCredential);
  });

  test('installs the composed payload-storage service in the production application', () => {
    const app = createApp({
      environment: {
        NODE_ENV: 'production',
        OBJECT_STORAGE_PROVIDER: 'azure',
        PORT: 3000,
        CORS_ORIGINS: 'https://example.invalid',
        SUPABASE_URL: 'https://test-project.supabase.co',
        SUPABASE_PUBLISHABLE_KEY: 'test-publishable-key',
        ...productionStorageEnvironment,
      },
    });

    expect(app.locals.batchPayloadStorageService).toBeInstanceOf(BatchPayloadStorageService);
  });

  test('fails safely when the storage account is absent', () => {
    expect(() =>
      createAzureObjectStorageComposition({
        AZURE_STORAGE_CONTAINER_NAME: 'staged-ingestion',
      }),
    ).toThrow('Azure storage account name is required for production object storage.');
  });

  test('fails safely when the container is absent', () => {
    expect(() =>
      createAzureObjectStorageComposition({
        AZURE_STORAGE_ACCOUNT_NAME: 'statsthegameblobdev',
      }),
    ).toThrow('Azure storage container name is required for production object storage.');
  });
});

import { describe, expect, it } from 'vitest';

import { loadEnvironment } from '../../src/config/env';

const requiredEnvironment = {
  NODE_ENV: 'test',
  SUPABASE_URL: 'https://test-project.supabase.co',
  SUPABASE_PUBLISHABLE_KEY: 'test-publishable-key',
