          setAccessState({ kind: 'error', message: errorMessage(error) });
        }
      }
    },
    [client],
  );

  useEffect(() => {
    if (isLoading || !isAuthenticated) return;
    const controller = new AbortController();
    void checkAccess(controller.signal);
    return () => controller.abort();
  }, [checkAccess, isAuthenticated, isLoading]);

  useEffect(() => {
    if (versionError || submissionError || release) {
      feedbackRef.current?.focus();
    }
  }, [release, submissionError, versionError]);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (isPublishing || accessState.kind !== 'ready') return;

    const parsedVersion = datasetReleaseVersionSchema.safeParse(version);
    if (!parsedVersion.success) {
      setVersionError(versionGuidance);
      setSubmissionError(undefined);
      setRelease(undefined);
      return;
    }

    setVersionError(undefined);
    setSubmissionError(undefined);
    setRelease(undefined);
    setIsPublishing(true);
    try {
      setRelease(await createAdministratorDatasetRelease(client, { version: parsedVersion.data }));
    } catch (error) {
      setSubmissionError(errorMessage(error));
    } finally {
      setIsPublishing(false);
    }
  }

  if (!isLoading && !isAuthenticated) return <Navigate to="/sign-in" replace />;

  return (
    <section className="admin-release-page content-boundary" aria-labelledby="admin-release-title">
      <header className="page-heading admin-release-page__heading">
        <p className="eyebrow">Administrator workspace</p>
        <h1 id="admin-release-title">Publish dataset release</h1>
        <p>
          Generate a versioned snapshot of published accepted deliveries and make it available to
          public data consumers.
        </p>
      </header>

      {isLoading || accessState.kind === 'loading' ? (
        <div className="state-message" role="status">
          <h2>Checking release permission</h2>
          <p>Confirming that your account can publish dataset releasesâ€¦</p>
        </div>
      ) : accessState.kind === 'forbidden' ? (
        <div className="state-message state-message--error" role="alert">
          <h2>Administrator access required</h2>
          <p>Your signed-in account cannot generate or publish dataset releases.</p>
        </div>
      ) : accessState.kind === 'error' ? (
        <div className="state-message state-message--error" role="alert">
          <h2>Release permission could not be checked</h2>
          <p>{accessState.message}</p>
          <button
            className="button button--secondary"
            type="button"
            onClick={() => void checkAccess()}
          >
            Retry permission check
          </button>
        </div>
      ) : (
        <div className="admin-release-workspace">
          <div className="admin-release-warning">
            <p className="eyebrow">Permanent public action</p>
            <h2>Review the version before publishing</h2>
            <p>
              Publishing immediately creates an immutable snapshot in the public dataset-release
              catalogue. An existing version cannot be overwritten; corrections require a new
              version.
            </p>
          </div>

          <form
            className="admin-release-form"
            noValidate
            onSubmit={(event) => void handleSubmit(event)}
          >
            <div className="field admin-release-form__field">
              <label htmlFor="dataset-release-version">Release version</label>
              <input
                id="dataset-release-version"
                name="version"
                type="text"
                autoComplete="off"
                aria-describedby={`dataset-release-version-help${versionError ? ' dataset-release-version-error' : ''}`}
                aria-invalid={versionError ? 'true' : undefined}
                disabled={isPublishing}
                value={version}
                onChange={(event) => {
                  setVersion(event.target.value);
                  setVersionError(undefined);
                  setSubmissionError(undefined);
                  setRelease(undefined);
                }}
              />
              <p id="dataset-release-version-help" className="field-help">
                {versionGuidance} Example: 2026.09.2
              </p>
              {versionError ? (
                <p id="dataset-release-version-error" className="field-error">
                  {versionError}
                </p>
              ) : null}
            </div>
            <button className="button button--primary" type="submit" disabled={isPublishing}>
              {isPublishing ? 'Publishing releaseâ€¦' : 'Generate and publish snapshot'}
            </button>
          </form>

          {versionError || submissionError ? (
            <div
              ref={feedbackRef}
              className="admin-release-feedback admin-release-feedback--error"
              role="alert"
              tabIndex={-1}
            >
              <h2>Dataset release was not published</h2>
              <p>{versionError ?? submissionError}</p>
            </div>
          ) : null}

          {release ? (
            <div
              ref={feedbackRef}
              className="admin-release-feedback admin-release-feedback--success"
              role="status"
              tabIndex={-1}
            >
              <p className="eyebrow">Public release available</p>
              <h2>Dataset {release.version}</h2>
              <p>This immutable snapshot is now available in the public release catalogue.</p>
              <dl className="admin-release-facts">
                <div>
                  <dt>Created</dt>
                  <dd>{formatCreationTime(release.createdAt)}</dd>
                </div>
                <div>
                  <dt>Events</dt>
                  <dd>{release.eventCount.toLocaleString('en-ZA')}</dd>
                </div>
                <div className="admin-release-facts__checksum">
                  <dt>SHA-256 checksum</dt>
                  <dd>
                    <code>{release.checksum}</code>
                  </dd>
                </div>
              </dl>
              <div className="admin-release-actions">
                <Link
                  className="button button--primary"
                  to={`/dataset-releases/${encodeURIComponent(release.version)}`}
                >
                  View public release
                </Link>
                <a
                  className="button button--secondary"
                  download={`dataset-release-${release.version}.json`}
                  href={datasetReleaseArtifactUrl(release.version)}
                >
                  Download JSON artefact
                </a>
                <Link className="text-link" to="/dataset-releases">
                  Browse release catalogue
                </Link>
              </div>
            </div>
          ) : null}
        </div>
      )}
    </section>
  );
}

import type { AuthChangeEvent, Session, User } from '@supabase/supabase-js';
import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import type { ComponentProps } from 'react';
import { MemoryRouter, Route, Routes } from 'react-router-dom';
import { afterEach, describe, expect, it, vi } from 'vitest';

import { AuthProvider } from '../auth/AuthProvider';
import { AdminDatasetReleasePage } from './AdminDatasetReleasePage';

type AuthClient = ComponentProps<typeof AuthProvider>['client'];

const release = {
  releaseId: '01234567-89ab-cdef-0123-456789abcdef',
  version: '2026.09.2',
  createdAt: '2026-09-10T10:00:00.000Z',
  formatVersion: '1.0',
  scope: 'published-accepted-deliveries',
  eventCount: 1234,
  checksum: 'a'.repeat(64),
  fields: [{ name: 'eventId', description: 'Stable event identifier.' }],
};

function session(): Session {
  const user = {
    id: 'admin-subject',
    aud: 'authenticated',
    role: 'authenticated',
    email: 'admin@example.com',
    app_metadata: {},
    user_metadata: {},
    identities: [],
    created_at: release.createdAt,
  } satisfies User;
  return {
    access_token: 'admin-access-token',
    refresh_token: 'refresh',
    expires_in: 3600,
    token_type: 'bearer',
    user,
  };
}

function authClient(currentSession: Session | null): AuthClient {
  return {
    getSession: vi.fn().mockResolvedValue({ data: { session: currentSession } }),
    onAuthStateChange: vi.fn(
      (_listener: (event: AuthChangeEvent, session: Session | null) => void) => ({
        data: { subscription: { id: 'test', callback: _listener, unsubscribe: vi.fn() } },
      }),
    ),
    signInWithOAuth: vi.fn(),
    signOut: vi.fn(),
  } as unknown as AuthClient;
}

function response(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

function currentUser(role: 'viewer' | 'admin' = 'admin') {
  return response(200, {
    user: {
      id: '1',
      subject: 'admin-subject',
      displayName: 'Administrator',
      role,
      approvalState: 'not_requested',
      requestedCompetition: null,
      competitionIds: [],
    },
  });
}

function renderPage(currentSession: Session | null = session()) {
  render(
    <AuthProvider client={authClient(currentSession)}>
      <MemoryRouter initialEntries={['/admin/dataset-releases/new']}>
        <Routes>
          <Route path="/admin/dataset-releases/new" element={<AdminDatasetReleasePage />} />
          <Route path="/sign-in" element={<h1>Sign in</h1>} />
        </Routes>
      </MemoryRouter>
    </AuthProvider>,
  );
}

describe('administrator dataset release page', () => {
  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it('redirects signed-out visitors and denies non-administrators before showing the form', async () => {
    const signedOutFetch = vi.fn();
    vi.stubGlobal('fetch', signedOutFetch);
    renderPage(null);
    expect(await screen.findByRole('heading', { name: 'Sign in' })).toBeInTheDocument();
    expect(signedOutFetch).not.toHaveBeenCalled();

    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(currentUser('viewer')));
    renderPage();
    expect(await screen.findByRole('alert')).toHaveTextContent('Administrator access required');
    expect(screen.queryByRole('textbox', { name: 'Release version' })).not.toBeInTheDocument();
  });

  it('validates the version with the shared release contract and focuses actionable feedback', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(currentUser()));
    renderPage();
    const input = await screen.findByRole('textbox', { name: 'Release version' });
    fireEvent.change(input, { target: { value: 'bad version' } });
    fireEvent.click(screen.getByRole('button', { name: 'Generate and publish snapshot' }));

    const alert = screen.getByRole('alert');
    expect(alert).toHaveFocus();
    expect(alert).toHaveTextContent('Use 1â€“64 letters, numbers, dots, underscores, or hyphens');
    expect(input).toHaveAttribute('aria-invalid', 'true');
  });

  it('prevents duplicate submission and presents the published release metadata and links', async () => {
    let resolveRelease!: (value: Response) => void;
    const releaseRequest = new Promise<Response>((resolve) => {
      resolveRelease = resolve;
    });
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(currentUser())
      .mockReturnValueOnce(releaseRequest);
    vi.stubGlobal('fetch', fetchMock);
    renderPage();
    const input = await screen.findByRole('textbox', { name: 'Release version' });
    fireEvent.change(input, { target: { value: ' 2026.09.2 ' } });
    const submit = screen.getByRole('button', { name: 'Generate and publish snapshot' });
    fireEvent.click(submit);
    expect(screen.getByRole('button', { name: 'Publishing releaseâ€¦' })).toBeDisabled();
    fireEvent.click(screen.getByRole('button', { name: 'Publishing releaseâ€¦' }));
    expect(fetchMock).toHaveBeenCalledTimes(2);

    resolveRelease(response(201, { data: release }));
    const status = await screen.findByRole('status');
    expect(status).toHaveFocus();
    expect(within(status).getByRole('heading', { name: 'Dataset 2026.09.2' })).toBeInTheDocument();
    expect(within(status).getByText('1 234')).toBeInTheDocument();
    expect(within(status).getByText('a'.repeat(64))).toBeInTheDocument();
    expect(within(status).getByRole('link', { name: 'View public release' })).toHaveAttribute(
      'href',
      '/dataset-releases/2026.09.2',
    );
    expect(within(status).getByRole('link', { name: 'Browse release catalogue' })).toHaveAttribute(
      'href',
      '/dataset-releases',
    );

    const [, request] = fetchMock.mock.calls[1]!;
    expect(fetchMock.mock.calls[1]?.[0]).toContain('/admin/dataset-releases');
    expect(request).toMatchObject({
      method: 'POST',
      body: JSON.stringify({ version: '2026.09.2' }),
    });
    expect((request?.headers as Headers).get('Authorization')).toBe('Bearer admin-access-token');
  });

  it('preserves the entered version and surfaces API and unexpected-response failures', async () => {
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce(currentUser())
      .mockResolvedValueOnce(
        response(403, { error: { code: 'FORBIDDEN', message: 'Release permission was revoked.' } }),
      )
      .mockResolvedValueOnce(response(201, { data: { version: 'malformed' } }));
    vi.stubGlobal('fetch', fetchMock);
    renderPage();
    const input = await screen.findByRole('textbox', { name: 'Release version' });
    fireEvent.change(input, { target: { value: '2026.09.2' } });
    fireEvent.click(screen.getByRole('button', { name: 'Generate and publish snapshot' }));
    expect(await screen.findByRole('alert')).toHaveTextContent(
      'Your signed-in account is not authorised to publish dataset releases.',
    );
    expect(input).toHaveValue('2026.09.2');

    fireEvent.click(screen.getByRole('button', { name: 'Generate and publish snapshot' }));
    await waitFor(() =>
      expect(screen.getByRole('alert')).toHaveTextContent('unexpected dataset release response'),
    );
    expect(input).toHaveValue('2026.09.2');
  });
});

