import { createHash, randomUUID } from 'node:crypto';
import { Readable } from 'node:stream';

import {
  DATASET_RELEASE_FIELDS,
  DATASET_RELEASE_FORMAT_VERSION,
  DATASET_RELEASE_SCOPE,
} from '@sport-analytics/contracts';
import type { ObjectStore } from '@sport-analytics/object-storage';
import type { Pool, PoolClient } from 'pg';

import { PermanentJobError, type ReceivedJob } from './delivery-pump';
import type { Logger } from './logger';

const PAGE_SIZE = 10_000;

interface Cursor {
  fixtureId: string;
  inningsOrdinal: number;
  sequenceNumber: number;
  eventId: string;
}
interface EventRow extends Cursor {
  event: unknown;
}
interface Claim {
  terminal: boolean;
  attemptCount: number;
  maxAttempts: number;
  previousKey: string | null;
}
interface Command {
  type: 'dataset-release.generate';
  version: 1;
  jobId: string;
  releaseVersion: string;
  deploymentEnvironment: string;
}

class LeaseBusyError extends Error {}

async function transaction<T>(
  database: Pool,
  operation: (client: PoolClient) => Promise<T>,
): Promise<T> {
  const client = await database.connect();
  try {
    await client.query('BEGIN');
    const result = await operation(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK').catch(() => undefined);
    throw error;
  } finally {
    client.release();
  }
}

function parseCommand(message: ReceivedJob): Command {
  const body = message.body as Partial<Command> | null;
  if (
    !body ||
    body.type !== 'dataset-release.generate' ||
    body.version !== 1 ||
    typeof body.jobId !== 'string' ||
    typeof body.releaseVersion !== 'string' ||
    typeof body.deploymentEnvironment !== 'string'
  ) {
    throw new PermanentJobError('UnsupportedJobContract', 'Dataset release command is invalid.');
  }
  return body as Command;
}

export function createDatasetReleaseJobHandler(
  database: Pool,
  objectStore: ObjectStore,
  logger: Logger,
  options: {
    workerId: string;
    leaseMs: number;
    deploymentEnvironment: string;
    storageProvider: 'azure' | 'filesystem';
    pageSize?: number;
  },
) {
  const pageSize = options.pageSize ?? PAGE_SIZE;

  async function claim(command: Command): Promise<Claim> {
    if (command.deploymentEnvironment !== options.deploymentEnvironment) {
      throw new PermanentJobError(
        'DeploymentEnvironmentMismatch',
        'Dataset release command belongs to another deployment environment.',
      );
    }
    return transaction(database, async (client) => {
      const result = await client.query<{
        state: string;
        attemptCount: number;
        maxAttempts: number;
        leaseOwner: string | null;
        leaseExpiresAt: Date | null;
        storageProvider: string;
        attemptStorageKey: string | null;
      }>(
        `
        SELECT j.state::text,j.attempt_count AS "attemptCount",j.max_attempts AS "maxAttempts",
          drj.lease_owner AS "leaseOwner",drj.lease_expires_at AS "leaseExpiresAt",
          drj.storage_provider AS "storageProvider",drj.attempt_storage_key AS "attemptStorageKey"
        FROM background_job j INNER JOIN dataset_release_job drj ON drj.job_id=j.job_id
        WHERE j.job_id=$1::uuid AND j.job_type='dataset-release.generate' AND j.contract_version=1
          AND drj.requested_version=$2 AND drj.deployment_environment=$3
        FOR UPDATE OF j,drj`,
        [command.jobId, command.releaseVersion, command.deploymentEnvironment],
      );
      const row = result.rows[0];
      if (!row) throw new PermanentJobError('JobNotFound', 'Dataset release job does not exist.');
      if (row.storageProvider !== options.storageProvider)
        throw new PermanentJobError(
          'StorageProviderMismatch',
          'Dataset release job storage provider does not match this worker.',
        );
      if (row.state === 'succeeded')
        return {
          terminal: true,
          attemptCount: row.attemptCount,
          maxAttempts: row.maxAttempts,
          previousKey: null,
        };
      if (!['queued', 'running', 'failed'].includes(row.state))
        throw new PermanentJobError('JobNotRunnable', 'Dataset release job is not runnable.');
      if (
        row.leaseOwner &&
        row.leaseOwner !== options.workerId &&
        row.leaseExpiresAt &&
        row.leaseExpiresAt.getTime() > Date.now()
      )
        throw new LeaseBusyError();
      if (row.attemptCount >= row.maxAttempts)
        throw new PermanentJobError(
          'AttemptBudgetExhausted',
          'Dataset release retry budget is exhausted.',
        );
      const attemptCount = row.attemptCount + 1;
      await client.query(
        `UPDATE background_job SET state='running',attempt_count=$2,started_at=COALESCE(started_at,now()),completed_at=NULL,last_error_code=NULL,last_error_message=NULL WHERE job_id=$1::uuid`,
        [command.jobId, attemptCount],
      );
      await client.query(
        `UPDATE dataset_release_job SET events_processed=0,bytes_written=0,page_number=0,last_fixture_id=NULL,last_innings_ordinal=NULL,last_sequence_number=NULL,last_event_id=NULL,lease_owner=$2,lease_expires_at=now()+($3::integer*interval '1 millisecond'),attempt_storage_key=NULL WHERE job_id=$1::uuid`,
        [command.jobId, options.workerId, options.leaseMs],
      );
      return {
        terminal: false,
        attemptCount,
        maxAttempts: row.maxAttempts,
        previousKey: row.attemptStorageKey,
      };
    });
  }

  async function loadPage(
    cursor: Cursor | null,
  ): Promise<{ events: unknown[]; next: Cursor | null }> {
    const predicate = cursor
      ? `WHERE (i.fixture_id,i.ordinal)>=($1::bigint,$2::integer) AND (i.fixture_id,i.ordinal,d.innings_sequence,d.delivery_id)>($1::bigint,$2::integer,$3::integer,$4::bigint)`
      : '';
    const params = cursor
      ? [cursor.fixtureId, cursor.inningsOrdinal, cursor.sequenceNumber, cursor.eventId, pageSize]
      : [pageSize];
    const limit = cursor ? '$5' : '$1';
    const result = await database.query<EventRow>(
      `SELECT json_build_object(
      'eventId',d.delivery_id::text,'fixtureId',i.fixture_id::text,'inningsId',i.innings_id::text,
      'inningsOrdinal',i.ordinal,'sequenceNumber',d.innings_sequence,'overNumber',d.over_number,
      'positionInOver',d.position_in_over,'ballNumber',d.ball_number,'strikerParticipantId',d.striker_id::text,
      'nonStrikerParticipantId',d.non_striker_id::text,'bowlerParticipantId',d.bowler_id::text,
      'runsOffBat',d.runs_off_bat,'runsExtras',d.runs_extras,'runsTotal',d.runs_total) AS event,
      i.fixture_id::text AS "fixtureId",i.ordinal AS "inningsOrdinal",d.innings_sequence AS "sequenceNumber",d.delivery_id::text AS "eventId"
      FROM delivery_current d INNER JOIN innings i ON i.innings_id=d.innings_id
      INNER JOIN submission s ON s.submission_id=d.submission_id AND s.status='accepted'
      ${predicate} ORDER BY i.fixture_id,i.ordinal,d.innings_sequence,d.delivery_id LIMIT ${limit}`,
      params,
    );
    const last = result.rows.at(-1);
    return {
      events: result.rows.map((row) => row.event),
      next: last
        ? {
            fixtureId: last.fixtureId,
            inningsOrdinal: last.inningsOrdinal,
            sequenceNumber: last.sequenceNumber,
            eventId: last.eventId,
          }
        : null,
    };
  }

  async function updateProgress(
    jobId: string,
    cursor: Cursor | null,
    events: number,
    bytes: number,
    page: number,
  ) {
    const result = await database.query(
      `UPDATE dataset_release_job SET events_processed=$3,bytes_written=$4,page_number=$5,last_fixture_id=$6::bigint,last_innings_ordinal=$7,last_sequence_number=$8,last_event_id=$9::bigint,lease_expires_at=now()+($10::integer*interval '1 millisecond') WHERE job_id=$1::uuid AND lease_owner=$2`,
      [
        jobId,
        options.workerId,
        events,
        bytes,
        page,
        cursor?.fixtureId ?? null,
        cursor?.inningsOrdinal ?? null,
        cursor?.sequenceNumber ?? null,
        cursor?.eventId ?? null,
        options.leaseMs,
      ],
    );
    if (result.rowCount !== 1) throw new LeaseBusyError();
    await database.query(`UPDATE background_job SET progress_current=$2 WHERE job_id=$1::uuid`, [
      jobId,
      events,
    ]);
  }

  async function markFailed(
    jobId: string,
    attemptCount: number,
    maxAttempts: number,
    error: unknown,
    artifactCleaned = true,
  ) {
    const permanent = attemptCount >= maxAttempts;
    const code =
      error instanceof LeaseBusyError
        ? 'LeaseBusy'
        : error instanceof Error
          ? error.name
          : 'GenerationFailed';
    const message =
      error instanceof LeaseBusyError
        ? 'Another worker owns the active generation lease.'
        : 'Dataset release generation failed; see safe worker progress logs.';
    await database.query(
      `UPDATE background_job SET state=$2::background_job_state,completed_at=CASE WHEN $2='dead_lettered' THEN now() ELSE NULL END,last_error_code=$3,last_error_message=$4 WHERE job_id=$1::uuid AND state<>'succeeded'`,
      [jobId, permanent ? 'dead_lettered' : 'failed', code, message],
    );
    await database.query(
      `UPDATE dataset_release_job SET lease_owner=NULL,lease_expires_at=NULL,attempt_storage_key=CASE WHEN $3 THEN NULL ELSE attempt_storage_key END WHERE job_id=$1::uuid AND lease_owner=$2`,
      [jobId, options.workerId, artifactCleaned],
    );
    if (permanent) throw new PermanentJobError('AttemptBudgetExhausted', message);
  }

  async function handler(message: ReceivedJob, signal: AbortSignal): Promise<void> {
    const command = parseCommand(message);
    const started = Date.now();
    const claimed = await claim(command);
    if (claimed.terminal) return;
    if (claimed.previousKey) {
      try {
        await objectStore.delete(claimed.previousKey);
      } catch (error) {
        await markFailed(command.jobId, claimed.attemptCount, claimed.maxAttempts, error, false);
        throw error;
      }
    }
    const storageKey = `${randomUUID()}.json`;
    await database.query(
      `UPDATE dataset_release_job SET attempt_storage_key=$2 WHERE job_id=$1::uuid AND lease_owner=$3`,
      [command.jobId, storageKey, options.workerId],
    );
    let events = 0,
      bytes = 0,
      page = 0;
    const hash = createHash('sha256');
    const emit = (value: string) => {
      const chunk = Buffer.from(value);
      hash.update(chunk);
      bytes += chunk.length;
      return chunk;
    };
    async function* artifact() {
      yield emit(
        `{"formatVersion":${JSON.stringify(DATASET_RELEASE_FORMAT_VERSION)},"scope":${JSON.stringify(DATASET_RELEASE_SCOPE)},"fields":${JSON.stringify(DATASET_RELEASE_FIELDS)},"events":[`,
      );
      let cursor: Cursor | null = null;
      let first = true;
      while (true) {
        if (signal.aborted) throw new Error('Dataset release generation was interrupted.');
        page += 1;
        logger.info('Dataset release database page read started.', {
          jobId: command.jobId,
          releaseVersion: command.releaseVersion,
          pageNumber: page,
          eventsProcessed: events,
          bytesWritten: bytes,
        });
        const loaded = await loadPage(cursor);
        for (const event of loaded.events) {
          const serialized = JSON.stringify(event);
          if (serialized === undefined)
            throw new Error('A published dataset event could not be serialized.');
          yield emit(`${first ? '' : ','}${serialized}`);
          first = false;
          events += 1;
        }
        cursor = loaded.next;
        await updateProgress(command.jobId, cursor, events, bytes, page);
        logger.info('Dataset release database page read completed.', {
          jobId: command.jobId,
          releaseVersion: command.releaseVersion,
          pageNumber: page,
          eventsProcessed: events,
          bytesWritten: bytes,
          lastFixtureId: cursor?.fixtureId,
          lastInningsOrdinal: cursor?.inningsOrdinal,
          lastSequenceNumber: cursor?.sequenceNumber,
          lastEventId: cursor?.eventId,
          elapsedMs: Date.now() - started,
        });
        if (loaded.events.length < pageSize || !cursor) break;
      }
      yield emit(']}');
    }
    const source = Readable.from(artifact());
    try {
      logger.info('Dataset release artifact write started.', {
        jobId: command.jobId,
        releaseVersion: command.releaseVersion,
      });
      const stored = await objectStore.write(storageKey, source);
      const checksum = hash.digest('hex');
      logger.info('Dataset release artifact write completed.', {
        jobId: command.jobId,
        releaseVersion: command.releaseVersion,
        eventsProcessed: events,
        bytesWritten: bytes,
        elapsedMs: Date.now() - started,
      });
      const created = await transaction(database, async (client) => {
        await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [
          `dataset-release:${command.deploymentEnvironment}:${command.releaseVersion}`,
        ]);
        const inserted = await client.query<{ releaseId: string }>(
          `INSERT INTO dataset_release (version,deployment_environment,format_version,scope,event_count,fields,artifact_storage_key,artifact_provider_version_id,artifact_storage_provider,artifact_storage_location,checksum_sha256) VALUES ($1,$2,$3,$4,$5,$6::jsonb,$7,$8,$9,'release',$10) ON CONFLICT (deployment_environment,version) DO NOTHING RETURNING release_id::text AS "releaseId"`,
          [
            command.releaseVersion,
            command.deploymentEnvironment,
            DATASET_RELEASE_FORMAT_VERSION,
            DATASET_RELEASE_SCOPE,
            events,
            JSON.stringify(DATASET_RELEASE_FIELDS),
            storageKey,
            stored.versionId,
            options.storageProvider,
            checksum,
          ],
        );
        let releaseId = inserted.rows[0]?.releaseId;
        if (!releaseId)
          releaseId = (
            await client.query<{ releaseId: string }>(
              `SELECT release_id::text AS "releaseId" FROM dataset_release WHERE deployment_environment=$1 AND version=$2`,
              [command.deploymentEnvironment, command.releaseVersion],
            )
          ).rows[0]!.releaseId;
        await client.query(
          `UPDATE dataset_release_job SET release_id=$2::uuid,events_processed=$3,bytes_written=$4,page_number=$5,lease_owner=NULL,lease_expires_at=NULL,attempt_storage_key=NULL WHERE job_id=$1::uuid`,
          [command.jobId, releaseId, events, bytes, page],
        );
        await client.query(
          `UPDATE background_job SET state='succeeded',progress_current=$2,progress_total=$2,completed_at=now(),last_error_code=NULL,last_error_message=NULL WHERE job_id=$1::uuid`,
          [command.jobId, events],
        );
        return Boolean(inserted.rows[0]);
      });
      if (!created) await objectStore.delete(storageKey).catch(() => undefined);
      logger.info('Dataset release metadata persisted.', {
        jobId: command.jobId,
        releaseVersion: command.releaseVersion,
        eventsProcessed: events,
        bytesWritten: bytes,
        elapsedMs: Date.now() - started,
      });
    } catch (error) {
      source.destroy();
      let artifactCleaned = true;
      try {
        await objectStore.delete(storageKey);
      } catch {
        artifactCleaned = false;
      }
      logger.error('Dataset release generation failed and cleanup was attempted.', {
        jobId: command.jobId,
        releaseVersion: command.releaseVersion,
        pageNumber: page,
        eventsProcessed: events,
        bytesWritten: bytes,
        elapsedMs: Date.now() - started,
        errorName: error instanceof Error ? error.name : 'UnknownError',
      });
      await markFailed(
        command.jobId,
        claimed.attemptCount,
        claimed.maxAttempts,
        error,
        artifactCleaned,
      );
      throw error;
    }
  }
  return { handler };
}

import { randomUUID } from 'node:crypto';
import type { Pool } from 'pg';

import { executeQuery, getDatabasePool, type QueryExecutor, withTransaction } from '../../database';

export interface DatasetReleaseSnapshot {
  releaseId: string;
  version: string;
  createdAt: string;
  eventCount: number;
  checksum: string;
}

export interface DatasetReleaseEventCursor {
  fixtureId: string;
  inningsOrdinal: number;
  sequenceNumber: number;
  eventId: string;
}

interface DatasetReleaseEventPage {
  events: unknown[];
  nextCursor: DatasetReleaseEventCursor | null;
}

export interface DatasetReleaseArtifactReference {
  storageKey: string | null;
  legacyArtifactText: string | null;
  storageLocation: 'release' | null;
}

export interface DatasetReleaseJobRecord {
  jobId: string;
  version: string;
  state: 'queued' | 'running' | 'succeeded' | 'failed' | 'dead_lettered' | 'cancelled';
  eventsProcessed: number;
  bytesWritten: number;
  pageNumber: number;
  createdAt: string;
  startedAt: string | null;
  completedAt: string | null;
  failureCode: string | null;
  failureMessage: string | null;
  release: DatasetReleaseSnapshot | null;
}

interface DatasetReleaseRow extends DatasetReleaseSnapshot {
  artifactStorageKey?: string | null;
  artifactText?: string | null;
  artifactStorageLocation?: 'release' | null;
}

interface DatasetReleaseEventRow extends DatasetReleaseEventCursor {
  event: unknown;
}

interface DatasetReleaseJobRow {
  jobId: string;
  version: string;
  state: DatasetReleaseJobRecord['state'];
  eventsProcessed: string;
  bytesWritten: string;
  pageNumber: number;
  createdAt: string;
  startedAt: string | null;
  completedAt: string | null;
  failureCode: string | null;
  failureMessage: string | null;
  releaseId: string | null;
  releaseVersion: string | null;
  releaseCreatedAt: string | null;
  releaseEventCount: number | null;
  releaseChecksum: string | null;
}

export interface DatasetReleaseRepository {
  loadPublishedEventPage(
    cursor: DatasetReleaseEventCursor | null,
    limit: number,
  ): Promise<DatasetReleaseEventPage>;
  requestGeneration(input: {
    version: string;
    requesterId: string;
    deploymentEnvironment: string;
    storageProvider: 'azure' | 'filesystem';
  }): Promise<{ release: DatasetReleaseSnapshot | null; job: DatasetReleaseJobRecord | null }>;
  findJob(jobId: string, deploymentEnvironment: string): Promise<DatasetReleaseJobRecord | null>;
  list(deploymentEnvironment: string): Promise<DatasetReleaseSnapshot[]>;
  findByVersion(
    version: string,
    deploymentEnvironment: string,
  ): Promise<DatasetReleaseSnapshot | null>;
  findArtifactReferenceByVersion(
    version: string,
    deploymentEnvironment: string,
  ): Promise<DatasetReleaseArtifactReference | null>;
}

const snapshotColumns = `release_id::text AS "releaseId", version, created_at::text AS "createdAt", event_count AS "eventCount", checksum_sha256 AS checksum`;

function mapJob(row: DatasetReleaseJobRow): DatasetReleaseJobRecord {
  return {
    jobId: row.jobId,
    version: row.version,
    state: row.state,
    eventsProcessed: Number(row.eventsProcessed),
    bytesWritten: Number(row.bytesWritten),
    pageNumber: row.pageNumber,
    createdAt: row.createdAt,
    startedAt: row.startedAt,
    completedAt: row.completedAt,
    failureCode: row.failureCode,
    failureMessage: row.failureMessage,
    release:
      row.releaseId &&
      row.releaseVersion &&
      row.releaseCreatedAt &&
      row.releaseEventCount !== null &&
      row.releaseChecksum
        ? {
            releaseId: row.releaseId,
            version: row.releaseVersion,
            createdAt: row.releaseCreatedAt,
            eventCount: row.releaseEventCount,
            checksum: row.releaseChecksum,
          }
        : null,
  };
}

const jobSelection = `
  j.job_id::text AS "jobId", drj.requested_version AS version, j.state,
  drj.events_processed::text AS "eventsProcessed", drj.bytes_written::text AS "bytesWritten", drj.page_number AS "pageNumber",
  j.created_at::text AS "createdAt", j.started_at::text AS "startedAt", j.completed_at::text AS "completedAt",
  j.last_error_code AS "failureCode", j.last_error_message AS "failureMessage",
  r.release_id::text AS "releaseId", r.version AS "releaseVersion", r.created_at::text AS "releaseCreatedAt",
  r.event_count AS "releaseEventCount", r.checksum_sha256 AS "releaseChecksum"
`;

export function createDatasetReleaseRepository(executor?: QueryExecutor): DatasetReleaseRepository {
  const database = () => executor ?? getDatabasePool();
  const transactionPool = () =>
    executor && 'connect' in executor ? (executor as Pool) : getDatabasePool();

  async function findByVersion(version: string, deploymentEnvironment: string) {
    const result = await executeQuery<DatasetReleaseRow>(
      database(),
      `SELECT ${snapshotColumns} FROM dataset_release WHERE deployment_environment=$1 AND version=$2`,
      [deploymentEnvironment, version],
    );
    return result.rows[0] ?? null;
  }

  async function findJobOn(target: QueryExecutor, jobId: string, deploymentEnvironment: string) {
    const result = await executeQuery<DatasetReleaseJobRow>(
      target,
      `SELECT ${jobSelection} FROM dataset_release_job drj INNER JOIN background_job j ON j.job_id=drj.job_id LEFT JOIN dataset_release r ON r.release_id=drj.release_id WHERE drj.job_id=$1::uuid AND drj.deployment_environment=$2`,
      [jobId, deploymentEnvironment],
    );
    return result.rows[0] ? mapJob(result.rows[0]) : null;
  }

  return {
    async loadPublishedEventPage(cursor, limit) {
      const cursorPredicate = cursor
        ? `WHERE (i.fixture_id, i.ordinal) >= ($1::bigint, $2::integer)
             AND (i.fixture_id, i.ordinal, d.innings_sequence, d.delivery_id) > ($1::bigint, $2::integer, $3::integer, $4::bigint)`
        : '';
      const parameters = cursor
        ? [cursor.fixtureId, cursor.inningsOrdinal, cursor.sequenceNumber, cursor.eventId, limit]
        : [limit];
      const limitParameter = cursor ? '$5' : '$1';
      const result = await executeQuery<DatasetReleaseEventRow>(
        database(),
        `
        SELECT json_build_object(
          'eventId', d.delivery_id::text, 'fixtureId', i.fixture_id::text, 'inningsId', i.innings_id::text,
          'inningsOrdinal', i.ordinal, 'sequenceNumber', d.innings_sequence, 'overNumber', d.over_number,
          'positionInOver', d.position_in_over, 'ballNumber', d.ball_number,
          'strikerParticipantId', d.striker_id::text, 'nonStrikerParticipantId', d.non_striker_id::text,
          'bowlerParticipantId', d.bowler_id::text, 'runsOffBat', d.runs_off_bat,
          'runsExtras', d.runs_extras, 'runsTotal', d.runs_total
        ) AS event,
        i.fixture_id::text AS "fixtureId", i.ordinal AS "inningsOrdinal",
        d.innings_sequence AS "sequenceNumber", d.delivery_id::text AS "eventId"
        FROM delivery_current d
        INNER JOIN innings i ON i.innings_id=d.innings_id
        INNER JOIN submission s ON s.submission_id=d.submission_id AND s.status='accepted'
        ${cursorPredicate}
        ORDER BY i.fixture_id, i.ordinal, d.innings_sequence, d.delivery_id
        LIMIT ${limitParameter}`,
        parameters,
      );
      const last = result.rows.at(-1);
      return {
        events: result.rows.map((row) => row.event),
        nextCursor: last
          ? {
              fixtureId: last.fixtureId,
              inningsOrdinal: last.inningsOrdinal,
              sequenceNumber: last.sequenceNumber,
              eventId: last.eventId,
            }
          : null,
      };
    },

    async requestGeneration(input) {
      return withTransaction(transactionPool(), async (client) => {
        await executeQuery(client, `SELECT pg_advisory_xact_lock(hashtext($1))`, [
          `dataset-release:${input.deploymentEnvironment}:${input.version}`,
        ]);
        const existingRelease = await executeQuery<DatasetReleaseRow>(
          client,
          `SELECT ${snapshotColumns} FROM dataset_release WHERE deployment_environment=$1 AND version=$2`,
          [input.deploymentEnvironment, input.version],
        );
        if (existingRelease.rows[0]) return { release: existingRelease.rows[0], job: null };

        const existingJob = await executeQuery<{
          jobId: string;
          state: DatasetReleaseJobRecord['state'];
        }>(
          client,
          `SELECT j.job_id::text AS "jobId", j.state FROM dataset_release_job drj INNER JOIN background_job j ON j.job_id=drj.job_id WHERE drj.deployment_environment=$1 AND drj.requested_version=$2 FOR UPDATE OF j, drj`,
          [input.deploymentEnvironment, input.version],
        );
        let jobId = existingJob.rows[0]?.jobId;
        if (!jobId) {
          jobId = randomUUID();
          await executeQuery(
            client,
            `INSERT INTO background_job (job_id,job_type,contract_version,idempotency_key,owner_id) VALUES ($1::uuid,'dataset-release.generate',1,$2,$3::bigint)`,
            [
              jobId,
              `dataset-release.generate:${input.deploymentEnvironment}:${input.version}`,
              input.requesterId,
            ],
          );
          await executeQuery(
            client,
            `INSERT INTO dataset_release_job (job_id,requested_version,deployment_environment,storage_provider) VALUES ($1::uuid,$2,$3,$4)`,
            [jobId, input.version, input.deploymentEnvironment, input.storageProvider],
          );
        } else if (['failed', 'dead_lettered'].includes(existingJob.rows[0]!.state)) {
          await executeQuery(
            client,
            `UPDATE background_job SET state='queued',progress_current=0,progress_total=NULL,attempt_count=0,started_at=NULL,completed_at=NULL,last_error_code=NULL,last_error_message=NULL WHERE job_id=$1::uuid`,
            [jobId],
          );
          await executeQuery(
            client,
            `UPDATE dataset_release_job SET events_processed=0,bytes_written=0,page_number=0,last_fixture_id=NULL,last_innings_ordinal=NULL,last_sequence_number=NULL,last_event_id=NULL,lease_owner=NULL,lease_expires_at=NULL,storage_provider=$2 WHERE job_id=$1::uuid`,
            [jobId, input.storageProvider],
          );
        }

        if (
          !existingJob.rows[0] ||
          ['failed', 'dead_lettered'].includes(existingJob.rows[0].state)
        ) {
          const messageId = randomUUID();
          await executeQuery(
            client,
            `INSERT INTO outbox_message (outbox_message_id,job_id,message_type,contract_version,body) VALUES ($1::uuid,$2::uuid,'dataset-release.generate',1,jsonb_build_object('type','dataset-release.generate','version',1,'commandId',$1::text,'jobId',$2::text,'releaseVersion',$3::text,'deploymentEnvironment',$4::text))`,
            [messageId, jobId, input.version, input.deploymentEnvironment],
          );
        }
        return { release: null, job: await findJobOn(client, jobId, input.deploymentEnvironment) };
      });
    },

    findJob(jobId, deploymentEnvironment) {
      return findJobOn(database(), jobId, deploymentEnvironment);
    },
    async list(deploymentEnvironment) {
      const result = await executeQuery<DatasetReleaseRow>(
        database(),
        `SELECT ${snapshotColumns} FROM dataset_release WHERE deployment_environment=$1 ORDER BY created_at DESC,version DESC`,
        [deploymentEnvironment],
      );
      return result.rows;
    },
    findByVersion,
    async findArtifactReferenceByVersion(version, deploymentEnvironment) {
      const result = await executeQuery<DatasetReleaseRow>(
        database(),
        `SELECT artifact_storage_key AS "artifactStorageKey",artifact_text AS "artifactText",artifact_storage_location AS "artifactStorageLocation" FROM dataset_release WHERE deployment_environment=$1 AND version=$2`,
        [deploymentEnvironment, version],
      );
      const row = result.rows[0];
      return row
        ? {
            storageKey: row.artifactStorageKey ?? null,
            legacyArtifactText: row.artifactText ?? null,
            storageLocation: row.artifactStorageLocation ?? null,
          }
        : null;
    },
  };
}

import { z } from 'zod';

const optionalNonEmptyString = z.preprocess(
  (value) => (typeof value === 'string' && value.trim() === '' ? undefined : value),
  z.string().trim().min(1).optional(),
);

const environmentSchema = z
  .object({
    NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
    PORT: z.coerce.number().int().positive().max(65_535).default(3000),
    CORS_ORIGINS: z.string().default('http://localhost:5173'),
    SUPABASE_URL: z.string().trim().url('Supabase URL must be a valid URL'),
    SUPABASE_PUBLISHABLE_KEY: z.string().trim().min(1, 'Supabase publishable key is required'),
    SUPABASE_SECRET_KEY: optionalNonEmptyString,
    OBJECT_STORAGE_PROVIDER: z.enum(['azure', 'filesystem']).optional(),
    OBJECT_STORAGE_FILESYSTEM_ROOT: optionalNonEmptyString,
    DEPLOYMENT_ENVIRONMENT: z
      .string()
      .trim()
      .regex(/^[a-z0-9][a-z0-9-]{0,31}$/)
      .default('local'),
    AZURE_STORAGE_ACCOUNT_NAME: optionalNonEmptyString.pipe(
      z
        .string()
        .regex(
          /^[a-z0-9]{3,24}$/,
          'Azure storage account name must be 3-24 lowercase letters or numbers',
        )
        .optional(),
    ),
    AZURE_STORAGE_CONTAINER_NAME: optionalNonEmptyString.pipe(
      z
        .string()
        .regex(
          /^(?!.*--)[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])$/,
          'Azure storage container name must be 3-63 lowercase letters, numbers or single hyphens',
        )
        .optional(),
    ),
    AZURE_STORAGE_INGESTION_CONTAINER_NAME: optionalNonEmptyString,
    AZURE_STORAGE_RELEASE_CONTAINER_NAME: optionalNonEmptyString,
  })
  .superRefine((environment, context) => {
    if (environment.NODE_ENV === 'production') {
      if (!environment.OBJECT_STORAGE_PROVIDER) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['OBJECT_STORAGE_PROVIDER'],
          message: 'Object storage provider is required in production',
        });
      } else if (environment.OBJECT_STORAGE_PROVIDER !== 'azure') {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['OBJECT_STORAGE_PROVIDER'],
          message: 'Production object storage provider must be azure',
        });
      }
    }

    if (
      environment.OBJECT_STORAGE_PROVIDER === 'filesystem' &&
      !environment.OBJECT_STORAGE_FILESYSTEM_ROOT
    ) {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['OBJECT_STORAGE_FILESYSTEM_ROOT'],
        message: 'Filesystem object storage root is required for the filesystem provider',
      });
    }

    if (environment.OBJECT_STORAGE_PROVIDER === 'azure') {
      if (!environment.AZURE_STORAGE_ACCOUNT_NAME) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['AZURE_STORAGE_ACCOUNT_NAME'],
          message: 'Azure storage account name is required for the Azure provider',
        });
      }

      if (!environment.AZURE_STORAGE_CONTAINER_NAME) {
        if (!environment.AZURE_STORAGE_INGESTION_CONTAINER_NAME) {
          context.addIssue({
            code: z.ZodIssueCode.custom,
            path: ['AZURE_STORAGE_CONTAINER_NAME'],
            message: 'Azure storage container name is required for the Azure provider',
          });
        }
      }
      if (!environment.AZURE_STORAGE_RELEASE_CONTAINER_NAME) {
        context.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['AZURE_STORAGE_RELEASE_CONTAINER_NAME'],
          message: 'Azure release storage container name is required for the Azure provider',
        });
      }
    }

    if (environment.NODE_ENV === 'production' && environment.DEPLOYMENT_ENVIRONMENT === 'local') {
      context.addIssue({
        code: z.ZodIssueCode.custom,
        path: ['DEPLOYMENT_ENVIRONMENT'],
        message: 'Production requires a non-local deployment environment',
      });
    }
  });

export type Environment = z.infer<typeof environmentSchema>;

export function loadEnvironment(source: NodeJS.ProcessEnv = process.env): Environment {
  const result = environmentSchema.safeParse(source);

  if (!result.success) {
    const details = result.error.issues
      .map((issue) => `${issue.path.join('.') || 'environment'}: ${issue.message}`)
      .join('; ');

    throw new Error(`Invalid environment configuration: ${details}`);
  }

  return result.data;
}

