      source.destroy();
      await unlink(temporary).catch(() => undefined);
      if (published) await unlink(target).catch(() => undefined);
      if (error instanceof ObjectStorageError) throw error;
      throw new ObjectStorageError('The filesystem object write failed.');
    }
  }

